(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["生活関連"]=[{"id":"00002188","register_sub_id":"101","register_pk":"103178","name":"旧西岡水源池取水塔","kana":"きゅうにしおかすいげんちしゅすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市豊平区西岡公園内","lat":42.98645324,"lng":141.3801849,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"煉瓦及び木造、鉄板葺、建築面積1.5㎡","structure_material":"煉瓦及び木造","registered":"2001.08.28(平成13.08.28)","register_no":"01 － 0029","desc":"旧陸軍第７師団歩兵第２５連隊用として月寒川上流部に建設された水道施設。内径１．５m，高６．６mの円柱状煉瓦造基礎上に，六角形平面，下見板張，縦長窓付の木造胴体部と，六角錐形の屋根が載る。井上二郎設計。公園のシンボルとして市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002188"},{"id":"00007825","register_sub_id":"101","register_pk":"108806","name":"旧島守発電所水圧鉄管路","kana":"きゅうしまもりはつでんしょすいあつてっかんろ","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県八戸市南郷区大字島守字持金沢3","lat":40.39681487,"lng":141.48005228,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"鋼製、延長21m、土台付","structure_material":"鋼製","registered":"2009.11.02(平成21.11.02)","register_no":"02-0081","desc":"本館と水槽間に据えられた水圧鉄管路。法勾配２割２分の斜面に据えられ、下端で水平方向に屈曲する延長２１ｍ、外径１．４ｍの円筒形鉄管とコンクリート造の受台からなる。県内に現存する最古の水力発電所施設の遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007825"},{"id":"00007824","register_sub_id":"101","register_pk":"108805","name":"旧島守発電所水槽","kana":"きゅうしまもりはつでんしょすいそう","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県八戸市南郷区大字島守字持金沢3","lat":40.39666363,"lng":141.48020332,"geo_status":"db","era":"大正3／昭和30増設・昭和48改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"コンクリート造、面積190㎡","structure_material":"コンクリート造","registered":"2009.11.02(平成21.11.02)","register_no":"02-0080","desc":"本館から１６ｍ東方の高台に位置する。水車に流入する水量の調整等を行うために導水路と水圧管の接合点に築かれた、延長３３ｍ、「く」の字形平面のコンクリート構造物で、表面モルタル塗仕上げとする。余水路に接続するごみ捨路を一体化した特徴的なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007824"},{"id":"00007823","register_sub_id":"101","register_pk":"108804","name":"旧島守発電所本館","kana":"きゅうしまもりはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県八戸市南郷区大字島守字持金沢3","lat":40.39691158,"lng":141.47999629,"geo_status":"db","era":"大正3／昭和30改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"02-0079","desc":"市内を南北に貫流する新井田川の上流域に位置する。川に面する敷地に建つ桁行１３ｍ梁間７．６ｍ、切妻造妻入の木造平屋建。外装下見板張とし、縦長上下窓を配し、南妻面にはポーチを付ける。ドイツ製の横軸水車と発電機を一組残す近代水力発電所施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007823"},{"id":"00007826","register_sub_id":"101","register_pk":"108807","name":"旧島守発電所余水路","kana":"きゅうしまもりはつでんしょよすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県八戸市南郷区大字島守字持金沢3","lat":40.3969338,"lng":141.48016482,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"コンクリート造、延長53m","structure_material":"コンクリート造","registered":"2009.11.02(平成21.11.02)","register_no":"02-0082","desc":"水槽より北側に位置し、新井田川に合流する水路。余水や土砂等を川に流し出すために築かれた延長５３ｍ、台形断面とする直線状のコンクリート造構造物で、全体のうち２１ｍは暗渠とする。水力発電所施設のシステムを知る上で欠くことのできない構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007826"},{"id":"00001217","register_sub_id":"101","register_pk":"102207","name":"米内浄水場１号ろ過池調整室","kana":"よないじょうすいじょういちごうろかちちょうせいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.74487702,"lng":141.20254604,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，建築面積10㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0015","desc":"東寄りの１号濾過池に対応するバルブ操作室上屋。正方形プランのＲＣ造モルタル塗の小建築であるが、土台回り、腰回り、開口部回り、コーナーストーン、軒の持送りなど要所に大谷石を用いて装飾効果を高めている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001217"},{"id":"00001214","register_sub_id":"101","register_pk":"102204","name":"米内浄水場緩速系着水井","kana":"よないじょうすいじょうかんそくけいちゃくすいせい","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.74509956,"lng":141.20325682,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，面積17.１㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0012","desc":"昭和９年に配水を開始した盛岡市創設水道の基幹施設になる米内浄水場の東端に位置する。９．５ｍ×１．８ｍ、深さ約２ｍのＲＣ造池で、内部を３室に区画する。約１ｋｍ上流で取水され沈砂池を経て導水された水はこの池に着水し、量水の後、沈殿池に送られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001214"},{"id":"00001215","register_sub_id":"101","register_pk":"102205","name":"米内浄水場緩速沈殿池","kana":"よないじょうすいじょうかんそくちんでんち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.74546956,"lng":141.20297691,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，１号・２号沈殿池よりなる，面積1458㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0013","desc":"構内東方の一段高い造成地に着水井とともに築造され、着水井の北方に隣接して配置されている。５４ｍ×２７ｍ、有効水深３ｍのＲＣ造池で、中央に隔壁を設けて２池とする。各池は正方形平面で、側壁の内側に煉瓦を貼り、上部に笠石を置く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001215"},{"id":"00001216","register_sub_id":"101","register_pk":"102206","name":"米内浄水場緩速ろ過池","kana":"よないじょうすいじょうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.745228,"lng":141.202515,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，ろ過池面積3347㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0014","desc":"沈殿池の南に位置する。９０ｍ×３７ｍの矩形平面のＲＣ造池で、２つの隔壁により３池に等分し、１池を予備池とする。濾材として砂と砂利を敷き、側壁の内側は沈殿池と同様に煉瓦貼りとし、各池の南辺中央に調整室を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001216"},{"id":"00001219","register_sub_id":"101","register_pk":"102209","name":"米内浄水場３号ろ過池調整室","kana":"よないじょうすいじょうさんごうろかちちょうせいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.74531202,"lng":141.20212422,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，建築面積10㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0017","desc":"米内川に沿った構内敷地西辺寄りに位置する３号濾過池に対応するバルブ操作室上屋。１号・２号濾過池調整室と同規模、同意匠、同仕様の建屋で、ＪＲ山田線上米内駅に向き合う正門を入って右手に拡がる浄水場景観のアイストップ的な役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001219"},{"id":"00001220","register_sub_id":"101","register_pk":"102210","name":"米内浄水場出水井","kana":"よないじょうすいじょうしゅっすいせい","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.744568,"lng":141.202515,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，建築面積15㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0018","desc":"正門を入って左手に建つ。八角形平面の建屋で、平屋建であるが、外観上は二層構成とし、上層に濾過池調整室と同系統意匠の丸窓を配する。大谷石は、出隅部のバットレスとバンドコースに用いて、調整室とは変化をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001220"},{"id":"00001221","register_sub_id":"101","register_pk":"102211","name":"米内浄水場水道記念館","kana":"よないじょうすいじょうすいどうきねんかん","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.74454409,"lng":141.20219167,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積157㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0019","desc":"敷地南東寄り、沈殿池・濾過池など構内を見渡せる位置に建つ。創設時の管理事務所で、正面左右に翼屋を張出す凹字型プランをとる。木造平屋建、瓦葺寄棟屋根の正面中央にドーマー窓を載せる。スクラッチタイルの使用に時代的な特徴が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001221"},{"id":"00001218","register_sub_id":"101","register_pk":"102208","name":"米内浄水場２号ろ過池調整室","kana":"よないじょうすいじょうにごうろかちちょうせいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.74509684,"lng":141.20232349,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，建築面積10㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0016","desc":"濾過池の中央に位置する２号濾過池に対応するバルブ操作室上屋。１号濾過池調整室と同規模、同意匠、同仕様で、濾過池南辺の中央部に建つ。大谷石で縁取られた丸窓と小丸換気孔、半円ヴォールト屋根を重ねた濾過池側の立面は水辺に佇む小宮殿風の趣を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001218"},{"id":"00001088","register_sub_id":"101","register_pk":"102078","name":"青下隧道入口","kana":"あおしたずいどういりぐち","category":"生活関連","subcategory":"土木構造物","type_guess":"隧道","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字大原新田12-7地先","lat":38.29831477,"lng":140.69475921,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"玉石張鉄筋コンクリート造，幅6.0m，高さ3.9m","structure_material":"玉石張鉄筋コンクリート造","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0015","desc":"青下第１ダム下流側左岸に設けられた量水池より中原浄水場へ向かう延長６９６ｍの導水隧道の上口。隧道坑門は、坑口両脇の柱型やコーニス部のマチコレーション飾りにより仕上げられた丁寧な造りの石造ポータルで、坑口アーチ上部に扁額を掲げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001088"},{"id":"00001086","register_sub_id":"101","register_pk":"102076","name":"青下第１ダム","kana":"あおしただいいちだむ","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区熊ヶ根字大原道17-2地先","lat":38.29840859,"lng":140.69460021,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"コンクリート造堰堤，玉石張，副堰堤及び青下橋附属，主堰堤堤高13.4m，堤長41.8m，副堰堤堤高2.4m，堤長25.7m，青下橋長さ43.6m，幅員1.8m","structure_material":"コンクリート造堰堤","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0013","desc":"仙台市水道第一次拡張時の取水ダムで、広瀬川支流の青下川に設けられた三つのダムの内最下流のもの。堤長４１．５ｍ、堤高１３ｍの玉石コンクリート造玉石貼の越流式重力ダムで、下流側に副ダムを設け、主ダム頂上に管理用の桁橋（青下橋）を付設する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001086"},{"id":"00001087","register_sub_id":"101","register_pk":"102077","name":"青下第１ダム取水塔","kana":"あおしただいいちだむしゅすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区熊ヶ根字大原道17-2地先","lat":38.29845712,"lng":140.69476098,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造，高さ15.5m","structure_material":"鉄筋コンクリート造","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0014","desc":"第１ダム上流側左岸寄りに設置された独立塔状の鉄筋コンクリート造取水塔で、内径２．４ｍ、高さ１６．９７ｍの規模を有し、塔頂部において管理橋（青下橋）に連絡する。上中下三段の取水管より取水し、主ダム下流側左岸の量水池に導水する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001087"},{"id":"00001090","register_sub_id":"101","register_pk":"102080","name":"青下第３ダム","kana":"あおしただいさんだむ","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字前原1-2地先","lat":38.30816745,"lng":140.69101235,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"コンクリート造堰堤，玉石張，副堰堤及び管理橋附属，主堰堤堤高15.2m，堤長60.4m，副堰堤堤高2.4m，堤長27.7m，管理橋長さ15.5m，幅員1.2m","structure_material":"コンクリート造堰堤","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0017","desc":"青下第２ダムの上流に位置する。堤長６０．４ｍ、堤高１５．１５ｍ、第２貯水池との満水位差は約１８ｍ。第２ダムと同様の玉石コンクリート造玉石貼の管理橋付き越流式重力ダムであるが、泥吐出口を副ダム下流部に設けているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001090"},{"id":"00001089","register_sub_id":"101","register_pk":"102079","name":"青下第２ダム","kana":"あおしただいにだむ","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区熊ヶ根字大原道27-2地先","lat":38.30103695,"lng":140.68136393,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"コンクリート造堰堤，玉石張，副堰堤及び管理橋附属，主堰堤堤高14.4m，堤長39.2m，副堰堤堤高2.4m，堤長23.6m，管理橋長さ23.6m，幅員1.5m","structure_material":"コンクリート造堰堤","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0016","desc":"青下第１ダムの上流に位置し、堤長３９．２ｍ、堤高１６．２８ｍの規模をもつ。第１貯水池との満水位差は約１０ｍ。第１ダムと同様の玉石コンクリート造玉石貼の越流式重力ダムで、下流部に副ダムを付設する。主ダム頂部右岸側には長１４ｍの管理橋を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001089"},{"id":"00001093","register_sub_id":"101","register_pk":"102083","name":"青下ダム記念碑","kana":"あおしただむきねんひ","category":"生活関連","subcategory":"その他工作物","type_guess":"堰堤","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区熊ヶ根字大原道18地先","lat":38.30012313,"lng":140.69339854,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造，幅14.4m，奥行6.9m，高さ2.6m","structure_material":"石造","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0020","desc":"青下第１ダム右岸に至る取付通路脇の平地に設置された記念碑。地元産の石材を用い、正面に山羊頭の噴水口を設け、背面に「仙台市水道拡張工事誌」銘板を填め込む。銘板には、顧問の茂庭忠次郎、技術部長の八島明、技師の杉本宗二郎らの名が記されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001093"},{"id":"00001092","register_sub_id":"101","register_pk":"102082","name":"青下ダム旧管理事務所","kana":"あおしただむきゅうかんりじむしょ","category":"生活関連","subcategory":"建築物","type_guess":"堰堤","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区熊ヶ根字大原道18地先","lat":38.29927312,"lng":140.69485199,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建一部２階建，建築面積70㎡","structure_material":"鉄筋コンクリート造平屋建一部２階建","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0019","desc":"青下第１貯水池右岸に水源地事務所として建てられたもの。階段室を曲面状に突出させた国際様式志向の建築で、丸窓の意匠も時代性を物語る。水道拡張課建築係長鹿井清吾のもとで、菊地孝太郎（ともに仙台市工出身）が担当したと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001092"},{"id":"00001091","register_sub_id":"101","register_pk":"102081","name":"青下量水堰","kana":"あおしたりょうすいぜき","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字西原38地先","lat":38.31268141,"lng":140.68534358,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"コンクリート造堰堤，玉石張，堤高2.0m，堤長20.0m","structure_material":"コンクリート造堰堤","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0018","desc":"青下第３ダムの上流５１８ｍの地点に位置する堤長２０ｍ、堤高２ｍ、敷幅３．４ｍ堤頂幅０．６ｍの玉石コンクリート造玉石貼の小ダム。右岸近くに幅１．３７ｍ、深さ０．５ｍの切欠きを設けて常時の流水量を計量する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001091"},{"id":"00001097","register_sub_id":"101","register_pk":"102087","name":"荒巻配水池入口","kana":"あらまきはいすいちいりぐち","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区国見3-6-1地先","lat":38.27217625,"lng":140.84122971,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造，幅4.5m，高さ2.7m","structure_material":"鉄筋コンクリート造","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0024","desc":"仙台市水道創設時における配水池の中央監視廊出入口。コンクリートブロックで造られる。配水所正門の正面に位置し、市内配水の起点に当たるため、出入口のアーチとムクリアーチ状の笠石との間を葉状の浮彫で飾るなど装飾的な造りとなっているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001097"},{"id":"00016475","register_sub_id":"101","register_pk":"574837","name":"旧石巻市大街道浄水場事務所","kana":"きゅういしのまきしおおかいどうじょうすいじょうじむしょ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県石巻市尾崎字鍜治間10","lat":38.54928889,"lng":141.47053333,"geo_status":"db","era":"昭和5年頃／昭和54年改修、令和6年移築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"04 - 0244","desc":"長面浦沿岸の敷地に移築された旧大街道浄水場の事務所。木造平屋建腰折屋根のスレート葺で、南面に切妻造の玄関ポーチを設け、北面に附属屋を延ばす。外壁は下見板とする。内部は中廊下の左右に板敷の部屋を配す。地域の水道施設の歴史を伝える貴重な事務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016475"},{"id":"00001233","register_sub_id":"101","register_pk":"102223","name":"三居沢発電所","kana":"さんきょざわはつでんじょ","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県仙台市青葉区荒巻字三居沢17-1","lat":38.266979,"lng":140.840271,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建，鋼板葺，建築面積169㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"04 － 0025","desc":"東北地方最初の発電所の二代目建屋。木造平屋建、下見板貼のほぼ正方形プランの建屋で、寄棟屋根の中央部を一段高く上げて切妻屋根を架け、平の面を前面明かり取り窓とする特徴的な外観を呈す。棟札より棟梁伊藤今朝五郎、脇棟梁伊藤利三郎が判明している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001233"},{"id":"00001094","register_sub_id":"101","register_pk":"102084","name":"中原系苦地取水口","kana":"なかはらけいくちしゅすいこう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区芋沢字中田西29-1地先","lat":38.30454597,"lng":140.70584562,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"鉄筋コンクリート造，高さ8.5m","structure_material":"鉄筋コンクリート造","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0021","desc":"広瀬川の支流大倉川左岸に設けられた仙台市創設水道の取水口で、中原浄水場へ導水する。取水口は煉瓦造で造られ、煉瓦アーチと煉瓦柱型によりポータルが構成され、両翼を玉石貼コンクリート造とする。仙台市創設水道のモニュメントとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001094"},{"id":"00001095","register_sub_id":"101","register_pk":"102085","name":"中原浄水場旧管理事務所","kana":"なかはらじょうすいじょうきゅうかんりじむしょ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区芋沢字中原24地先","lat":38.28293083,"lng":140.7541194,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積74㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0022","desc":"創設時の浄水場事務所を第一次拡張時に鉄筋コンクリート造で建替えたもの。近年改装されて寄棟屋根が架けられ、外装も石目地風に改められたが、当初は陸屋根造でパラペットにスペイン瓦を載せたモダニズム色の強い建築であった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001095"},{"id":"00005237","register_sub_id":"101","register_pk":"106225","name":"今福浄水場ポンプ室","kana":"いまふくじょうすいじょうぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市今福545","lat":36.33663287,"lng":139.42927989,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造地上1階地下1階建、建築面積208㎡","structure_material":"鉄筋コンクリート造地上1階地下1階建","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0132","desc":"渡良瀬川左岸に位置する水道施設。開口部を広くとる採光に配慮した造りで，１階を吹抜けとする。丸くおさめた出隅部分や窓形状等が特徴的。正面を曲面状に張出し，柱頭部を幾何学的モチーフで飾る円柱を配するなどゼツェッシオン風意匠も取り入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005237"},{"id":"00005738","register_sub_id":"101","register_pk":"106726","name":"宇都宮市水道今市水系第六号接合井","kana":"うつのみやしすいどういまいちすいけいだいろくごうせつごうせい","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県宇都宮市上金井町635-3","lat":36.63809109,"lng":139.84926071,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"コンクリート造、面積17㎡、煉瓦造上屋付","structure_material":"コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0150","desc":"市北部に位置し，日光街道にほぼ平行して敷設された延長約２５ｋｍの送水管にかかる水圧を調節するための施設。深さ２．３ｍのコンクリート造構造物の上に，西洋城郭風意匠をあしらう八角形平面の煉瓦造上屋を建てる。宇都宮市近代化の水道施設遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005738"},{"id":"00005748","register_sub_id":"101","register_pk":"106736","name":"宇都宮市水道資料館（旧管理事務所）","kana":"うつのみやしすいどうしりょうかん（きゅうかんりじむしょ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県日光市瀬川1334-1","lat":36.72739,"lng":139.679642,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積88㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0159","desc":"宇都宮市創設水道の浄水場事務所建築。日光街道杉並木に北面する浄水場の北東部に建つ。南西隅部の円形平面の塔と下見板張外壁の太い押縁が特徴ある外観をつくり，屋根窓を載せた急傾斜の半寄棟屋根と塔のベル形ドームにより周辺で際立つ存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005748"},{"id":"00005739","register_sub_id":"101","register_pk":"106727","name":"宇都宮市水道戸祭配水場配水池","kana":"うつのみやしすいどうとまつりはいすいじょうはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県宇都宮市中戸祭町2841-2","lat":36.58484584,"lng":139.87525043,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造及びコンクリート造、面積1910㎡","structure_material":"煉瓦造及びコンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0151","desc":"市の中心部に位置する。コンクリート造の一辺３１ｍの正方形の２池を並列し，導水壁の上部に煉瓦５枚厚の連続欠円アーチで屋蓋をつくる。外壁はフランス積風の煉瓦貼とし，隅部と階段には花崗岩を用いる。宇都宮市近代化の水道施設遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005739"},{"id":"00005241","register_sub_id":"101","register_pk":"106229","name":"緑町配水場水道計量室","kana":"みどりちょうはいすいじょうすいどうけいりょうしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市緑町1-3780","lat":36.3388384,"lng":139.4355508,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積4.0㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0136","desc":"敷地の東北部に位置する，配水を計量するための施設。桁行２．５ｍ，梁間１．５ｍ規模の鉄筋コンクリート造平屋建で，四隅に配した柱形と軒蛇腹を段状に迫り出すのが特徴的。米元晋一指導のもと建設が進められた足利市創設水道施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005241"},{"id":"00005238","register_sub_id":"101","register_pk":"106226","name":"緑町配水場水道山記念館（旧事務所）","kana":"みどりちょうはいすいじょうすいどうやまきねんかん（きゅうじむしょ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市緑町1-3780","lat":36.33909207,"lng":139.43527856,"geo_status":"db","era":"昭和5／昭和9増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積200㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0133","desc":"敷地の東北隅に位置する。玄関脇の事務室の背後に応接室や貴賓室を雁行形に配する。フランス瓦を用いたハーフティンバー風の木造平屋建で，背面にはドーマー窓を設ける。外壁は腰部と上部で仕様の異なるモルタル塗洗出しとする。水道創設時の施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005238"},{"id":"00005240","register_sub_id":"101","register_pk":"106228","name":"緑町配水場接合井","kana":"みどりちょうはいすいじょうせつごうせい","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市緑町1-3780","lat":36.33862355,"lng":139.43450289,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積43㎡、塩素滅菌室付","structure_material":"鉄筋コンクリート造","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0135","desc":"今福浄水場より東方の高台に築かれた配水場の施設。敷地の西南隅に位置し，浄水場ポンプ室より配水池へ送る水を中継する。上屋は鉄筋コンクリート造で，半円アーチを四周に配し，東側に塩素滅菌室を接続する。足利市が創設した水道施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005240"},{"id":"00005239","register_sub_id":"101","register_pk":"106227","name":"緑町配水場配水池","kana":"みどりちょうはいすいじょうはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市緑町1-3780","lat":36.338848,"lng":139.434814,"geo_status":"db","era":"昭和5／昭和30頃増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積1607㎡、水位計室及び保守点検入口棟付","structure_material":"鉄筋コンクリート造","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0134","desc":"敷地の西側中央部に位置する。幅約６０ｍ，奥行約２７ｍの鉄筋コンクリート造構造物で，内部は３池に区切られる。６角平面の各隅に柱形をつくり，軒蛇腹より上部に目地付のパラペットを立ち上げた水位計室と保守・点検入口棟を，東側にほぼ左右対称に配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005239"},{"id":"00000337","register_sub_id":"101","register_pk":"101327","name":"桐生市水道局高区配水池","kana":"きりゅうしすいどうきょくこうくはいすいち","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市堤町1-2816-11","lat":36.41735694,"lng":139.33154212,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造，幅21.6m，長さ24.2m","structure_material":"鉄筋コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0016","desc":"旧配水事務所の北に位置する。正面２１．６ｍ，側面２４．２ｍ，深４．５ｍで，形式・形状ともに，浄水場調整池・低区配水池と似る。桐生市の水道施設は，元宿浄水場，堤町の高区・低区等からなる昭和初期に建設された一連の施設が良好に残る点が珍しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000337"},{"id":"00000339","register_sub_id":"101","register_pk":"101329","name":"桐生市水道局高区量水室","kana":"きりゅうしすいどうきょくこうくりょうすいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市堤町1-2816-11","lat":36.41610992,"lng":139.33162088,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造，建築面積6.2㎡","structure_material":"鉄筋コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0018","desc":"高区配水池と低区配水池との間の低区配水池寄りに位置する鉄筋コンクリート造の小規模な建物。屋根や入口に円弧状の曲線を巧みに用いる意匠やスクラッチタイルを張った腰壁等に，時代の特徴がよく表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000339"},{"id":"00000338","register_sub_id":"101","register_pk":"101328","name":"桐生市水道局低区配水池","kana":"きりゅうしすいどうきょくていくはいすいち","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市堤町1-2816-11","lat":36.41559467,"lng":139.33133419,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造，幅29.9m，長さ29.2m","structure_material":"鉄筋コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0017","desc":"高区配水池の南方に位置する。正面２９．９ｍ，側面２９．２ｍ，深４．５ｍである。元宿浄水場，堤町の高区・低区等からなる一連の施設の計画を手がけたのは，東京帝国大学の中島鋭治（大正期）・草間偉・沼田征矢（昭和期）である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000338"},{"id":"00000340","register_sub_id":"101","register_pk":"101330","name":"桐生市水道局低区量水室","kana":"きりゅうしすいどうきょくていくりょうすいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市堤町1-2816-11","lat":36.41552221,"lng":139.33271796,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造，建築面積6.2㎡","structure_material":"鉄筋コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0019","desc":"低区配水池の東方にある一段低い場所に建つ鉄筋コンクリート造の小規模な建物で，規模・形態・意匠とも高区量水室と等しい。スクラッチタイルを用いる点は，元宿浄水場の諸施設や旧配水事務所と似るが，円弧状の曲線を用いる点に独自の特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000340"},{"id":"00000342","register_sub_id":"101","register_pk":"101332","name":"桐生市立西公民館機械室（旧水道倉庫）","kana":"きりゅうしりつにしこうみんかんきかいしつ（きゅうすいどうそうこ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市永楽町2-16","lat":36.41348056,"lng":139.33672695,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積60㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0021","desc":"旧事務所の北方に隣接して建つ倉庫で，現在は公民館の機械室として使われている。鉄筋コンクリート造で伝統的な土蔵造にみせかけている。時代の流行の先端をいく意匠を用いて建設されたものが多い桐生市の水道施設のなかでひときわ異彩をはなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000342"},{"id":"00000341","register_sub_id":"101","register_pk":"101331","name":"桐生市立西公民館本館（旧水道事務所）","kana":"きりゅうしりつにしこうみんかんほんかん（きゅうすいどうじむしょ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市永楽町2-16","lat":36.41329384,"lng":139.33667668,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建，建築面積232㎡","structure_material":"鉄筋コンクリート造3階建","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0020","desc":"市街地西方に接道して建つ。建設当初は，鉄筋コンクリート造２階建で，３階は後の増築である。石張り風の目地があるモルタル壁，段差をつけた窓廻りの意匠，曲線を用いた開口部等に時代の特徴がよく表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000341"},{"id":"00000331","register_sub_id":"101","register_pk":"101321","name":"水道資料館（元宿浄水場旧事務所）","kana":"すいどうしりょうかん（もとじゅくじょうすいじょうきゅうじむしょ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市元宿町14-37","lat":36.41153836,"lng":139.32565961,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積122㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0010","desc":"桐生市の水道施設は，大正期に計画し，関東大震災の影響による一時延期の後，昭和になり再び調査を開始，昭和５年９月に工事に着手，７年４月に通水を開始している。旧事務所は浄水場敷地の東北隅に建ち，現在水道資料館と使用され広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000331"},{"id":"00000336","register_sub_id":"101","register_pk":"101326","name":"水道山記念館（旧配水事務所）","kana":"すいどうやまきねんかん（きゅうはいすいじむしょ）","category":"生活関連","subcategory":"建築物","type_guess":"記念碑","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市堤町1-5-7","lat":36.4168973,"lng":139.33138771,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建，建築面積157㎡","structure_material":"木造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0015","desc":"桐生市街の西方にある山裾に位置する。垂直線を強調した外観，外壁のスクラッチタイル等，意匠は浄水場の施設と似る。平面形式，木造タイル張りの構造，屋根のスペイン瓦等に独自の特徴がある。現在水道記念館として公開され，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000336"},{"id":"00003517","register_sub_id":"101","register_pk":"104507","name":"北甘変電所","kana":"ほっかんへんでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県富岡市一ノ宮422","lat":36.25690734,"lng":138.86096914,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積156㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"10 － 0101","desc":"鉄筋コンクリート造，２階建で，ラーメン構造だが柱型を極力見せない平滑な外観とし，外壁モルタル塗は主要部をドイツ壁風仕上に塗り分ける。各部陸屋根に高低を付け，縦長窓，アーチ型小窓を多数配し，機能的な意匠を基調としながら変化に富んだ外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003517"},{"id":"00000032","register_sub_id":"101","register_pk":"101022","name":"前橋市浄水場配水塔","kana":"まえばししじょうすいじょうはいすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県前橋市敷島町216","lat":36.41510508,"lng":139.0545378,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄骨造、高さ37.4m","structure_material":"鉄骨造","registered":"1996.12.20(平成8.12.20)","register_no":"10 － 0004","desc":"水道資料館に近接して建つ。給水塔は鉄骨造で，環状体の鉄筋コンクリート基礎に八本のラチス柱を立て水槽を支える構造になる。水槽は鋼鉄板製で，外側を断熱材で巻き更に銅板で覆っている。高さ３７．４ｍあり，地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000032"},{"id":"00000031","register_sub_id":"101","register_pk":"101021","name":"前橋市水道資料館（旧浄水構場事務所）","kana":"まえばししすいどうしりょうかん（きゅうじょうすいこうじょうじむしょ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県前橋市敷島町216","lat":36.41476545,"lng":139.05446661,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積183㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"10 － 0003","desc":"鉄筋コンクリート造２階建で，瓦葺の屋根と物見等の部分は，木造の小屋組となる。妻の片方を平面屋根とも半円形とし，２階窓枠や屋根の小窓を半円形とする特色ある外観は，広く親しまれている。平成元年度に内部を改修し，水道資料館として開館した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000031"},{"id":"00006665","register_sub_id":"101","register_pk":"107648","name":"前橋市中央児童遊園（るなぱあく）旧ラジオ塔","kana":"まえばししちゅうおうじどうゆうえん（るなぱあく）きゅうらじおとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県前橋市大手町3-16-3","lat":36.39522185,"lng":139.06350669,"geo_status":"db","era":"昭和8／昭和前期移設","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"コンクリート造一部石造、高さ4.9m","structure_material":"コンクリート造一部石造","registered":"2007.12.05(平成19.12.05)","register_no":"10 － 0247","desc":"前橋市中央児童遊園の北側中央に建つ。ラジオ放送の受信施設として日本放送協会前橋放送局開局に併せて建設された。花崗岩の基壇の上に、モルタル塗洗出し仕上げのコンクリート躯体を載せた、高さ４．９ｍの常夜灯風の構造物。わが国初期のラジオ放送関連施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006665"},{"id":"00000333","register_sub_id":"101","register_pk":"101323","name":"元宿浄水場急速濾過場","kana":"もとじゅくじょうすいじょうきゅうそくろかじょう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市元宿町14-37","lat":36.41167619,"lng":139.32502037,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積190㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0012","desc":"喞筒（ポンプ）場の西北に建つ。旧事務所・喞筒場と類似する意匠になるが，スクラッチタイルを用いない点が異なる。入口のある中央部に向かって順次高く前方に出る形にして，中央部を強調した左右対称のひときわ目立つ特異な外観に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000333"},{"id":"00000335","register_sub_id":"101","register_pk":"101325","name":"元宿浄水場接合井","kana":"もとじゅくじょうすいじょうせつごうせい","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市元宿町14-37","lat":36.4112532,"lng":139.32516533,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造，外径3.9m","structure_material":"鉄筋コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0014","desc":"喞筒場の南方に隣接して位置する。内径３．５ｍ，深１１．１ｍの大規模な井戸で，地上に円形の低い壁を立ち上げる。壁の仕上げを石造風の目地をつけたモルタル塗りとし，上部に石製の笠木を据える等，簡素ながら丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000335"},{"id":"00000334","register_sub_id":"101","register_pk":"101324","name":"元宿浄水場調整池","kana":"もとじゅくじょうすいじょうちょうせいち","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市元宿町14-37","lat":36.41129598,"lng":139.32536969,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造，幅15.2m，長さ21.1m","structure_material":"鉄筋コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0013","desc":"喞筒場の東にある。正面１５．２ｍ，側面２１．１ｍ，深さ３．０ｍで，東北隅に石造の階段があり，上部に換気口等を均等に配列する。旧事務所，喞筒場等と同時期に建設されたもので，桐生市の生活の近代化を示す施設のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000334"},{"id":"00000332","register_sub_id":"101","register_pk":"101322","name":"元宿浄水場喞筒室","kana":"もとじゅくじょうすいじょうぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市元宿町14-37","lat":36.41141717,"lng":139.32521285,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積280㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0011","desc":"旧事務所の西南に建つ鉄筋コンクリート造，平屋建の施設。旧事務所と類似した意匠になる建物で，縦長の窓や柱形を使うことによって垂直線を強調した外観，外壁のスクラッチタイル，入口庇の装飾等に時代の特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000332"},{"id":"00001901","register_sub_id":"101","register_pk":"102891","name":"児玉町旧配水塔","kana":"こだままちきゅうはいすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県本庄市児玉町児玉323-2","lat":36.18803255,"lng":139.13103139,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、高さ18m","structure_material":"鉄筋コンクリート造","registered":"2000.10.18(平成12.10.18)","register_no":"11 － 0025","desc":"昭和３～９年に行われた児玉町水道施設工事の一環で建設。ＲＣ造外装モルタル塗，高さ１７．５ｍの内部は揚水用ポンプ室と天井をドーム形にした筒形高架水槽からなり，入口と階段室が正面に突出する。現在は時報塔として利用。設計は県技手の宮原雄次郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001901"},{"id":"00005549","register_sub_id":"101","register_pk":"106537","name":"石岡第二発電所取水堰堤","kana":"いしおかだいにはつでんしょしゅすいえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県北茨城市中郷町石岡","lat":36.77679154,"lng":140.6805259,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長19m、堤高4.7m、取水制水門、排砂門及び一号開渠付","structure_material":"重力式コンクリート造堰堤","registered":"2006.08.03(平成18.08.03)","register_no":"08 － 0213","desc":"第一発電所本館より約１００ｍ東方に位置する水路式の水力発電所施設。堤長１９ｍ，堤高４．７ｍ規模の表面石積の重力式コンクリート造堰堤で，前面に石張の水叩を付ける。左岸には取水制水門を矩折れに配し，その背面に導水路の一部をなす開渠を連続させる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005549"},{"id":"00005552","register_sub_id":"101","register_pk":"106540","name":"石岡第二発電所水槽","kana":"いしおかだいにはつでんしょすいそう","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県北茨城市中郷町石岡","lat":36.7774316,"lng":140.68916203,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"鉄筋コンクリート造、面積64㎡","structure_material":"鉄筋コンクリート造","registered":"2006.08.03(平成18.08.03)","register_no":"08 － 0216","desc":"沈砂池の東側に接続する。長径１１ｍ，短径６ｍの楕円形平面を有する筒状の鉄筋コンクリート造構造物。頂部にスラブを架け，沈砂池との境には２門からなるストーニー式制水門を配する。南側にドレーンバルブ操作用の張出し部を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005552"},{"id":"00005550","register_sub_id":"101","register_pk":"106538","name":"石岡第二発電所沈砂池","kana":"いしおかだいにはつでんしょちんさち","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県北茨城市中郷町石岡","lat":36.77745045,"lng":140.6890052,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"鉄筋コンクリート造、面積337㎡、副水路付","structure_material":"鉄筋コンクリート造","registered":"2006.08.03(平成18.08.03)","register_no":"08 － 0214","desc":"取水堰堤の約７５０ｍ下流に位置する。長さ３０ｍ，幅９ｍのほぼ長方形平面をしたコンクリート造構造物で，表面をモルタル塗仕上げとする。山側に巡らされた副水路に排砂門を取り付け，副水路内の土砂の排出も可能とした周到なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005550"},{"id":"00005553","register_sub_id":"101","register_pk":"106541","name":"石岡第二発電所鉄管路擁壁","kana":"いしおかだいにはつでんしょてっかんろようへき","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県北茨城市中郷町石岡","lat":36.77721951,"lng":140.68945504,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"石造、延長49m","structure_material":"石造","registered":"2006.08.03(平成18.08.03)","register_no":"08 － 0217","desc":"水槽と本館を結ぶ１条の水圧鉄管に沿って築かれる。水槽下の鉄管取付部分の石積擁壁と，余水路及び道路の隣接部など補強が必要とされる箇所に，鉄管と平行に築かれた擁壁からなる。総延長４９ｍとし，花崗岩を用いた谷積で築かれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005553"},{"id":"00005554","register_sub_id":"101","register_pk":"106542","name":"石岡第二発電所本館","kana":"いしおかだいにはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県北茨城市中郷町石岡69-1","lat":36.77672245,"lng":140.68986033,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積175㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"08 － 0218","desc":"大北川に面する敷地に，川と平行して建つ。桁行１８ｍ，梁間１０ｍ，切妻造で，小屋組はフィンクトラスとする。上部欠円アーチ形の大窓を平側に連続させリズム感のある立面とし，妻には特徴のある丸窓をあしらう。我が国初期の鉄筋コンクリート造建築物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005554"},{"id":"00005551","register_sub_id":"101","register_pk":"106539","name":"石岡第二発電所余水路","kana":"いしおかだいにはつでんしょよすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県北茨城市中郷町石岡","lat":36.77727465,"lng":140.68923122,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"石造及びコンクリート造、延長107m","structure_material":"石造及びコンクリート造","registered":"2006.08.03(平成18.08.03)","register_no":"08 － 0215","desc":"沈砂池南側壁に沿って設けられた越流式余水吐から大北川に至る，延長１０７ｍの開渠。丘の斜面に築かれる。沈砂池及び副水路の土砂排出も行い，壁面は谷積で築いた石積とし，前面一部をコンクリートで補強したつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005551"},{"id":"00004316","register_sub_id":"101","register_pk":"105306","name":"小里川発電所取水所","kana":"おざとがわはつでんしょしゅすいじょ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.80242866,"lng":140.49615926,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長20m、堤高2.1m、取水口及び石積護岸74m付","structure_material":"重力式コンクリート造堰堤","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0146","desc":"小里川電力株式会社が計画した発電所施設の取水部分で，本館の約３ｋｍ上流に位置する。堤長２０ｍ，堤高２．１ｍの重力式コンクリート造堰堤を中心として，右岸側に魚道，左岸側に制水門と排砂門を配する。小規模ながら近代的要素を全体に備えた河川構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004316"},{"id":"00004314","register_sub_id":"101","register_pk":"105304","name":"小里川発電所放水路","kana":"おざとがわはつでんしょほうすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.78541097,"lng":140.48048423,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"コンクリート造、延長142m、鉄筋コンクリート造橋及び石積護岸17m付","structure_material":"コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0144","desc":"発電所本館から流れ出る水を里川まで導く水路。くの字形平面をした長１４２ｍの開渠で，敷幅を２．７ｍ，側壁法勾配３分の谷積とし，水路端部から連続して里川に石造護岸を築く。欠円アーチの上方側壁を布積石張とした鉄筋コンクリート造管理橋が３基架かる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004314"},{"id":"00004313","register_sub_id":"101","register_pk":"105303","name":"小里川発電所本館","kana":"おざとがわはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町1284-2","lat":36.78569321,"lng":140.48127534,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積186㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0143","desc":"里美村を南北に貫流する里川の上流域に位置する発電施設。鉄筋コンクリート造平屋建，切妻造，瓦棒鉄板葺で，平側中央部に玄関ポーチを設ける。小屋組は鉄骨フィンクトラスで，内部には横軸水車と発電機を据える。軒蛇腹を段状につくり，外観に変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004313"},{"id":"00004315","register_sub_id":"101","register_pk":"105305","name":"小里川発電所余水路","kana":"おざとがわはつでんしょよすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.78743505,"lng":140.48154351,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"コンクリート造、延長281m、鉄筋コンクリート造橋付","structure_material":"コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0145","desc":"水槽からの余水を里川に導くための水路で，山の斜面の鉛直方向にほぼ一直線に穿たれる。３．６ｍ長の暗渠部分と，側壁を法勾配３分の谷積とした２７７ｍ長の開渠部分からなり，放水口近くにはスパン約１．５ｍの小規模な鉄筋コンクリート造橋を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004315"},{"id":"00004312","register_sub_id":"101","register_pk":"105302","name":"賀美発電所取水所","kana":"がみはつでんしょしゅすいじょ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市小菅町","lat":36.70188683,"lng":140.50920384,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長33m、堤高2.9m、沈砂地・取水口・導水路59m及び石積護岸99m付","structure_material":"重力式コンクリート造堰堤","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0142","desc":"茨城電気株式会社が計画した賀美発電所の取水部分で，本館から約４ｋｍ上流に位置する。堤長３３ｍ，堤高２．９ｍで堤頂部にむくりをつけた布積石張の重力式取水堰を中心に，丁寧な石材仕上が施された２門の制水門，コンクリート造沈砂池を一体的に築く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004312"},{"id":"00004311","register_sub_id":"101","register_pk":"105301","name":"賀美発電所放水路及び余水路","kana":"がみはつでんしょほうすいろおよびよすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市上深荻町","lat":36.66526263,"lng":140.52010838,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"コンクリート造、延長299m、鉄筋コンクリート造橋付","structure_material":"コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0141","desc":"発電所本館東方の欠円アーチ型放水口から里川に至る放水路と，水槽から流れ出て放水路と合流する余水路からなる。水路側壁は法勾配約３分の谷積石張で精緻に築く。里川の近くに，側壁を布積石張とした欠円アーチの鉄筋コンクリート造管理橋を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004311"},{"id":"00004310","register_sub_id":"101","register_pk":"105300","name":"賀美発電所本館","kana":"がみはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市上深荻町320","lat":36.66548194,"lng":140.52033517,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積189㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0140","desc":"久慈川水系里川の中流域に建設された水力発電施設。木造平屋建，切妻造，瓦棒鉄板葺で，外装は下見板張とする。越屋根を設け，壁面に広く開口部をとる，換気に配慮したつくり。小屋組は木造プラットトラスで，発電機室には横軸水車と発電機を一組据える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004310"},{"id":"00001241","register_sub_id":"101","register_pk":"102231","name":"旧町屋変電所","kana":"きゅうまちやへんでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県常陸太田市西河内下町1382-1","lat":36.6070416,"lng":140.53805405,"geo_status":"db","era":"明治42頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"煉瓦造平屋建，鉄板葺，建築面積191㎡","structure_material":"煉瓦造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"08 － 0014","desc":"明治４４年１月から旧太田町などに電気を供給した町屋発電所の変電施設。せいの高い切妻屋根、煉瓦造建屋の北側に棟を落とした寄棟屋根の建屋をつなげる姿形をとる。寄棟建屋部分の西面及び北面の一部を煉瓦壁で造る。県内初期発電関連施設の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001241"},{"id":"00004320","register_sub_id":"101","register_pk":"105310","name":"徳田発電所取水所","kana":"とくだはつでんしょしゅすいじょ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.81420961,"lng":140.51284669,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長12m、堤高2.0m、取水口及び石積護岸138m付","structure_material":"重力式コンクリート造堰堤","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0150","desc":"徳田発電所本館から約２ｋｍ上流に位置する。堤長１２ｍ堤高２．０ｍの重力式コンクリート造堰堤の左端に排砂門と制水門を配し，暗渠で途中の沈砂池を経て発電所水槽に水を送る。小規模ながら，水路式水力発電の仕組みを知る上で欠くことのできない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004320"},{"id":"00004318","register_sub_id":"101","register_pk":"105308","name":"徳田発電所放水路","kana":"とくだはつでんしょほうすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.79877585,"lng":140.49128801,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"コンクリート造、延長34m、鉄筋コンクリート造橋及び石積護岸33m付","structure_material":"コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0148","desc":"発電所本館下方の南西面から発する放水を里川左岸に導くための水路。３４ｍ長の開渠で，敷幅２．４ｍ，側壁を法勾配３分の谷積とし，里川に面して３３ｍ長の石積護岸を一体的に築く。水路に架かる鉄筋コンクリート造橋を含め，優れた石積技術を確認できる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004318"},{"id":"00004317","register_sub_id":"101","register_pk":"105307","name":"徳田発電所本館","kana":"とくだはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.80239684,"lng":140.49624182,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積81㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0147","desc":"里川水系発電施設の中で最上流に位置する水力発電施設で，東部電力株式会社が建設。桁行７間梁間３間半規模で，平屋建，切妻造，瓦棒鉄板葺とした小規模な木造建築物。外装は賀美発電所と同様下見板張で，小屋組は木造のキングポストトラスとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004317"},{"id":"00004319","register_sub_id":"101","register_pk":"105309","name":"徳田発電所余水路","kana":"とくだはつでんしょよすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.79895083,"lng":140.49278041,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"コンクリート造、延長254m、石積護岸11m付","structure_material":"コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0149","desc":"発電所本館の上方に位置する水槽からの余水を里川に導くための水路。２３ｍ長のコンクリート造暗渠に，側壁法勾配３分の谷積とした２３１ｍ長の開渠を連続させ，底部をモルタル塗とする。水圧鉄管路北側の斜面を直線状に貫き，放水路上流側で里川に流れ込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004319"},{"id":"00001400","register_sub_id":"101","register_pk":"102390","name":"花貫川第一発電所第3号水路橋（めがね橋）","kana":"はなぬきがわだいいちはつでんしょだいさんごうすいろきょう（めがねばし）","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県高萩市大字秋山字板木2989","lat":36.72784565,"lng":140.64270476,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"鉄筋コンクリート造2連アーチ橋、橋長77m、幅員2m","structure_material":"鉄筋コンクリート造2連アーチ橋","registered":"1999.11.18(平成11.11.18)","register_no":"08 － 0016","desc":"花貫ダムと花貫川第一発電所間の送水路の一部をなす長さ約７７ｍの水路橋。支間約２６ｍの２連ＲＣアーチからなる。スパンドレル部に位置する木造桁橋の橋脚部材を想わせる鉛直材に，我が国の橋梁分野におけるＲＣ導入初期の造形が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001400"},{"id":"00000028","register_sub_id":"101","register_pk":"101018","name":"水戸市水道低区配水塔","kana":"みとしすいどうていくはいすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県水戸市北見町126-14","lat":36.37833765,"lng":140.47562267,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造、高さ21.6m、直径11.2m","structure_material":"鉄筋コンクリート造","registered":"1996.12.20(平成8.12.20)","register_no":"08 － 0002","desc":"水戸市街の低地部分に給水を行うために建設された配水塔。設計は水道技師後藤鶴松で工事は市の直営で行われた。２階塔屋部の壁面にある浮彫彫刻や１階入口の装飾等に特徴があり，建設直後に既に水戸市の新名所として評判になる等，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000028"},{"id":"00016496","register_sub_id":"101","register_pk":"574858","name":"旧遊楽園（茂木佐公園）塔","kana":"きゅうゆうらくえん（もぎさこうえん）とう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東中町350-4","lat":35.937995,"lng":139.86641778,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造、高さ6.8m、面積1.3㎡","structure_material":"鉄筋コンクリート造","registered":"2026.02.10(令和8.02.10)","register_no":"12 - 0342","desc":"醤油醸造家が地域に開放した児童公園の中央に立つ塔。高さ六・八メートル、鉄筋コンクリート造モルタル洗出の角柱で、頂部を相輪風につくる。街灯兼時計塔で、かつて基部四面に水栓と流しを備えた。公園開設とともに野田における電力と水道の供給を示す塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016496"},{"id":"00011878","register_sub_id":"101","register_pk":"211139","name":"千葉県水道局栗山配水塔","kana":"ちばけんすいどうきょくくりやまはいすいとう","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県松戸市栗山198","lat":35.755237,"lng":139.897764,"geo_status":"db","era":"昭和12年／昭和38年・同52年・平成元年・同5年・同23年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造、内径15m、高さ32m、基礎土塁及び階段4基付","structure_material":"鉄筋コンクリート造","registered":"2017.10.27(平成29.10.27)","register_no":"12-236","desc":"昭和一五年に給水を開始した旧古ヶ崎浄水場の円筒型高架水槽。内径一五メートル、高さ三二メートルで、下部に従い緩やかに壁を厚くした耐圧構造となっている。ドーム状の屋根の塔頂部にパーゴラ風の通気口が付く。地域のランドマークとなる配水塔である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011878"},{"id":"00006264","register_sub_id":"101","register_pk":"107248","name":"千葉県水道局千葉高架水槽","kana":"ちばけんすいどうきょくちばこうかすいそう","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県千葉市中央区矢作町670","lat":35.606308,"lng":140.137741,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造、高さ30m、面積199㎡、階段付","structure_material":"鉄筋コンクリート造","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0070","desc":"ＪＲ千葉駅より約２ｋｍ東方，都川に面する水道用地に建つ高区配水用の施設。高さ３０ｍ規模の正十二角形平面の鉄筋コンクリート造構造物で，頂部に水槽を収め，躯体の北側に玄関及び階段室を設ける。高台にそびえ，地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006264"},{"id":"00011877","register_sub_id":"101","register_pk":"211124","name":"千葉県水道局千葉分場１号配水池","kana":"ちばけんすいどうきょくちぶんじょう１ごうはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県千葉市中央区矢作町670","lat":35.606434,"lng":140.138149,"geo_status":"db","era":"昭和12年／平成26年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造、内径29m、有効水深4.3m、基礎土塁及び階段4基付","structure_material":"鉄筋コンクリート造","registered":"2017.10.27(平成29.10.27)","register_no":"12-235","desc":"昭和一一年に通水された千葉県営水道創設時からの配水池。高架水槽と並ぶ。鉄筋コンクリート造半地下構造。円形の平面に矩形の弁室を張出す。アールデコ風の階段を上がると、芝張りの屋上にアールデコ風中央塔を飾る。戦前の水道施設として重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011877"},{"id":"00011646","register_sub_id":"101","register_pk":"210662","name":"松ケ丘一号型街路灯","kana":"まつがおかいちごうがたがいろとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"千葉県","address":"千葉県流山市松ケ丘二丁目330-85","lat":35.847624,"lng":139.950028,"geo_status":"db","era":"昭和32年頃／平成25年移設","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"コンクリート造、高さ4.4m","structure_material":"コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"12-0226","desc":"昭和三〇年代に開発された住宅地に、防犯等のため要所に設置された街路灯。コンクリート製、高さ四・四メートルで、フルーティングを設けるなど様式建築の柱を模し、頂部に円形電灯を置く。地域の歴史を今に伝えるのみならず、意匠的にも特徴ある街路灯。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011646"},{"id":"00007977","register_sub_id":"101","register_pk":"128809","name":"旧野方配水塔","kana":"きゅうのかたはいすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都中野区江古田1-3","lat":35.72464956,"lng":139.67485374,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、屋根コンクリートアスファルト塗、建築面積187㎡、石柵付","structure_material":"鉄筋コンクリート造","registered":"2010.01.15(平成22.01.15)","register_no":"13-0255","desc":"東京２３区北西部への配水を目的として建設。高さ３４ｍの鉄筋コンクリート造構造物で、東側に階段室、頂部に換気塔を付け、水槽周壁上部にはアーチ形窓を配する。壁体内の漏水防止用鋼板に最初期の溶接技術を用い、ドーム付円筒形水道塔としても最初期の事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007977"},{"id":"00000725","register_sub_id":"101","register_pk":"101715","name":"川島町旧配水計量室上屋","kana":"かわしまちょうきゅうはいすいけいりょうしつうわや","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町578-12","lat":35.46599524,"lng":139.57577709,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積25㎡","structure_material":"煉瓦造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"14 － 0022","desc":"横浜市水道第二次拡張の施設。同時期建設の西谷浄水場の下方に位置する。浄水場内の上屋と同様の造りであるが，場外に所在するだけに，外装には横黒・鼻黒煉瓦を用い，開口部のグリルなども装飾的にするなど格別の仕様がとられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000725"},{"id":"00015006","register_sub_id":"101","register_pk":"529284","name":"旧神奈川県営湘南水道鎌倉加圧ポンプ所","kana":"きゅうかながわけんえいしょうなんすいどうかまくらかあつぽんぷじょ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市長谷四丁目527-1他","lat":35.31773056,"lng":139.53297222,"geo_status":"db","era":"昭和11年／昭和40年・令和4年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、建築面積290㎡","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2024.08.15(令和6.08.15)","register_no":"14 - 0351","desc":"大仏隧道の鎌倉口に建ち、上水を加圧送水したポンプ所。鉄筋コンクリート造平屋建、外壁スクラッチタイル貼、腰を人造石とし縦長窓と単窓を並べる。内部は矩形平面で北寄りを二層とし、階段廻りを幾何学的意匠で飾る。簡明な構成で入口等要所の意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015006"},{"id":"00000724","register_sub_id":"101","register_pk":"101714","name":"旧横浜居留地煉瓦造下水道マンホール","kana":"きゅうよこはまきょりゅうちれんがづくりげすいどうまんほーる","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県横浜市中区日本大通","lat":35.44772604,"lng":139.64394254,"geo_status":"db","era":"明治14～16","year":1881,"year_source":"converted","year_min":1881,"year_max":1881,"year_label":null,"structure":"外径長4.0m，外径幅3.2m，沈殿槽部深さ2.1m，前後卵形管総延長41.5m附属","structure_material":"外径長4.0m","registered":"1998.09.02(平成10.09.02)","register_no":"14 － 0021","desc":"明治初年のブラントン設計による陶管下水道を煉瓦造に改造した際の施設。当時神奈川県御用掛の三田善太郎が計画にあたる。日本人の計画になる最初の近代下水道遺構として貴重。２本の中下水卵型管を接続する。大桟橋入口の開港広場に保存展示されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000724"},{"id":"00004730","register_sub_id":"101","register_pk":"105720","name":"横須賀市上下水道局逸見浄水場緩速ろ過池調整室Ⅰ","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうかんそくろかちちょうせいしついち","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27837156,"lng":139.64811787,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積17㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0111","desc":"横須賀市中心部より西方に位置する水道施設。ほぼ南北に４基配された緩速ろ過池のうち，北端に位置する一号ろ過池に附属する調整室。アングル材を用いて組み上げられた鉄骨を，梁間方向に３基並べ，鉄筋コンクリート造スラブを支える珍しい構造形式をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004730"},{"id":"00004877","register_sub_id":"101","register_pk":"105867","name":"横須賀市上下水道局逸見浄水場緩速ろ過池調整室Ⅲ","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうかんそくろかちちょうせいしつさん","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27790266,"lng":139.64795837,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積17㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0113","desc":"調整室Ⅱの約２０ｍ南側に位置する。明治４５年２月から大正１０年３月にかけて実施された横須賀軍用水道拡張工事の一環として建設。他３棟と同様に，鉄筋コンクリート技術が確立される前の，形式に囚われない構法が見所。水道拡張工事の計画指導は石黒弘毅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004877"},{"id":"00004876","register_sub_id":"101","register_pk":"105866","name":"横須賀市上下水道局逸見浄水場緩速ろ過池調整室Ⅱ","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうかんそくろかちちょうせいしつに","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27813585,"lng":139.64803134,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積17㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0112","desc":"調整室Ⅰの約２０ｍ南側に位置する。緩速ろ過池の西辺に隣接してたち，配水池に至るろ過水の水量調節するバルブ等をおさめる。桁行４．６ｍ，梁間３．７ｍの規模を有する，鉄筋コンクリート造平屋建，銅板葺，妻入で，他の調整室と同様の構造形式とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004876"},{"id":"00004878","register_sub_id":"101","register_pk":"105868","name":"横須賀市上下水道局逸見浄水場緩速ろ過池調整室Ⅳ","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうかんそくろかちちょうせいしつよん","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27767824,"lng":139.64787805,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積17㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0114","desc":"調整室Ⅲの約２０ｍ南側に位置する。他３棟と同様の構造形式。基礎には花崗岩を用い，鉄筋コンクリート躯体の四周には，デザインの簡略化された柱形と幅の異なる２種類の縦長窓を密に配す。正面と背面には菱形模様に楕円を浮彫したメダイオン風の装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004878"},{"id":"00004879","register_sub_id":"101","register_pk":"105869","name":"横須賀市上下水道局逸見浄水場配水池西入口","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうはいすいちにしいりぐち","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27782357,"lng":139.64714863,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造、建築面積20㎡","structure_material":"鉄筋コンクリート造","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0116","desc":"東入口と観測路で繋がる配水池西入口の建屋。鉄筋コンクリートで築かれた，正方形平面の塔状の建造物で，浄水場のランドマーク的な構造物。開口部と内部空間を広くとる採光と換気に配慮したつくりで，デザインは，東入口と同様にセセッション風とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004879"},{"id":"00004731","register_sub_id":"101","register_pk":"105721","name":"横須賀市上下水道局逸見浄水場配水池東入口","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうはいすいちひがしいりぐち","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27769576,"lng":139.64775287,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造、建築面積20㎡","structure_material":"鉄筋コンクリート造","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0115","desc":"緩速ろ過池西方に位置する，半地下構造の配水池東側中央にたてられた鉄筋コンクリート造の建築。窓と入口のアーチ頂部に誇張されたデザインの要石形を浮彫する。直線を基調としたセセッション風の幾何学的デザインに，新たな時代の造形感覚を窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004731"},{"id":"00004732","register_sub_id":"101","register_pk":"105722","name":"横須賀市上下水道局逸見浄水場ベンチュリーメーター室","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうべんちゅりーめーたーしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27867981,"lng":139.64870999,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積18㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0117","desc":"敷地北方に位置する。逸見浄水場から，西北に約５３ｋｍ離れた半原水源地より導かれた原水の流量を計測するために築かれる。桁行４．７ｍ，梁間３．８ｍの鉄筋コンクリート造平屋建で，中央に換気塔を設ける。近代水道の仕組みを今に伝える貴重な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004732"},{"id":"00001506","register_sub_id":"101","register_pk":"102496","name":"横須賀市水道局走水水源地鉄筋コンクリート造浄水池","kana":"よこすかしすいどうきょくはしりみずすいげんちてっきんこんくりーとづくりじょうすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県横須賀市走水1-1-26","lat":35.26284836,"lng":139.72273524,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"鉄筋コンクリート造、面積517㎡","structure_material":"鉄筋コンクリート造","registered":"2000.02.15(平成12.02.15)","register_no":"14 － 0030","desc":"走水水源地の第２期拡張工事で建設された上屋付き浄水池。内部は鉄筋コンクリート造の５連馬蹄形ヴォールトで構成され，外壁には石で縁取りされた丸窓を一列に配す。設計は海軍技師伊藤誠吉とされる。日本最初期の鉄筋コンクリート建造物のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001506"},{"id":"00001505","register_sub_id":"101","register_pk":"102495","name":"横須賀市水道局走水水源地煉瓦造貯水池","kana":"よこすかしすいどうきょくはしりみずすいげんちれんがづくりちょすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県横須賀市走水1-1-26","lat":35.26252479,"lng":139.72322685,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"煉瓦造、面積143㎡","structure_material":"煉瓦造","registered":"2000.02.15(平成12.02.15)","register_no":"14 － 0029","desc":"横須賀軍港水道走水水源地の第１期拡張工事で建設された上屋付き煉瓦造貯水池。内部空間を構成する扁平ヴォールトが，入口・丸窓を左右対称に配した壁面で覆われ，屋上は盛土される。横須賀鎮守府経理部建築科の海軍技師井川喜久蔵，堀池好之助らが担当。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001505"},{"id":"00000821","register_sub_id":"101","register_pk":"101811","name":"横浜市水道局青山水源事務所旧青山取水口","kana":"よこはましすいどうきょくあおやますいげんじむしょきゅうあおやましゅすいこう","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県相模原市緑区青山3482","lat":35.57816429,"lng":139.22326313,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"玉石詰鉄柵造取入堤（高さ4.6m，長さ8.2m）及び流水水門（高さ2.4m），導水鉄管２条よりなる","structure_material":"玉石詰鉄柵造取入堤（高さ4.6m","registered":"1998.10.09(平成10.10.09)","register_no":"14 － 0023","desc":"相模川左岸におけるポンプアップによる横浜創設水道(明治２０年)取水施設を廃し，取水地を道志川上流右岸に移した際の遺構。流木除けの鉄柵の内側に玉石を詰め，英国グラスゴーのレイドロー・アンド・サンズ社製の鉄管を２本立てて直接取水する構造をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000821"},{"id":"00000822","register_sub_id":"101","register_pk":"101812","name":"横浜市水道局青山水源事務所旧青山沈殿池","kana":"よこはましすいどうきょくあおやますいげんじむしょきゅうあおやまちんでんち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県相模原市緑区青山3482","lat":35.57924167,"lng":139.22313432,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"コンクリート造，長さ34.2m，幅34.2m","structure_material":"コンクリート造","registered":"1998.10.09(平成10.10.09)","register_no":"14 － 0024","desc":"横浜市水道第１次拡張時（完工は明治３４年）の遺構。旧青山取水口に対応する沈殿池で，新設の川井浄水地と既設の野毛浄水地に送水した。コンクリート造，約３０ｍ角の規模で，２池に分け，法面を玉石貼りとする（第２次拡張時に約半分に縮小）。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000822"},{"id":"00000194","register_sub_id":"101","register_pk":"101184","name":"横浜市西谷浄水場配水池配水井上屋","kana":"よこはましにしやじょうすいじょうはいすいちはいすいせいうわや","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町522","lat":35.46657072,"lng":139.57201695,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積30㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"14 － 0007","desc":"配水池を挟んで浄水井上屋と対照の位置に、これと同型同規模の配水井上屋が設けられている。建築面積は２２平方メートルと小規模な煉瓦造の建築であるが、端整な意匠の上屋として西谷浄水場の記念的存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000194"},{"id":"00000189","register_sub_id":"101","register_pk":"101179","name":"横浜市西谷浄水場濾過池整水室上屋３号棟","kana":"よこはましにしやじょうすいじょうろかちせいすいしつうわやさんごうとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町522","lat":35.46641218,"lng":139.57012011,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積13㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"14 － 0002","desc":"横浜水道第２次拡張工事により、大正４年に西谷の地に完成した水道施設の遺構の一部で、公園風に整備された浄水場のほぼ中心部に位置する。一帯は幾何学的な庭園風の構成となって保存され、浄水場の象徴的存在となっている。設計は横浜市水道臨時事業部。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000189"},{"id":"00000191","register_sub_id":"101","register_pk":"101181","name":"横浜市西谷浄水場濾過池整水室上屋７号棟","kana":"よこはましにしやじょうすいじょうろかちせいすいしつうわやななごうとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町522","lat":35.46631026,"lng":139.57015408,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積13㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"14 － 0004","desc":"整水室上屋は、４基とも内法１０フィート角の正方形平面を保つ。花崗岩切石の土台に連歌枚積みで外壁を造り、南北の向かい合わせ面に扉を開く。銅板葺の特異な宝形屋根をかけた小さいながらも建築として完結した煉瓦造の上屋として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000191"},{"id":"00000192","register_sub_id":"101","register_pk":"101182","name":"横浜市西谷浄水場濾過池整水室上屋８号棟","kana":"よこはましにしやじょうすいじょうろかちせいすいしつうわやはちごうとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町522","lat":35.46640652,"lng":139.57065802,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積13㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"14 － 0005","desc":"整水室上屋は、４基とも小規模な煉瓦造の建物で、基礎及び軒廻りを石造とし、外壁にも３筋の花崗岩の帯を入れアクセントとする。各壁面にはアーチを設けて扉口や小窓を開く。煉瓦の赤、花崗岩の白、銅板の緑が整然と配置された建物群を魅力あるものにしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000192"},{"id":"00000190","register_sub_id":"101","register_pk":"101180","name":"横浜市西谷浄水場濾過池整水室上屋４号棟","kana":"よこはましにしやじょうすいじょうろかちせいすいしつうわやよんごうとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町522","lat":35.46650278,"lng":139.57063537,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積13㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"14 － 0003","desc":"整水室は濾過池の水を浄水管で配水池に送る施設で、濾過地に対応して１基づつ造られている。上屋は４基とも昭和４８年の近代化工事で機能を失ったが、優れた場内環境を保つ上で欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000190"},{"id":"00000193","register_sub_id":"101","register_pk":"101183","name":"横浜市西谷浄水場配水池浄水井上屋","kana":"よこはましにやじょうすいじょうはいすいちじょうすいせいうわや","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町522","lat":35.46654808,"lng":139.57102606,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積22㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"14 － 0006","desc":"濾過池の東に配水池が配され、浄水井上屋と配水井上屋が設けられている。４基の整水室上屋の東西軸線の東方に建つ八角形の煉瓦造の上屋。平面が八角で規模も一回り大きいが、構造及び意匠は整水井上屋と共通し、一帯ののびやかな景観は広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000193"},{"id":"00003401","register_sub_id":"101","register_pk":"104391","name":"亀田町上水道高架水槽","kana":"かめだまちじょうすいどうこうかすいそう","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市江南区亀田水道町2-4-3","lat":37.87070497,"lng":139.11803724,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄骨造、鉄製水槽、高さ18m","structure_material":"鉄骨造","registered":"2003.07.01(平成15.07.01)","register_no":"15 － 0162","desc":"新潟市境に近い市街地東部に位置する浄水場敷地内の配水塔。山形鋼を用いた６本の鉄骨柱を正六角形平面上にたち上げ，上部に直径７．８ｍ，高さ５．４ｍの円筒槽を頂く。町の近代化を支えたランドマークで，水道タンクの名で住民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003401"},{"id":"00012309","register_sub_id":"101","register_pk":"531633","name":"旧白根配水塔","kana":"きゅうしろねはいすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県新潟市南区上下諏訪木字川原10-1","lat":37.75712778,"lng":139.00930278,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、金属板葺、直径8.1m、高さ26m","structure_material":"鉄筋コンクリート造","registered":"2018.05.10(平成30.05.10)","register_no":"15-478","desc":"昭和六年の大火を契機に建設された上水道施設の配水塔。円塔状の躯体頂部に円筒形の貯水槽を置き、円錐形の屋根をかける。内部は吹抜けで、階段と梯子を設けて貯水槽外周を廻るベランダに至る。生活基盤を支えた近代施設の象徴として市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012309"},{"id":"00009746","register_sub_id":"101","register_pk":"195575","name":"旧中島浄水場監視室棟","kana":"きゅうなかじまじょうすいじょうかんししつとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県長岡市水道町3-247-2","lat":37.45705172,"lng":138.8430925,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積57㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"15 － 0383","desc":"ポンプ室棟の南西側に建ち、略正方形平面の鉄筋コンクリート造平屋建、陸屋根である。各面中央に半円アーチを象るパラペットを立上げ、アーチ周りをドイツ壁仕上げとする。腰を石貼とし、外壁に柱形を表して石造風に目地を切り、ポンプ室棟と景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009746"},{"id":"00009745","register_sub_id":"101","register_pk":"195574","name":"旧中島浄水場ポンプ室棟","kana":"きゅうなかじまじょうすいじょうぽんぷしつとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県長岡市水道町3-247-2","lat":37.45723256,"lng":138.84324003,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積295㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"15 － 0382","desc":"Ｌ字形平面の鉄筋コンクリート造平屋建、陸屋根である。正面側は高揚ポンプ室で、中央の玄関ポーチ上に半円アーチを象るパラペットを立上げ、左右対称の立面に大オーダーを配する。腰を石貼とする石造風の重厚な外観で、要所をアールデコ意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009745"},{"id":"00009747","register_sub_id":"101","register_pk":"195576","name":"旧中島浄水場予備発電機室棟","kana":"きゅうなかじまじょうすいじょうよびはつでんきしつとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県長岡市水道町3-247-2","lat":37.45723256,"lng":138.84302588,"geo_status":"db","era":"昭和2／昭和37増築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造平屋建、金属板葺、建築面積203㎡、渡廊下付","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"15 － 0384","desc":"ポンプ室棟の西側に建ち、鉄筋コンクリート造平屋建、切妻造金属板葺である。外壁はモルタル仕上げで、パラペットを立上げて軒下に歯飾りを並べ、柱形の間には縦長窓や小窓を配してアクセントとする。ポンプ室棟と比べ装飾を抑えた外観で、景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009747"},{"id":"00008838","register_sub_id":"101","register_pk":"162281","name":"三条市水道局大崎浄水場１号・２号及び３号緩速ろ過池","kana":"さんじょうしすいどうきょくおおさきじょうすいじょういちごう・にごうおよびさんごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60834377,"lng":138.99766297,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"コンクリート造一部鉄筋コンクリート造、面積1913㎡","structure_material":"コンクリート造一部鉄筋コンクリート造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0347","desc":"事務室棟の南側に位置する。鉄筋コンクリート造、南北70.9ｍ東西28ｍ深さ2.7ｍで、三槽のろ過池からなる。各辺頂部に笠石を廻らし、各池底の中央に集水溝を設ける。創設以来、現役で使われているろ過池。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008838"},{"id":"00008837","register_sub_id":"101","register_pk":"162280","name":"三条市水道局大崎浄水場旧番宅","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうきゅうばんたく","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60947181,"lng":138.99703779,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0346","desc":"送水ポンプ室と配水池の間に建つ旧水道局官舎。木造平屋建、桁行16.4ｍ梁間7.3ｍ、寄棟造桟瓦葺、桁行を二分し二戸を設け、正面に各戸の玄関、背面に便所を張出し、外壁は下見板張とする。昭和初期の浄水場施設の一端を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008837"},{"id":"00008836","register_sub_id":"101","register_pk":"162279","name":"三条市水道局大崎浄水場事務室棟","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうじむしつとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60877868,"lng":138.99748629,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0345","desc":"敷地中央部に西面して建つ。木造平屋建、桁行5.5ｍ梁間7.9ｍ、切妻造桟瓦葺、北西部を切欠いて玄関ポーチとし、背面に手洗いを張出す。外壁はモルタル洗出しで腰壁をタイル貼とする。神社本殿の流造風の屋根が特徴の浄水場の中心施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008836"},{"id":"00008834","register_sub_id":"101","register_pk":"162277","name":"三条市水道局大崎浄水場取水ポンプ場ポンプ室","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうしゅすいぽんぷじょうぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新316","lat":37.60715678,"lng":138.99353272,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0343","desc":"五十嵐川東岸に建ち、木造平屋建、桁行13.7ｍ梁間7.3ｍ、切妻造鉄板葺、正面に切妻造の玄関、背面に寄棟造の付属屋を突出する。外壁はモルタル塗、内部中央に内径5.6ｍルの取水井を設ける。小住宅風の瀟洒な外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008834"},{"id":"00008835","register_sub_id":"101","register_pk":"162278","name":"三条市水道局大崎浄水場取水ポンプ場門","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうしゅすいぽんぷじょうもん","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新258","lat":37.60729009,"lng":138.99367463,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"コンクリート造、延長7.9m","structure_material":"コンクリート造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0344","desc":"ポンプ室の東側に位置する。コンクリート造、高さ2.1ｍの親柱を3.8ｍ間隔で配し、斜め前方の高さ1.3ｍの脇柱と袖壁で繋ぎ、各柱上に笠石を造り出す。取水ポンプ室と一体で良好な歴史的景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008835"},{"id":"00008839","register_sub_id":"101","register_pk":"162282","name":"三条市水道局大崎浄水場洗砂場","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうせんしゃじょう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60843211,"lng":138.99782606,"geo_status":"db","era":"昭和8年／昭和中期移築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄骨造平屋建、鉄板葺、建築面積19㎡","structure_material":"鉄骨造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0348","desc":"ろ過池の東側に位置する、ろ過層の砂類を洗浄するための施設。桁行4.9ｍ梁間3.8ｍの吹放ちの建物で、切妻造鉄板葺である。柱下部を鉄筋コンクリート造とし、上部は古レールをＹ字形に組んで木造の小屋組を受ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008839"},{"id":"00000657","register_sub_id":"101","register_pk":"101647","name":"水道タンク","kana":"すいどうたんく","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県長岡市水道町3-11-1","lat":37.45666341,"lng":138.84310213,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造，一部鉄製，高さ41.5m","structure_material":"鉄筋コンクリート造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0002","desc":"創設長岡市水道のモニュメントで，長岡のランドマークとして親しまれている。配水塔で，塔体は鉄筋コンクリート造６階建，平面円形で外周にトスカナ式のピラスターを付す。タンク部は鉄骨造の架構に鋼製の水槽を納める。金井彦三郎の設計と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000657"},{"id":"00009594","register_sub_id":"101","register_pk":"194590","name":"燕市旧浄水場配水塔","kana":"つばめしきゅうじょうすいじょうはいすいとうとう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県燕市水道町1-3-28","lat":37.65740398,"lng":138.91833121,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"鉄筋コンクリート造、高さ31m、直径10m","structure_material":"鉄筋コンクリート造","registered":"2013.06.21(平成25.06.21)","register_no":"15 － 0381","desc":"浄水場に設置された鉄筋コンクリート造の配水塔で、総高三二メートル。支持台部は円錐台形で八方に柱形を見せ、内部に四階の床を張る。上部水槽は八角平面。一階北に戸口を設け、各階四箇所の窓を開く。四階から外部梯子で登る水槽外周の歩廊が軽快である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009594"},{"id":"00002377","register_sub_id":"101","register_pk":"103367","name":"上滝発電所","kana":"かみだきはつでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県富山市中滝字小野海浦割3-1","lat":36.603237,"lng":137.3130692,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積678㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"16 － 0063","desc":"富山県県営電気事業第１期の常願寺川水系３発電所のうち最下流に位置する。常願寺川左岸に位置し，松ノ木発電所からの水を落差約６７ｍで導き３機の水車を回す。鉄筋コンクリート造平屋一部２階建で，３発電所のうち最も規模が大きく，屋根を陸屋根状に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002377"},{"id":"00002763","register_sub_id":"101","register_pk":"103753","name":"小牧ダム","kana":"こまきだむ","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県砺波市庄川町大字小牧字矢ヶ瀬74","lat":36.55703411,"lng":137.00850014,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長301m、堤高79m、副堰堤及び魚道付","structure_material":"重力式コンクリート造堰堤","registered":"2002.06.25(平成14.06.25)","register_no":"16 － 0069","desc":"庄川に築かれた発電用堰堤。アーチ平面の本格的な重力式コンクリート造ハイダムで，中央部にテンターゲート付越流部，右岸側にエレベータ式魚道，左岸側に運材設備を設ける。地震力を考慮した設計により飛躍的に大型化した構造物で，東洋一のダムと呼ばれた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002763"},{"id":"00000127","register_sub_id":"101","register_pk":"101117","name":"清水町配水塔資料館旧第３源井上屋","kana":"しみずまちはいすいとうしりょうかんきゅうだいさんげんせいうわや","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県高岡市清水町1-7-30","lat":36.74048141,"lng":137.00328868,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建，銅板葺，建築面積6.6㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"16 － 0005","desc":"地下水を汲み上げる源井の上屋である。鉄筋コンクリート造ではあるが，煉瓦の外壁を持ち，八角形の平面とあいまって愛らしい外観を見せている。配水塔とともに当時の科学技術の粋を集めた施設のシンボルとして広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000127"},{"id":"00000038","register_sub_id":"101","register_pk":"101028","name":"清水町配水塔資料館旧配水塔","kana":"しみずまちはいすいとうしりょうかんきゅうはいすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県高岡市清水町1-7-30","lat":36.74106804,"lng":137.00355779,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、高さ29.7m、直径11.4m","structure_material":"鉄筋コンクリート造","registered":"1996.12.20(平成8.12.20)","register_no":"16 － 0002","desc":"昭和６年に完成した高岡市の水道施設の一部。当時の最新科学の粋を集めた水源施設のシンボル的存在である。鉄筋コンクリート造の４層の上に銅板張りの貯水槽が乗る。平成５年より資料館として活用され，通水当時の工具などを展示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000038"},{"id":"00000128","register_sub_id":"101","register_pk":"101118","name":"清水町配水塔資料館水源地水槽","kana":"しみずまちはいすいとうしりょうかんすいげんちすいそう","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県高岡市清水町1-7-30","lat":36.74074942,"lng":137.00384913,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造，長さ30.3m，幅22.7m，高さ3.0m","structure_material":"鉄筋コンクリート造","registered":"1997.05.07(平成9.05.07)","register_no":"16 － 0006","desc":"鉄筋コンクリート造で，長さ30.3ｍ，幅22.7ｍ，高さ3.0ｍの大規模な半地下式の構造物。現在も予備の水槽としての機能をもつが，上部が公園化され市民の憩いの場になっており，高岡の市民生活を支える施設として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000128"},{"id":"00002379","register_sub_id":"101","register_pk":"103369","name":"中地山発電所","kana":"なかちやまはつでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県富山市中地山字上中地山割1-2","lat":36.56804605,"lng":137.36617948,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積237㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"16 － 0065","desc":"富山県電気局による最初の３発電所のうち，常願寺川の最上流に位置し，最も早い大正１３年２月に稼働した。鉄筋コンクリート造，切妻屋根の平屋建で，水車・発電機１対と配電施設等を１室に収める。３発電所とも県内初期鉄筋コンクリート造建築とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002379"},{"id":"00000039","register_sub_id":"101","register_pk":"101029","name":"入善町下山芸術の森アートスペース（旧下山発電所）","kana":"にゅうぜんまちにざやまげいじゅつのもりあーとすぺーす（きゅうにざやまはつでんしょ）","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県下新川郡入善町下山364-1","lat":36.90714499,"lng":137.53141345,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階建、鉄板葺、建築面積558㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"16 － 0003","desc":"発電所の建屋を町が払い下げを受け美術館とした建物。富山平野特有の低落差の河岸段丘を利用した小型の水力発電所で，その立地と赤煉瓦を用いた外観の意匠に特徴がある。富山平野の地形やそれを利用した近代の景観を知る上で特に必要な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000039"},{"id":"00002378","register_sub_id":"101","register_pk":"103368","name":"松ノ木発電所","kana":"まつのきはつでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県富山市松木字大下割446","lat":36.57245853,"lng":137.34801483,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積537㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"16 － 0064","desc":"大正１０年１１月同時着工された３発電所のひとつで，常願寺川左岸に位置し，中地山発電所の放水を導水し２機の水車を回す。鉄筋コンクリート造平屋一部２階建で，下弦材をアーチにした鉄骨トラスにより切妻状の屋根を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002378"},{"id":"00004953","register_sub_id":"101","register_pk":"105943","name":"浅野川大橋詰火の見櫓","kana":"あさのがわおおはしづめひのみやぐら","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県金沢市東山3-1-2先","lat":36.572456,"lng":136.664551,"geo_status":"db","era":"大正13／昭和46改造","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄骨造、高さ11m","structure_material":"鉄骨造","registered":"2005.11.10(平成17.11.10)","register_no":"17 － 0128","desc":"市内に現存する最古の火の見櫓。浅野川大橋の北詰にあり，鋳鉄製銘板から，施工は市内の高田商会。手摺を含めると高さ約１１ｍ，三角形平面の鉄骨造で，柱や横材等は山形鋼を用い，筋違は鋼棒とし，一部にアーチを使い，大型鉄骨造の櫓とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004953"},{"id":"00011282","register_sub_id":"101","register_pk":"209118","name":"大桑配水場旧計量室","kana":"おおくわはいすいじょうきゅうけいりょうしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市大桑町サ乙3-3","lat":36.525669,"lng":136.686667,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積8.5㎡、地階付","structure_material":"鉄筋コンクリート造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0259","desc":"隣接する配水池から延びる導水管の流量を計測していた施設で、約三メートルの正方形平面に導水管を視認できる地下室を持つ。屋根や外壁が直線的意匠で飾られ、窓格子には渦模様に梅鉢に水の標章を配するなど、末浄水場の施設群と一連で計画された意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011282"},{"id":"00002231","register_sub_id":"101","register_pk":"103221","name":"末浄水場一号緩速沈澱池","kana":"すえじょうすいじょういちごうかんそくちんでんち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.512432,"lng":136.700455,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積2848㎡","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0043","desc":"市中心部の南方，犀川中流部に位置する。金沢市創設水道の浄水場施設で，一号沈澱池は，敷地南部に位置する面積２８４８㎡の鉄筋コンクリート造水槽。下部約４ｍの側壁を法面勾配１割５分でつくり，隅部に同勾配で約８ｍ長の階段１基が築かれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002231"},{"id":"00002234","register_sub_id":"101","register_pk":"103224","name":"末浄水場一号緩速ろ過池","kana":"すえじょうすいじょういちごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513008,"lng":136.698639,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積1375㎡、浄水井付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0046","desc":"沈澱池の西端から引かれた水が，低地にある６基の緩速ろ過池に配水される。一号ろ過池はろ過池全体の東南端にあり，他と同様にほぼ垂直に切り立った鉄筋コンクリート造壁面に囲まれた面積１３７５㎡の構造物で，池の北側にコンクリート造浄水井を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002234"},{"id":"00002240","register_sub_id":"101","register_pk":"103230","name":"末浄水場緩速浄水集合井","kana":"すえじょうすいじょうかんそくじょうすいしゅうごうせい","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.51401263,"lng":136.69711278,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積26㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0052","desc":"敷地の西端，緩速ろ過池中央通路の先端部に位置する。当初計画されていた円形平面は，井面積拡大の要請により小判型平面となる。鉄筋コンクリート造上屋の側面に，大小３つの半円アーチを配し，スパンドレルに円をモチーフとした浮彫をあしらう。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002240"},{"id":"00002241","register_sub_id":"101","register_pk":"103231","name":"末浄水場緩速浄水ポンプ室","kana":"すえじょうすいじょうかんそくじょうすいぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.51412816,"lng":136.69720064,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積12㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0053","desc":"緩速浄水集合井の北側に位置する旧塩素滅菌室。ろ過池側を正面として建つ。矩形平面の平屋建鉄筋コンクリート造建築で，各立面を柱型と梁型により縁取る特徴的な意匠でまとめる。金沢市創設水道は大井清一，石井一夫によって計画・設計された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002241"},{"id":"00011283","register_sub_id":"101","register_pk":"209119","name":"末浄水場旧着水井上屋","kana":"すえじょうすいじょうきゅうちゃくすいせいうわや","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.512267,"lng":136.699848,"geo_status":"db","era":"昭和7／平成26改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積87㎡、地階付","structure_material":"鉄筋コンクリート造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0260","desc":"末浄水場の最初期の整備事業で建てられたもので、正面入口に西面して建つ。緩い曲線で持ち送られるパラペットや一段低く入口上部を回る庇が立面を構成し、丸窓や、外壁腰部の飾りがアクセントとなり、近代的水道施設として意図された装飾性が感じられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011283"},{"id":"00002238","register_sub_id":"101","register_pk":"103228","name":"末浄水場五号緩速ろ過池","kana":"すえじょうすいじょうごごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513241,"lng":136.697983,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積1375㎡、浄水井付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0050","desc":"三号緩速ろ過池の西側に位置する。正面開口部を凸型曲面で縁取り門柱形とした浄水井上屋を構える。上屋は，躯体の４隅を曲面で仕上げ，正面以外の各側面に２つの縦長を並置する。屋根を階段状造り，中央に小ドームを載せて外観にアクセントを与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002238"},{"id":"00002233","register_sub_id":"101","register_pk":"103223","name":"末浄水場三号緩速沈澱池","kana":"すえじょうすいじょうさんごうかんそくちんでんち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513268,"lng":136.701035,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積2848㎡","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0045","desc":"二号緩速沈澱池の北側にある。白山連峰に連なる山岳地帯を集水源とする犀川上流部から引かれた水は，正門前の道路下に敷設された導水管を通り，敷地南端正門横の着水井，緩速原水処理機を経由して，沈澱池の東側から前述２基の緩速沈澱池に均等に配水される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002233"},{"id":"00002236","register_sub_id":"101","register_pk":"103226","name":"末浄水場三号緩速ろ過池","kana":"すえじょうすいじょうさんごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513111,"lng":136.698318,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積1375㎡、浄水井付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0048","desc":"一号緩速ろ過池の西側に位置し，隔壁を兼ねた管理用通路によって両側のろ過池と仕切られる。ろ過池通路側の両端に管を１基ずつ設け溢水に備える。ろ過水を集水する浄水井は，コンクリート造水槽で，笠石に花崗石を用い，蓋を縞鋼板で覆う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002236"},{"id":"00002232","register_sub_id":"101","register_pk":"103222","name":"末浄水場二号緩速沈澱池","kana":"すえじょうすいじょうにごうかんそくちんでんち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.512844,"lng":136.700745,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積2848㎡","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0044","desc":"一号緩速沈澱池の北側に位置する。他の沈澱池同様，地下湧水処理用の土管を池下方に敷設する。コンクリートの伸縮作用に備え，池全体が１２分割され，表面全体にモルタル工を施す。伸縮接手にアスファルトと鉛板を用い，池の水密性を高める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002232"},{"id":"00002235","register_sub_id":"101","register_pk":"103225","name":"末浄水場二号緩速ろ過池","kana":"すえじょうすいじょうにごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513462,"lng":136.698959,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積1375㎡、浄水井付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0047","desc":"一号緩速ろ過池の通路を挟んだ北側にある。伸縮作用を考慮し２５区画に分割し，煉瓦，多孔鉄筋コンクリート板，砂を敷いたろ床中央に，浄水井に向かって１／１１８の勾配を有す約０．９ｍ幅の集水渠を設ける。伸縮接手に緩速沈殿地と同様の加工を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002235"},{"id":"00002237","register_sub_id":"101","register_pk":"103227","name":"末浄水場四号緩速ろ過池","kana":"すえじょうすいじょうよんごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513611,"lng":136.698593,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積1375㎡、浄水井付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0049","desc":"二号緩速ろ過池の西側に位置する。池の南側に，鉄筋コンクリート造，建築面積１４㎡でほぼ正方形平面をした浄水井上屋を構える。上屋は，通路側を正面とし，笠石を花崗岩とした基壇を４周に廻し前面に凸形曲線を有する袖に挟まれた階段３段をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002237"},{"id":"00002239","register_sub_id":"101","register_pk":"103229","name":"末浄水場六号緩速ろ過池","kana":"すえじょうすいじょうろくごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513733,"lng":136.698288,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積1375㎡、浄水井付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0051","desc":"四号緩速ろ過池の西側，ろ過池全体の北西端に位置する。東西方向に延びる通路の下に布設された集水管にろ過水が合流する。小規模ながらも，通路を軸に３基づつ左右対称に配置された浄水井は，周辺景観に溶け込み，市民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002239"},{"id":"00002384","register_sub_id":"101","register_pk":"103374","name":"福岡第一発電所","kana":"ふくおかだいいちはつでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県白山市河内町福岡日171-2","lat":36.40074607,"lng":136.62724409,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"煉瓦造地下1階地上2階建、瓦葺、建築面積641㎡","structure_material":"煉瓦造地下1階地上2階建","registered":"2001.10.12(平成13.10.12)","register_no":"17 － 0058","desc":"村北西部，国道１５７号沿いの水力発電所の建屋。キングポストトラスを用い，切妻造，煉瓦造２階建とする。要石，迫持石等に石材を用い，上下の半円アーチ・丸窓と，３方向の妻に付く丸窓とコーニスに特徴をもつ外観が，自然景観の中で際だっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002384"},{"id":"00008448","register_sub_id":"101","register_pk":"134844","name":"福井市水道記念館（旧足羽揚水ポンプ場）","kana":"ふくいしすいどうきねんかん（きゅうあすわようすいぽんぷじょう）","category":"生活関連","subcategory":"建築物","type_guess":"記念碑","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県福井市足羽1-5420","lat":36.05866046,"lng":136.21132243,"geo_status":"db","era":"大正13年頃／平成10年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造2階建、スレート葺、建築面積240㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"18 － 0083","desc":"市内中央にある足羽山の東山麓に位置し、山頂の貯水池に揚水した。切妻造スレート葺、正面一八メートル側面一三メートルの鉄筋コンクリート造二階建。外壁はモルタル洗い出しで、上下二段の大きな矩形窓や胡麻殻仕上げの柱を配し、リズム感のある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008448"},{"id":"00000728","register_sub_id":"101","register_pk":"101718","name":"三宅区火の見やぐら","kana":"みやけくひのみやぐら","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"福井県","address":"福井県三方上中郡若狭町三宅66-26","lat":35.45717279,"lng":135.86511706,"geo_status":"db","era":"江戸期","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"木造平屋建櫓附属，瓦葺，建築面積41㎡","structure_material":"木造平屋建櫓附属","registered":"1998.09.02(平成10.09.02)","register_no":"18 － 0009","desc":"若狭街道の通る三宅地区で，シンボル的な存在となっている火の見櫓。正側面とも３間の地蔵堂の東側屋根の南端に，南妻から延びる梯子を兼ねた主脚を利用して簡略な構造の櫓を載せる。農家の点在する地域にあって，その素朴な外観は広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000728"},{"id":"00000729","register_sub_id":"101","register_pk":"101719","name":"三宅区火の見やぐら倉庫","kana":"みやけくひのみやぐらそうこ","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県三方上中郡若狭町三宅66-26","lat":35.4571046,"lng":135.86507955,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建，瓦葺，建築面積40㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"18 － 0010","desc":"火の見櫓の載る地蔵堂の左側にあり，棟を直交する形で接続し南面して建つ切妻造，桟瓦葺の消防用等の小規模な倉庫。正面左手に出入り口を設け，間口一間半の大戸を引き戸とする。軒廻りを真壁とするほかは縦板貼りとする簡素な建屋として知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000729"},{"id":"00000285","register_sub_id":"101","register_pk":"101275","name":"駒橋発電所落合水路橋","kana":"こまばしはつでんしょおちあいすいろきょう","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県都留市古川渡字落合","lat":35.57801603,"lng":138.93521158,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"煉瓦造アーチ橋，長さ56m，幅員8.5m","structure_material":"煉瓦造アーチ橋","registered":"1997.09.03(平成9.09.03)","register_no":"19 － 0015","desc":"東京電灯(現東京電力)駒橋発電所関連の施設として建設された水路橋で，朝日川を越える地点に作られた。河床を３連アーチで越え，東側に小さな４つのアーチを設ける。簡素な外観であるが，ひときわ目に付く現在では珍しい大規模な煉瓦構造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000285"},{"id":"00000289","register_sub_id":"101","register_pk":"101279","name":"鹿留発電所うそぶき水路呑口部","kana":"ししどめはつでんしょうそぶきすいろのみくちぶ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県南都留郡富士河口湖町浅川字片浜1309-1地先","lat":35.50714175,"lng":138.77297995,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造・鉄筋コンクリート造，長さ21.9m，幅23.0m，高さ9.1m","structure_material":"石造・鉄筋コンクリート造","registered":"1997.09.03(平成9.09.03)","register_no":"19 － 0019","desc":"発電に必要な水量を確保するために河口湖に建設された取水口。大正５年に着工，同７年に竣工・通水した。水溜をつくり水位を調節する形式で，水溜の護岸に用いられた石積みの構法等に時代の特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000289"},{"id":"00000346","register_sub_id":"101","register_pk":"132551","name":"鹿留発電所うそぶき水路吐口部","kana":"ししどめはつでんしょうそぶきすいろはきぐちぶ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県富士吉田市旭5-2457-1、5-2462-1、5-4636-1","lat":35.49503534,"lng":138.78704389,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造，延長72.8m，石造水路坑口附属","structure_material":"石造","registered":"1997.11.05(平成9.11.05)","register_no":"19 － 0020","desc":"河口湖の水を宮川へと導き，下流で発電の用に供するための水路。斜面の中腹に石造の坑口を設け，斜面を開渠で流下させる構成である。呑口部と同様に石積みの構法等に時代の特徴が現れており，また年月を経て周囲の景観に溶け込んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000346"},{"id":"00000823","register_sub_id":"101","register_pk":"101813","name":"平瀬浄水場旧片山隧道上口","kana":"ひらせじょうすいじょうきゅうかたやまずいどうかみぐち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲府市平瀬町2903","lat":35.70123389,"lng":138.55065484,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"石造水路坑口，幅4.6m，高さ3.4m","structure_material":"石造水路坑口","registered":"1998.10.09(平成10.10.09)","register_no":"19 － 0030","desc":"平瀬浄水場からの送水路の一部になる片山隧道の上手口に設けられた石造の坑口で，開口部に鉄扉が付く。同市羽黒町梨の木に所在する隧道の下口と同形式になるが，上口の方が一回り小さい。甲府市の水道の歴史を知る上で，欠かせない施設のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000823"},{"id":"00000762","register_sub_id":"101","register_pk":"101752","name":"平瀬浄水場旧片山隧道下口","kana":"ひらせじょうすいじょうきゅうかたやまずいどうしもぐち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲府市羽黒町字梨の木1715","lat":35.70651613,"lng":138.52638407,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"石造水路坑口，幅4.7m，高さ3.4m","structure_material":"石造水路坑口","registered":"1998.09.02(平成10.09.02)","register_no":"19 － 0029","desc":"大正２年に竣工した浄水場の送水施設。幅６ｍ，高さ５ｍの石造の駆体部に鉄扉付きのアーチ状開口部を持つ簡素な建物で，内部は岩盤を穿った送水坑口に鉄管が付設される。開口上部に「片山隧道」の銘板を掲げる。浄水場の構成を知る上でも貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000762"},{"id":"00000730","register_sub_id":"101","register_pk":"101720","name":"平瀬浄水場旧取水口門部","kana":"ひらせじょうすいじょうきゅうしゅすいこうもんぶ","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲府市平瀬町437-3","lat":35.71193852,"lng":138.53503005,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"石造水路坑口，幅14.4m，高さ11.0m","structure_material":"石造水路坑口","registered":"1998.09.02(平成10.09.02)","register_no":"19 － 0028","desc":"荒川からの取水路の，浄水場側の出口に位置する。石造でポータルを造り，開口部の上に「沢渠為雨」の銘板を置く。現在ではこの取水ルートは使用されていないが，水道近代化のシンボルとして，また浄水場の石造構造物の好例として位置づけることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000730"},{"id":"00000238","register_sub_id":"101","register_pk":"101228","name":"平瀬浄水場旧濾過池整水井","kana":"ひらせじょうすいじょうきゅうろかちせいすいせい","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲府市平瀬町437-3","lat":35.71192136,"lng":138.53541186,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"鉄筋コンクリート造，建築面積11㎡","structure_material":"鉄筋コンクリート造","registered":"1997.07.15(平成9.07.15)","register_no":"19 － 0012","desc":"平瀬浄水場の創設とほぼ同時に建設された調整井上屋。内部に制水弁を持ち、濾過速度及び流水量を調節する。円形平面で、入口にはペディメントを持つフレームを配し、上部には「尽不流々混」の題字を記す。甲府市の生活近代化のシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000238"},{"id":"00001254","register_sub_id":"101","register_pk":"102244","name":"平瀬浄水場第２隧道上口","kana":"ひらせじょうすいじょうだいにずいどうかみぐち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲府市平瀬町","lat":35.71318758,"lng":138.5407314,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"石造水路坑口、幅4.3m、高さ3.3m","structure_material":"石造水路坑口","registered":"1999.08.23(平成11.08.23)","register_no":"19 － 0038","desc":"甲府市創設水道の遺構のひとつ。取水口から平瀬浄水場に至る経路の浄水場側に位置する導水隧道の上流側入口門部で、出口側の「取水口門部」に対応する。花崗石を用いて江戸切り仕上げ風に見せた丁寧な造りの門部で、「挙鍾為雲」の扁額を掲げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001254"},{"id":"00000407","register_sub_id":"101","register_pk":"101397","name":"平瀬水源旧事務所（水交庵）","kana":"ひらせすいげんきゅうじむしょ（すいこうあん）","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県甲府市平瀬町437-3","lat":35.71192842,"lng":138.53494927,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積242㎡","structure_material":"木造平屋建","registered":"1997.12.12(平成9.12.12)","register_no":"19 － 0021","desc":"もと平瀬浄水場の事務所で，現在は甲府市の水道の歴史を展示する資料館として活用されている。木造平屋建，瓦葺で，正面中央にある２連のアーチで構成した玄関ポーチの意匠に特徴がある。市民生活の近代化を象徴する施設として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000407"},{"id":"00003242","register_sub_id":"101","register_pk":"104232","name":"旧岡谷上水道集水溝","kana":"きゅうおかやじょうすいどうしゅうすいこう","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県岡谷市山手町3-4071","lat":36.06539413,"lng":138.03673631,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"石造及びコンクリート造、面積155㎡、正面両翼壁付","structure_material":"石造及びコンクリート造","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0129","desc":"市街地東部の高台に位置する。正面を切石布積，側壁及び内部アーチ天井をコンクリート造とした矩形平面の構造物で，上部に換気塔を設ける。約１５ｍ長の水路の石積側面細隙から湧水を取り込み，量水計などを備えた貯水槽に集水する特異な構造を有す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003242"},{"id":"00015019","register_sub_id":"101","register_pk":"529297","name":"旧小野村下町火の見櫓","kana":"きゅうおのむらしもまちひのみやぐら","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"長野県","address":"長野県上伊那郡辰野町大字小野字町823-2","lat":36.03815556,"lng":137.96871111,"geo_status":"db","era":"昭和30年","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"鉄骨造、高さ17m","structure_material":"鉄骨造","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0658","desc":"伊那街道沿いに建つ高さ17メートルの鉄骨造の櫓。方形平面を上方に向かって逓減させ、頂部に設けた見張台に尖塔形宝形屋根を載せ、中央に半鐘を吊る。横架材間はリング式ターンバックルで補強。軒先の蕨手状飾りなど繊細な装飾を施した地域のランドマーク。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015019"},{"id":"00010590","register_sub_id":"101","register_pk":"201164","name":"松本市上下水道局島内第一水源地石垣及び階段","kana":"まつもとしじょうげすいどうきょくしまうちだいいちすいげんちいしがきおよびかいだん","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市島内3635-1","lat":36.242929,"lng":137.949048,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"石造、総延長156m","structure_material":"石造","registered":"2015.08.04(平成27.08.04)","register_no":"20－0481","desc":"水源地南半の敷地において、集水井及び会所を囲むように築かれる。花崗岩を用い、西面を谷積、その他三面を布積で築いた総延長一五六メートルの石垣と、北面中央の石積階段よりなる。水源地に埋設された集水暗渠の範囲を区画する、松本市創設水道施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010590"},{"id":"00010591","register_sub_id":"101","register_pk":"201165","name":"松本市上下水道局島内第一水源地旧喞筒室","kana":"まつもとしじょうげすいどうきょくしまうちだいいちすいげんちきゅうしょくとうしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市島内3890-1","lat":36.243106,"lng":137.949072,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積231㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"20－0482","desc":"配水地への揚水用ポンプを収容した、間口一四間奥行五間の鉄筋コンクリート造建築。平側に窓を広くとり採光や排気に配慮したつくりで、四周に菱形模様付のパラペットを廻らし、柱形には石積風の目地を刻むなど随所に意匠を施す。水源地の要となる建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010591"},{"id":"00010589","register_sub_id":"101","register_pk":"201163","name":"松本市上下水道局島内第一水源地集水井及び会所","kana":"まつもとしじょうげすいどうきょくしまうちだいいちすいげんちしゅうすいせいおよびかいしょ","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市島内3635-1","lat":36.242753,"lng":137.948998,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"コンクリート造、集水井及び会所3基よりなる、総面積27㎡","structure_material":"コンクリート造","registered":"2015.08.04(平成27.08.04)","register_no":"20－0480","desc":"市中心部の北西、奈良井川沿いの敷地に建つ。湧水を導く暗渠の曲所に配された会所三基と暗渠を接続する集水井よりなる。いずれもコンクリート造で、会所は内法四尺角、集水井は内径一五尺とする。湧泉を水源とした近代水道の仕組みを今に伝える貴重な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010589"},{"id":"00010592","register_sub_id":"101","register_pk":"201166","name":"松本市上下水道局島内第一水源地倉庫","kana":"まつもとしじょうげすいどうきょくしまうちだいいちすいげんちそうこ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市島内3890-1","lat":36.242985,"lng":137.948777,"geo_status":"db","era":"大正11年／昭和40年頃移築","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"20－0483","desc":"喞筒室の西側に位置する。東面して建つ桁行四間梁間三間の木造平屋建で、寄棟造、外装モルタル塗仕上げとする。小屋組はキングポストトラスで、正面には左右対称に二箇所の入口を設ける。建ちを高くし、内部空間を広くとる倉庫建築らしい簡素な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010592"},{"id":"00010594","register_sub_id":"101","register_pk":"201168","name":"松本市上下水道局城山配水地旧配水池","kana":"まつもとしじょうげすいどうきょくじょうやまはいすいちきゅうはいすいち","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市大字蟻ヶ崎字城山腰1133-1","lat":36.245636,"lng":137.955415,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"コンクリート造、面積1518㎡","structure_material":"コンクリート造","registered":"2015.08.04(平成27.08.04)","register_no":"20－0485","desc":"接合井に隣接して築かれる。縦三五メートル、横四二メートル規模のコンクリート造構造物で、南北二面に煉瓦壁を立ち上げ覆土を押さえる。内部は二池よりなり、屋根はヴォールト状とし、中央に煉瓦造上屋から出入りする管理用通路を設ける。配水地の中心施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010594"},{"id":"00010593","register_sub_id":"101","register_pk":"201167","name":"松本市上下水道局城山配水地接合井","kana":"まつもとしじょうげすいどうきょくじょうやまはいすいちせつごうせい","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市大字蟻ヶ崎字城山腰1133-1","lat":36.245462,"lng":137.955411,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"コンクリート造平屋建、建築面積20㎡","structure_material":"コンクリート造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"20－0484","desc":"島内第一水源地より約六〇〇メートル北東の高台に位置し、水源地からの揚水を受ける。コンクリート造の円形水槽と、腰、柱形等をモルタル塗とし、全体に幾何学模様をあしらう煉瓦造上屋からなる。水道施設全体の構成を知る上で欠くことのできない構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010593"},{"id":"00015449","register_sub_id":"101","register_pk":"533464","name":"南向発電所本館","kana":"みなかたはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県上伊那郡中川村葛島933-2","lat":35.61061111,"lng":137.93139722,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積976㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"20 - 0672","desc":"天竜川水系に築いた最初期の水力発電施設。鉄筋コンクリート造で正面側は半円アーチ形の長大な縦長窓が囲む一室の大空間の発電機室とし、背面側は事務室・機械室を配し、放物線アーチ形窓など前衛的意匠も取り込む。洗練された姿の施設で地域のランドマーク。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015449"},{"id":"00002242","register_sub_id":"101","register_pk":"103232","name":"鏡岩水源地旧エンジン室","kana":"かがみいわすいげんちきゅうえんじんしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県岐阜市鏡岩408-2、米廩谷1-2","lat":35.43755,"lng":136.779053,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄骨造及び鉄筋コンクリート造平屋建、建築面積187㎡","structure_material":"鉄骨造及び鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"21 － 0037","desc":"長良川左岸に位置する岐阜市創設水道の水源地施設で，敷地の南端に建つ。鉄骨造平屋建で，外壁は鉄筋コンクリート造玉石張とし，隅石を花崗岩で積み上げ，妻側は切妻屋根を方杖が支える山小屋風意匠とするなど水道施設としては異色のデザインでまとめられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002242"},{"id":"00002243","register_sub_id":"101","register_pk":"103233","name":"鏡岩水源地旧ポンプ室","kana":"かがみいわすいげんちきゅうぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県岐阜市鏡岩408-2、米廩谷1-1・1-2","lat":35.437691,"lng":136.779266,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄骨造及び鉄筋コンクリート造平屋建、建築面積186㎡","structure_material":"鉄骨造及び鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"21 － 0038","desc":"昭和３年に建設着手した当水源地施設は同９年に完成。旧ポンプ室は類似した外観をもつ旧エンジン室の北東に位置する。平側に丸窓を一列に穿ち，旧エンジン室では壁面の外側に出された２ヒンジ鉄骨トラスを室内側に収める。棟の脇に細長い換気口を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002243"},{"id":"00002247","register_sub_id":"101","register_pk":"103237","name":"長良川発電所下須原谷水路橋","kana":"ながらがわはつでんしょしもすはらだにすいろきょう","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県美濃市大字須原字小洞","lat":35.57749381,"lng":136.93052151,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦及びコンクリート造単アーチ橋、橋長13m、幅9.3m","structure_material":"煉瓦及びコンクリート造単アーチ橋","registered":"2001.08.28(平成13.08.28)","register_no":"21 － 0042","desc":"第二沈砂池に隣接し，下須原川を跨ぐ橋長１３ｍ，幅９．３ｍの煉瓦及びコンクリート造充腹単アーチ橋。４枚厚煉瓦欠円アーチの上に深さ３．３ｍの外装イギリス積煉瓦水路が設けられる。笠木部分に異なる厚さで煉瓦を２段積み，外観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002247"},{"id":"00002250","register_sub_id":"101","register_pk":"103240","name":"長良川発電所取水口呑口上部","kana":"ながらがわはつでんしょしゅすいこうのみくちじょうぶ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県郡上市美並町上田字干谷口3209-1、3206-2","lat":35.57349224,"lng":136.92843027,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦、石及びコンクリート造、幅14m、高さ2.7m","structure_material":"煉瓦","registered":"2001.08.28(平成13.08.28)","register_no":"21 － 0045","desc":"村南部，長良川中流域にある水力発電所の取水口。迫石に花崗岩を用いた５門の欠円アーチ形ゲートの上に，増水時の取水に使われる４つの矩形開口部（現在閉切）を設けたイギリス積の煉瓦壁面を立ち上げる。当発電所の建設には野口遵と佐藤四郎が関係している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002250"},{"id":"00002040","register_sub_id":"101","register_pk":"103030","name":"長良川発電所正門","kana":"ながらがわはつでんしょせいもん","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県美濃市立花字木の末844-1-1-1-1","lat":35.57329842,"lng":136.92962211,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造、間口5.5m、高さ2.4m、両側通用門及び北袖塀並びに階段含む","structure_material":"煉瓦造","registered":"2000.12.04(平成12.12.04)","register_no":"21 － 0034","desc":"長良川発電所は長良川中流域に位置し，正門は川に向かって構える。高さ2.4mの門柱の両側に通用門と袖塀を付け，前面に末開きの煉瓦造階段を設ける。各門柱の柱頭と柱礎に花崗岩を用い，外観を引き締めている。外塀と共に，本館と一体的な景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002040"},{"id":"00002041","register_sub_id":"101","register_pk":"103031","name":"長良川発電所外塀","kana":"ながらがわはつでんしょそとべい","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県美濃市立花字木の末844-1-1-1-1","lat":35.57319672,"lng":136.92959297,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"石及び煉瓦造、延長15m、高さ1.2m","structure_material":"石及び煉瓦造","registered":"2000.12.04(平成12.12.04)","register_no":"21 － 0035","desc":"明治３０年に岐阜水力電気株式会社が得た許可をもとに，名古屋電灯株式会社が建設した長良川発電所は，長良川流域で最初に造られた発電所である。外塀は高さ１．２ｍで，帯石でかたどられた玉石積壁に，計５本の控壁を有すフランス積の煉瓦塀が載る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002041"},{"id":"00002249","register_sub_id":"101","register_pk":"103239","name":"長良川発電所第一沈砂池防水壁","kana":"ながらがわはつでんしょだいいちちんさちぼうすいへき","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県美濃市大字須原字山ノ神858-2","lat":35.57512416,"lng":136.92833847,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦及び石造、全長折曲り60m、管理用通路及び水門操作場付","structure_material":"煉瓦及び石造","registered":"2001.08.28(平成13.08.28)","register_no":"21 － 0044","desc":"導水路第一隧道の手前に位置する第一沈砂池に隣接してたつ。ほぼ五角形平面で，外周に階段付通路を設ける。パラペット付煉瓦積壁面と玉石積壁面が全体を囲み，隧道の流入水量を調節するために各々２つの小門扉を収める４門の半円アーチ形大ゲートが備わる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002249"},{"id":"00002248","register_sub_id":"101","register_pk":"103238","name":"長良川発電所第二沈砂池排水路暗渠","kana":"ながらがわはつでんしょだいにちんさちはいすいろあんきょ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県美濃市大字須原字小洞168-8","lat":35.57657375,"lng":136.92929399,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦及び石造、長さ2.3m、幅0.90m、鉄製排砂門付","structure_material":"煉瓦及び石造","registered":"2001.08.28(平成13.08.28)","register_no":"21 － 0043","desc":"導水路中央部に位置する第二沈砂池排砂路の基部にある。長さ２．３ｍ，幅０．９０ｍ，高さ０．８５ｍの煉瓦造欠円アーチ形坑道の端部に，迫石を花崗岩でつくった坑門が付く。坑道内に捲上機と連動した鉄製排砂門を設け，小規模ながら重厚な外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002248"},{"id":"00002245","register_sub_id":"101","register_pk":"103235","name":"長良川発電所日谷水路橋","kana":"ながらがわはつでんしょひだにすいろきょう","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県美濃市大字立花字猿屋～字寄合畑","lat":35.57902125,"lng":136.93565324,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦及びコンクリート造5連アーチ橋、橋長54m、幅8.0m","structure_material":"煉瓦及びコンクリート造5連アーチ橋","registered":"2001.08.28(平成13.08.28)","register_no":"21 － 0040","desc":"取水口から長良川発電所まで約４．９ｋｍ続く導水路の終点近くに位置する。橋長５４ｍ，幅８．０ｍの曲線平面線形をもつ煉瓦及びコンクリート造充腹５連アーチ橋。２種類の径間長をもつ欠円アーチの上に，深さ３．４ｍで外装煉瓦イギリス積の水路がのる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002245"},{"id":"00002039","register_sub_id":"101","register_pk":"103029","name":"長良川発電所本館","kana":"ながらがわはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県美濃市立花字木の末844-1-1-1-1","lat":35.57324669,"lng":136.92940363,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造地上2階地下1階建、鉄板葺、建築面積439㎡","structure_material":"煉瓦造地上2階地下1階建","registered":"2000.12.04(平成12.12.04)","register_no":"21 － 0033","desc":"煉瓦造地上２階地下１階建の水力発電所の建屋。当初発電機室と接し全体でＬ字型平面をとっていたが，現在は地上で切り離される。妻面にバラ窓風の開口部を設けつつ，かつての瓦葺屋根の名残である鬼瓦を頂き，和風を意識した妻面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002039"},{"id":"00002246","register_sub_id":"101","register_pk":"103236","name":"長良川発電所湯之洞谷水路橋","kana":"ながらがわはつでんしょゆのほらだにすいろきょう","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県美濃市大字立花字湯ノ洞～字長平","lat":35.57842944,"lng":136.93345544,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦及びコンクリート造5連アーチ橋、橋長62m、幅8.0m","structure_material":"煉瓦及びコンクリート造5連アーチ橋","registered":"2001.08.28(平成13.08.28)","register_no":"21 － 0041","desc":"導水路の第３号隧道出口に隣接する，橋長６２ｍ，幅８．０ｍの煉瓦及びコンクリート造充腹５連アーチ橋。アーチ形に刳り抜れた各橋脚の上に花崗岩の迫持石がのり，そこから６枚厚の煉瓦アーチ部が立ち上がる。山道の景観に風趣を添え，市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002246"},{"id":"00002244","register_sub_id":"101","register_pk":"103234","name":"長良川発電所余水路横断橋","kana":"ながらがわはつでんしょよすいろおうだんきょう","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県美濃市立花字木の末844-1-1-1-1","lat":35.57962319,"lng":136.93584838,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"鉄筋コンクリート造単アーチ橋、橋長8.2m、幅2.0m","structure_material":"鉄筋コンクリート造単アーチ橋","registered":"2001.08.28(平成13.08.28)","register_no":"21 － 0039","desc":"長良川発電所に注ぎ込む水を堰き止める水槽の余水路に架かる管理橋。橋長８．２ｍ，幅２．０ｍの小規模な鉄筋コンクリート造単アーチ橋で，アーチ断面にわずかに変化をつける。中部地方における最初期の鉄筋コンクリート橋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002244"},{"id":"00005615","register_sub_id":"101","register_pk":"106603","name":"前野町火の見櫓","kana":"まえのちょうひのみやぐら","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市那加前野町4-2","lat":35.40869803,"lng":136.8351857,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄骨造、高さ19m","structure_material":"鉄骨造","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0102","desc":"高さ約１９ｍの鉄骨造の火の見櫓で，銘板から年代等が明確。山形鋼を四脚に建てて横材を渡し，その間をリング式ターンバックルで固める。最上部は円錐形屋根付の方形望楼を載せ，中間には半鐘を架ける。地域の歴史的景観の核として広く市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005615"},{"id":"00006537","register_sub_id":"101","register_pk":"107520","name":"山桜神社火の見櫓","kana":"やまざくらじんじゃひのみやぐら","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県高山市本町2-65","lat":36.142101,"lng":137.257614,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造、高さ7.0m、木造平屋建社殿付","structure_material":"木造","registered":"2007.07.31(平成19.07.31)","register_no":"21 － 0121","desc":"宮川に架かる柳橋西詰交差点近くに所在。山桜神社社殿の南側建屋の小屋梁上に柱を建て，棟上に櫓を組む。櫓の袴底部は３．４ｍ四方，高約７ｍ規模，三層建で，頭部に宝形造の見張小屋を置き明治１４年製の半鐘を吊る。神社の絵馬市とともに親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006537"},{"id":"00005465","register_sub_id":"101","register_pk":"106453","name":"旧岩渕火の見櫓","kana":"きゅういわぶちひのみやぐら","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"静岡県","address":"静岡県富士市南松野字根方281-8","lat":35.17450551,"lng":138.60255866,"geo_status":"db","era":"昭和26／平成17移築","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄骨造、高さ19m","structure_material":"鉄骨造","registered":"2006.03.27(平成18.03.27)","register_no":"22 － 0112","desc":"富士川町岩渕の消防団車庫の付属施設として建設。４．４ｍ四方のＲＣ造の基礎上に山形鋼で組まれ，高さは１８．５ｍ。踊り場を長方形，見張り台を円形とし，屋根を八角形で，くびれをもつ帽子状とし，頂部に避雷針を付ける。意匠，規模ともに秀でる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005465"},{"id":"00009284","register_sub_id":"101","register_pk":"194077","name":"旧掛塚郵便局（長谷川家住宅）局舎","kana":"きゅうかけつかゆうびんきょく（はせがわけじゅうたく）きょくしゃ","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県磐田市白羽29-2","lat":34.67340354,"lng":137.79810164,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階一部平屋建、鉄板葺一部瓦葺、建築面積178㎡","structure_material":"木造2階一部平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"22 － 0188","desc":"天竜川畔に西面して建つ。木造平屋一部二階建、建築面積一七八平方メートル、寄棟造鉄板葺及び桟瓦葺。正面の旧局舎は石造風のモルタル塗とし、柱形のほか上部にはコーニスやメダリオンを象る。後方平屋は和風住宅である。廻船で栄えた掛塚の近代化を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009284"},{"id":"00009285","register_sub_id":"101","register_pk":"194078","name":"旧掛塚郵便局（長谷川家住宅）蔵","kana":"きゅうかけつかゆうびんきょく（はせがわけじゅうたく）くら","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県磐田市白羽29-2","lat":34.67336071,"lng":137.79827772,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"22 － 0189","desc":"主屋後方に南北棟で建つ。木造二階建、桁行七・三メートル梁間四・六メートル、寄棟造桟瓦葺で西面出入口に庇を付ける。外壁は伊豆石張で石造風とし、石造の窓廻りでは、庇に垂木形を表し、窓枠に唐草や家紋を陽刻し、庇持送りに繰形を施すなど技巧を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009285"},{"id":"00009178","register_sub_id":"101","register_pk":"164731","name":"旧常光水源地ポンプ室","kana":"きゅうじょうこうすいげんちぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県浜松市東区常光町字矢来773","lat":34.74876079,"lng":137.80485918,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、建築面積205㎡","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"旧住吉浄水場から約8キロメートル東方の天竜川右岸に建ち、桁行14.7メートル梁間11.8メートル、鉄筋コンクリート造、平屋1部2階建、寄棟造鉄板葺である。東面入口の円柱頂部にアカンサスを飾り、周囲に植物紋の漆喰彫刻を配するなど意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009178"},{"id":"00009177","register_sub_id":"101","register_pk":"164730","name":"旧住吉浄水場正門","kana":"きゅうすみよしじょうすいじょうせいもん","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県浜松市中区住吉5-182-1","lat":34.73343319,"lng":137.72775694,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、間口5.6m、左右脇門付","structure_material":"鉄筋コンクリート造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地南面中央に位置する。鉄筋コンクリート造、5.6メートル間隔で親柱を立て、その両側に脇柱を立てて脇門とする。各門柱は洗出し仕上げで、幾何模様の飾りや溝彫りを施し、頂部に球形の灯具をおく。正面に建つポンプ室と1体で良好な景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009177"},{"id":"00009173","register_sub_id":"101","register_pk":"164726","name":"旧住吉浄水場接合井","kana":"きゅうすみよしじょうすいじょうせつごうせい","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県浜松市中区住吉5-283","lat":34.73436118,"lng":137.72784617,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積275㎡","structure_material":"鉄筋コンクリート造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地中央に位置する。鉄筋コンクリート造で、外径18.7メートルの円形平面になり、内部は深さ2.7メートルを測る。外壁は洗出し仕上げで、上下の帯と束を表して基壇風に見せ、各束間に石積を模した目地を切る。上面は芝を張り、換気塔2基を立ち上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009173"},{"id":"00009172","register_sub_id":"101","register_pk":"164725","name":"旧住吉浄水場着水井","kana":"きゅうすみよしじょうすいじょうちゃくすいせい","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県浜松市中区住吉5-182-1","lat":34.73487276,"lng":137.7288277,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積66㎡","structure_material":"鉄筋コンクリート造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地北東隅に建つ鉄筋コンクリート造。外径9.2メートルの正八角形平面で、頂部に円形の軒を張出し、内部は深さ6.8メートルを測る。外壁の隅に柱形を配し、基部にペデスタル、頂部に持送りを表し、柱身に溝彫りを施すなど、外部意匠を凝らした水道施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009172"},{"id":"00009175","register_sub_id":"101","register_pk":"164728","name":"旧住吉浄水場直送ポンプ井","kana":"きゅうすみよしじょうすいじょうちょくそうぽんぷせい","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県浜松市中区住吉5-283","lat":34.73408159,"lng":137.72783427,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積49㎡","structure_material":"鉄筋コンクリート造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"接合井とポンプ室の間に建ち、鉄筋コンクリート造で、外径7.9メートルの円筒形になる。外壁はモルタル洗出し仕上げで、基部にペデスタル風の飾りを廻し、石積を模した目地を切る。頂部の張出しでは帯状にメアンダーを飾り、外観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009175"},{"id":"00009174","register_sub_id":"101","register_pk":"164727","name":"旧住吉浄水場配水池","kana":"きゅうすみよしじょうすいじょうはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県浜松市中区住吉5-284","lat":34.73413513,"lng":137.72722751,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積1844㎡","structure_material":"鉄筋コンクリート造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地西側に位置する。東西24メートル南北34メートルの鉄筋コンクリート造の池2基を、アーチ状の通路を挟んで東西に並べ、盛土で被覆し、台形の土壇状を呈する。南北面中央に建つ塔屋は、3連アーチを配し、タイル貼の帯を上下に廻らすなど装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009174"},{"id":"00009176","register_sub_id":"101","register_pk":"164729","name":"旧住吉浄水場ポンプ室","kana":"きゅうすみよしじょうすいじょうぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県浜松市中区住吉5-283","lat":34.73387934,"lng":137.72780453,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積453㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地南側に建ち、桁行23メートル梁間17.6メートル、鉄筋コンクリート造、寄棟造鉄板葺で、小屋はフィンクトラスを架ける。外壁に植物模様の漆喰彫刻や放物線アーチの窓、松葉のステンドグラスを配し、パラペットにメダルを付すなど、豊かに装飾する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009176"},{"id":"00004977","register_sub_id":"101","register_pk":"105967","name":"豊門公園正門","kana":"ほうもんこうえんせいもん","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県駿東郡小山町藤曲144-8","lat":35.362293,"lng":138.985504,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造、間口5.2m、左右袖塀付","structure_material":"鉄筋コンクリート造","registered":"2005.11.10(平成17.11.10)","register_no":"22 － 0103","desc":"敷地の西端に位置する。添柱付の高さ１．７ｍのＲＣ造柱を左右に配し，その外側に曲線平面の袖壁を付ける。笠石に江戸切り仕上の大型の花崗岩を用い，モルタル洗出仕上の柱身には，石積風の目地を等間隔に入れる。重厚な外観で園路の入口を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004977"},{"id":"00004978","register_sub_id":"101","register_pk":"105968","name":"豊門公園噴水泉","kana":"ほうもんこうえんふんすいせん","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県駿東郡小山町藤曲144-8","lat":35.36249309,"lng":138.98628345,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造、面積39㎡","structure_material":"鉄筋コンクリート造","registered":"2005.11.10(平成17.11.10)","register_no":"22 － 0104","desc":"公園中央部に位置する。半径５ｍ規模の半円形平面をしたＲＣ造水槽の円弧を，西洋館と向かい合わせ，直線部分両端には，モルタル洗出仕上で石積風に目地を入れた角柱を配する。豊門会館と西洋館の各正面軸線のほぼ交点に位置する，公園空間構成上の要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004978"},{"id":"00004979","register_sub_id":"101","register_pk":"105969","name":"豊門公園和田君遺悳碑","kana":"ほうもんこうえんわだくんいとくひ","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県駿東郡小山町藤曲144-8","lat":35.36245827,"lng":138.98726575,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"石造、面積2.3㎡","structure_material":"石造","registered":"2005.11.10(平成17.11.10)","register_no":"22 － 0105","desc":"豊門公園の南東部に位置する，高さ３ｍの花崗岩の石造物。角を丸めた１．５ｍ四方の台座に碑文を陰刻した円柱を載せ，さらにその上部に宝珠を頂く三層の屋根形を載せる。建築的モチーフを取り入れた，朝倉文夫案による独特な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004979"},{"id":"00006422","register_sub_id":"101","register_pk":"107405","name":"旧豊川電話装荷線輪用櫓","kana":"きゅうとよかわでんわそうかせんりんようやぐら","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県豊川市野口町開津11","lat":34.83829162,"lng":137.3550265,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造、面積10㎡","structure_material":"鉄筋コンクリート造","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0261","desc":"旧豊川電話中継所の約４ｋｍ西方に建つ。面積１０㎡、高さ６ｍ、鉄筋コンクリート造の櫓。当時の逓信省の標準設計になり、上部に装荷線輪を設置していた。わが国最初の長距離市外電話用ケーブル施設の希少な現存例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006422"},{"id":"00014025","register_sub_id":"101","register_pk":"508285","name":"道徳公園クジラ池噴水","kana":"どうとくこうえんくじらいけふんすい","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市南区道徳新町五丁目42","lat":35.10381389,"lng":136.90741389,"geo_status":"db","era":"昭和2年／同16年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"コンクリート造及び石造、面積243㎡","structure_material":"コンクリート造及び石造","registered":"2021.10.14(令和3.10.14)","register_no":"23 - 0562","desc":"あゆち潟と呼ばれた伊勢湾の一部で、新田開発を経て昭和初期の土地区画整理で開かれた道徳地区にある公園施設。造形家後藤鍬五郎制作の鯨の噴水設備を中心にして石と擬木で池の護岸を巡らし、石製欄干付コンクリート橋を架ける。戦前から永く地域で愛される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014025"},{"id":"00006505","register_sub_id":"101","register_pk":"107488","name":"トヨテック本社社屋（旧豊川電話中継所本屋）","kana":"とよてっくほんしゃしゃおく（きゅうとよかわでんわちゅうけいしょほんや）","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県豊川市西豊町2-35","lat":34.828575,"lng":137.400696,"geo_status":"db","era":"昭和初","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積346㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0259","desc":"豊川稲荷近くの本社敷地内に建つ。建築面積３４６㎡、鉄筋コンクリート造２階建。外壁に２階分の柱型を連続させて表し、各間に縦長窓を配する。上部のパラペットも特徴的な意匠とする。昭和初期における、逓信省による標準的な中継所建築として、数少ない遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006505"},{"id":"00006319","register_sub_id":"101","register_pk":"107302","name":"トヨテック本社倉庫（旧豊川電話中継所倉庫）","kana":"とよてっくほんしゃそうこ（きゅうとよかわでんわちゅうけいしょそうこ）","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県豊川市西豊町2-35","lat":34.82867431,"lng":137.40091043,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造平屋建、建築面積38㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0260","desc":"敷地の東隅、本社社屋の北東に建つ。建築面積３８㎡、鉄筋コンクリート造平屋建で、南面に出入口、東と北面に窓を開ける。外壁は社屋と同様のモルタル塗仕上げで統一感をもたせるが、隅や上端部を丸めて面を取り、窓も方形に近いなど社屋と対照的な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006319"},{"id":"00012555","register_sub_id":"101","register_pk":"367850","name":"豊橋市上水道施設大江川水道橋","kana":"とよはししじょうすいどうしせつおおえがわすいどうきょう","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市牛川町字向堹下22-１地先","lat":34.782001,"lng":137.416962,"geo_status":"geocoded","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造桁橋、橋長11m、幅員3.6m","structure_material":"鉄筋コンクリート造桁橋","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0526","desc":"下条取水場と小鷹野浄水場を結ぶ水道道路の一部で、大江川に斜行してかかる鉄筋コンクリート造桁橋。2本のＴ桁と高欄を兼ねた耳桁からなる。親・中柱頂部を球形、高欄天端を蒲鉾形、桁下端をアーチ状につくるなど装飾に富み、単調な沿道景観に変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012555"},{"id":"00012556","register_sub_id":"101","register_pk":"367851","name":"豊橋市上水道施設小鷹野浄水場緩速ろ過池","kana":"とよはししじょうすいどうしせつおだかのじょうすいじょうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市東小鷹野二丁目9-3","lat":34.76717,"lng":137.430481,"geo_status":"geocoded","era":"昭和4年／昭和6年増設","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、面積5236㎡","structure_material":"鉄筋コンクリート造","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0527","desc":"豊橋市街東部にある浄水場の中央部に設けられる鉄筋コンクリート造、無蓋の長方形水槽。南北5槽に分かれ、各槽の西側に流入口、東側に調整井を設ける。水槽縁辺に花崗岩を張り、流入口を馬蹄形とするなど、丁寧なつくりが時代感覚を伝える現役の浄水施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012556"},{"id":"00012557","register_sub_id":"101","register_pk":"367852","name":"豊橋市上水道施設小鷹野浄水場旧ポンプ室","kana":"とよはししじょうすいどうしせつおだかのじょうすいじょうきゅうぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市東小鷹野二丁目9-3","lat":34.76717,"lng":137.430481,"geo_status":"geocoded","era":"昭和4年／昭和56年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積174㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0528","desc":"敷地の南端、正門脇に東面して建つ。鉄筋コンクリート造平屋建、陸屋根で、正面中央の玄関部を僅かに出し、両端にバルコニー付の窓を設ける。重量感のある石造風の外観、窓上部や軒廻り等各所に施された幾何学模様の細部装飾など、特色ある意匠の浄水場施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012557"},{"id":"00012554","register_sub_id":"101","register_pk":"367849","name":"豊橋市上水道施設下条取水場旧ポンプ室","kana":"とよはししじょうすいどうしせつげじょうしゅすいじょうきゅうぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市下条西町字三ノ下60","lat":34.797802,"lng":137.408829,"geo_status":"geocoded","era":"昭和4年／昭和51年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋地下1階建、建築面積137㎡","structure_material":"鉄筋コンクリート造平屋地下1階建","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0525","desc":"豊橋市街北方の豊川東岸にある取水場の中央に建つ。鉄筋コンクリート造平屋建、東西棟の切妻造で、南面に陸屋根の玄関ポーチを突出する。外壁は石造風で、半円アーチの縦長窓を並べる。窓回りや軒先をタイルで縁取るなど上品な仕上で、時代の気風を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012554"},{"id":"00012558","register_sub_id":"101","register_pk":"367853","name":"豊橋市上水道施設多米配水場旧配水池","kana":"とよはししじょうすいどうしせつためはいすいじょうきゅうはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市多米町字蝉川33-149","lat":34.763916,"lng":137.430542,"geo_status":"geocoded","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、面積1230㎡","structure_material":"鉄筋コンクリート造","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0529","desc":"小鷹野浄水場の東側にある配水場南西部に設けられた鉄筋コンクリート造、有蓋の半地下式長方形水槽で、地上部は土で被覆する。東西両端の中央に建つ管理用の建屋は、外壁タイル張や尖頭アーチ風の扉口など瀟洒に仕上げる。昭和前期の浄水施設の構成を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012558"},{"id":"00016392","register_sub_id":"101","register_pk":"536459","name":"名古屋市演劇練習館（旧稲葉地配水塔）","kana":"なごやしえんげきれんしゅうかん（きゅういなばじはいすいとう）","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市中村区稲葉地町一丁目47","lat":35.16643889,"lng":136.845425,"geo_status":"db","era":"昭和12年／昭和40年・平成7年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造地下1階地上5階建、建築面積478㎡","structure_material":"鉄筋コンクリート造地下1階地上5階建","registered":"2025.11.17(令和7.11.17)","register_no":"23 - 0619","desc":"名古屋駅西方の稲葉地公園内に位置する旧配水塔。鉄筋コンクリート造地下１階地上５階建。基壇上に建つ円筒形の構造体の中心と外周に長大な円柱を立てて、上部の巨大な貯水槽を支持する。古代の円形神殿を想起させる壮麗な姿が、地域のランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016392"},{"id":"00000052","register_sub_id":"101","register_pk":"101042","name":"上野市上水道水源地送水機関室","kana":"うえのしじょうすいどうすいげんちそうすいきかんしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県伊賀市小田町沢ノ谷646","lat":34.78160228,"lng":136.12655121,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造平屋建、トタン葺、建築面積81㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"24 － 0001","desc":"鉄筋コンクリート造，平屋建になり，背面側に汲み上げ用の円筒形の井戸等が接続する。機関室の外観は，基壇様に見せる腰壁の石張りやバルコニーを持つ玄関ポーチ，上部半円形の窓枠に様式にとらわれない素朴な意匠となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000052"},{"id":"00002297","register_sub_id":"101","register_pk":"103287","name":"旧天王貯水池","kana":"きゅうてんのうちょすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府堺市堺区中三国ヶ丘町3-78-1、2","lat":34.573982,"lng":135.489853,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦及びコンクリート造、面積886㎡","structure_material":"煉瓦及びコンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"27 － 0141","desc":"市北部にある煉瓦及びコンクリート造貯水池。総面積６６２㎡の２つの貯水槽が，スパン約３．６ｍの煉瓦造ヴォールトで覆われる。上部を曲線状にした出入口と，帯・笠石に花崗岩を用い楔石をダイヤモンド状山切とした出入口を構える。設計は野口広衛。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002297"},{"id":"00001288","register_sub_id":"101","register_pk":"102278","name":"水道記念館（旧柴島浄水場送水ポンプ場）","kana":"すいどうきねんかん（きゅうくにじまじょうすいじょうそうすいぽんぷじょう）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市東淀川区柴島1-3-1","lat":34.724361,"lng":135.505386,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造，建築面積1758㎡","structure_material":"煉瓦造","registered":"1999.08.23(平成11.08.23)","register_no":"27 － 0072","desc":"大阪市水道の拡張時につくられた煉瓦造，平屋建の建物。赤煉瓦を基調にして要所に花崗岩を混ぜた外観の意匠が特徴で，特に中央部にあるアーチ上部の煉瓦と石を交互に用いた仕上げが美しい。設計は宗兵蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001288"},{"id":"00003296","register_sub_id":"101","register_pk":"104286","name":"旧朝日町浄水場配水塔","kana":"きゅうあさひまちじょうすいじょうはいすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県高砂市高砂町朝日町1-2-1","lat":34.754601,"lng":134.804077,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄骨造、高さ26m","structure_material":"鉄骨造","registered":"2003.03.18(平成15.03.18)","register_no":"28 － 0121","desc":"加古川の水を利用し，高砂町へ給水するために建設された旧朝日町浄水場の配水塔。リベット接合の６本の鉄脚が円筒形水槽を支え，上部には棟飾付の八角錐屋根をかける。鋼材は官営八幡製鉄所製，組立加工は川崎造船所であり，我国初期の鉄骨造配水塔の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003296"},{"id":"00004483","register_sub_id":"101","register_pk":"105473","name":"旧神戸居留地煉瓦造下水道","kana":"きゅうこうべきょりゅうちれんがぞうげすいどう","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県神戸市中央区浪花町・明石町","lat":34.68829301,"lng":135.19097149,"geo_status":"db","era":"明治2～4","year":1869,"year_source":"converted","year_min":1869,"year_max":1869,"year_label":null,"structure":"煉瓦造円形管90m及び卵形管1.5m","structure_material":"煉瓦造円形管90m及び卵形管1.5m","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0174","desc":"神戸旧外国人居留地の浪速町筋と明石町筋に残る下水施設。口径約９０ｃｍ円形管９０ｍと，口径６０×４６ｃｍ卵形管１．５ｍからなり，いずれも煉瓦半枚厚。我国最初期の近代下水施設であるとともに，最初期の煉瓦造構造物のひとつ。英国人技師ハートの設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004483"},{"id":"00000994","register_sub_id":"101","register_pk":"101984","name":"神戸市水道局烏原立ケ畑堰堤（烏原ダム）","kana":"こうべしすいどうきょくからすはらたちがはたえんてい（からすはらだむ）","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県神戸市兵庫区烏原町山郡","lat":34.69153033,"lng":135.15866147,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"コンクリート造堰堤，高さ33m，長さ122m","structure_material":"コンクリート造堰堤","registered":"1998.12.11(平成10.12.11)","register_no":"28 － 0034","desc":"神戸市水道第１次拡張時の水源となる水道用大規模堰堤で，当初は堤高３３ｍ，堤長１２２ｍ，堤体敷幅２７ｍ。後に２．７ｍ程嵩上げしている。粗石コンクリート造石貼の重力ダムで，平面形状は半径１８０ｍのゆるやかな弧を描く。工事長は佐野藤次郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000994"},{"id":"00000995","register_sub_id":"101","register_pk":"101985","name":"神戸市水道局千苅堰堤（千苅ダム）","kana":"こうべしすいどうきょくせんがりえんてい（せんがりだむ）","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市北区道場町生野","lat":34.87635318,"lng":135.27004011,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"コンクリート造堰堤，高さ42m，長さ106m","structure_material":"コンクリート造堰堤","registered":"1998.12.11(平成10.12.11)","register_no":"28 － 0035","desc":"神戸市水道第２次拡張時の水源地ダム。堤高４２ｍ，堤長１０６ｍ，堤体敷幅４２ｍの規模で，取水塔から右岸までの間に幅３ｍの放流口１７個を有す。粗石コンクリート造石貼の直線重力ダムで，明治４４年５月の起工になる。技師長は佐野藤次郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000995"},{"id":"00007099","register_sub_id":"101","register_pk":"108081","name":"旧上久下村営上滝発電所","kana":null,"category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県丹波市山南町上滝字八ヶ坪1312-2他","lat":35.08180759,"lng":135.10438569,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積59㎡、橋付","structure_material":"煉瓦造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0355","desc":"市南部を東西に流れる篠山川の右岸に築かれた旧水力発電所施設。桁行９．２ｍ梁間６．５ｍ、切妻造、煉瓦造２階建で、外装イギリス積とし、１階に長方形上下窓、２階には欠円アーチ形の窓を配する。村が独自で建設、運営した近代水力発電施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007099"},{"id":"00000253","register_sub_id":"101","register_pk":"101243","name":"旧京都中央電話局上分局","kana":"きゅうきょうとちゅうおうでんわきょくかみぶんきょく","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市上京区中筋通丸太町下る駒之町561-1","lat":35.01739545,"lng":135.770767,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造3階建，瓦葺，建築面積745㎡","structure_material":"鉄筋コンクリート造3階建","registered":"1997.07.15(平成9.07.15)","register_no":"26 － 0006","desc":"逓信省技師吉田鉄郎の設計。施工清水組。吉田の表現主義から合理主義建築へ展開する過程を知ることのできる作品の一つ。現存するRC造電話局舎の中でも最も古い作品の一つ。鴨川の右岸に位置し、その特異な外観は近代教との河岸景観を特徴づけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000253"},{"id":"00005285","register_sub_id":"101","register_pk":"106273","name":"竹田火の見やぐら","kana":"たけだひのみやぐら","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市伏見区竹田狩賀町103","lat":34.9479772,"lng":135.75618952,"geo_status":"db","era":"大正12／平成17曳家","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄骨造、鉄板葺、高さ12m","structure_material":"鉄骨造","registered":"2006.03.02(平成18.03.02)","register_no":"26 － 0209","desc":"竹田村消防組第二支部の装備品として建設。山型鋼の鉄骨造，総高１２ｍで，地上を含めて６段の台形平面を徐々に逓減させた構成とし，一辺１．２ｍの正方形平面の望楼部は宝形造の木造鉄板葺屋根を架ける。現存例が少ない鉄骨造の火の見櫓で，貴重な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005285"},{"id":"00007800","register_sub_id":"101","register_pk":"108781","name":"旧江尾発電所本館","kana":"きゅうえびはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県日野郡江府町大字久連字唐杉500-2他","lat":35.2912096,"lng":133.4741404,"geo_status":"db","era":"大正8／平成12改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造平屋一部2階建、鉄板葺、建築面積216㎡","structure_material":"石造平屋一部2階建","registered":"2009.08.07(平成21.08.07)","register_no":"31-0155","desc":"日野川にほぼ面する敷地に東面して建つ旧水力発電所施設。石造平屋建の発電機室の北側に２階建の変圧室を接続し、全体でＬ字形平面としたもので、正面には欠円アーチ形の窓を穿ち、発電機室には越屋根を設ける。外壁全体に江戸切仕上げの切石を積む重厚な外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007800"},{"id":"00003299","register_sub_id":"101","register_pk":"104289","name":"旧倉吉町水源地ポンプ室","kana":"きゅうくらよしちょうすいげんちぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県倉吉市余戸谷町3078-1","lat":35.42764021,"lng":133.81062945,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建、スレート葺、建築面積77㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"31 － 0057","desc":"天神川の支流小鴨川に面する余戸谷町水源地内にある。切妻造，平入で，正面及び側面に櫛形欄間窓を左右対称に配し，腰を瘤出仕上の切石布積とする。正面中央のレリーフ付き三角ペディメント，平側のパラペットなど，小規模ながら洋風意匠を積極的に取り込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003299"},{"id":"00003300","register_sub_id":"101","register_pk":"104290","name":"旧倉吉町水源地量水室","kana":"きゅうくらよしちょうすいげんちりょうすいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県倉吉市余戸谷町3111-2","lat":35.42752255,"lng":133.81183445,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積5.0㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"31 － 0058","desc":"余戸谷町水源地から東方に１００ｍ程離れた住宅地に位置する倉吉市創設水道の施設で，配水池から市街地に送られる上水の計量に用いた。方形平面で，四周に廻した軒蛇腹・パラペット，正面入口上部の扁額・レリーフなどが，豊かな街路景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003300"},{"id":"00002301","register_sub_id":"101","register_pk":"103291","name":"旧米子市水源地記念碑","kana":"きゅうよなごしすいげんちきねんひ","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県米子市車尾南2-8-1","lat":35.427536,"lng":133.363617,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造、高さ7m","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"31 － 0044","desc":"ポンプ室に対面して建つ記念碑。ＲＣ造花崗岩貼り。アーチを施した矩形の土台に，付柱を放射状に配した円筒を載せ，相輪状の円盤を先端に重ねるアールデコ風のデザイン。設計は伊藤正文。若槻礼次郎をはじめ水道事業に寄与した人々を銘記する扁額がとりつく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002301"},{"id":"00002299","register_sub_id":"101","register_pk":"103289","name":"旧米子市水源地旧ポンプ室","kana":"きゅうよなごしすいげんちきゅうぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県米子市車尾南2-8-1","lat":35.427563,"lng":133.363464,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積175㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"31 － 0042","desc":"米子市上水道の旧水源地施設の一。ＲＣ造平屋建で，赤い桟瓦を葺く。幅太の付柱を軒まで立ち上げ，柱間に半円アーチ窓を並べる。また，東側に入口を兼ねた塔屋，西側にアプス状の突出部を配するなど全体に教会堂を思わせる外観。現在は水道記念館として活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002299"},{"id":"00002300","register_sub_id":"101","register_pk":"103290","name":"旧米子市水源地水神社","kana":"きゅうよなごしすいげんちみずじんじゃ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県米子市車尾南2-8-1","lat":35.427479,"lng":133.363342,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積0.8㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"31 － 0043","desc":"導水１５周年を記念し，水源地構内の北西，ポンプ室の奥脇に建設された水神社。正統的な一間社流造で，高い基壇の上に建ち，身舎のせいが高く，深い軒で屋根が強調されるなど小規模ながら存在感を持つ。旧水源地施設を構成する要素として貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002300"},{"id":"00008160","register_sub_id":"101","register_pk":"132601","name":"大社湯（第三鶴の湯）浴場及び主屋","kana":"たいしゃゆ（だいさんつるのゆ）よくじょうおよびしゅおく","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県倉吉市新町3-2293他","lat":35.43289379,"lng":133.82034903,"geo_status":"db","era":"明治後期／大正期増築・昭和中期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺、建築面積137㎡","structure_material":"木造平屋一部2階建","registered":"2010.04.28(平成22.04.28)","register_no":"31 － 0157","desc":"東西棟の木造２階建、建築面積１３７㎡、切妻造桟瓦葺である。１階西半部を浴場、東半部と２階を居住部分とし、浴場はさらに東西に二分して男湯と女湯とする。外観は住宅風で、周囲の景観と調和しており、明治後期における公衆浴場の形態をよく保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008160"},{"id":"00007117","register_sub_id":"101","register_pk":"108099","name":"忌部浄水場一号濾過池","kana":"いんべじょうすいじょういちごうろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市東忌部町字木ノ下35","lat":35.4235829,"lng":133.0515599,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"コンクリート造、面積683㎡、調整井上屋付","structure_material":"コンクリート造","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0065","desc":"浄水場中央で、東西に並置された濾過池のうち、西端に位置する。東西２２ｍ、南北３１ｍ規模の長方形平面としたコンクリート造構造物で、壁面法勾配１分とし、北面中央には上屋付調整井を配す。第一次拡張工事の際に、既存濾過池とほぼ同規模で建設された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007117"},{"id":"00007115","register_sub_id":"101","register_pk":"108097","name":"忌部浄水場旧弁室及び着水井","kana":"いんべじょうすいじょうきゅうべんしつおよびちゃくすいせい","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市東忌部町字木ノ下35","lat":35.423527,"lng":133.051559,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"コンクリート造、面積34㎡","structure_material":"コンクリート造","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0063","desc":"貯水池堰堤より約５００ｍ北東の浄水場の西端に位置する。貯水池より送られる原水を、浄水場内で最初に受けるコンクリート造構造物。西側に弁室と東側に量水用ノッチ付の着水井を配し、天端には花崗岩の笠石を置く。松江市水道第一拡張工事に関連する遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007115"},{"id":"00007121","register_sub_id":"101","register_pk":"108103","name":"忌部浄水場五号濾過池","kana":"いんべじょうすいじょうごごうろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市東忌部町字木ノ下35","lat":35.42368769,"lng":133.05172163,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"コンクリート造、面積695㎡、調整井上屋付","structure_material":"コンクリート造","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0069","desc":"四号濾過池の東側に隣接する。三号・四号濾過池と同規模、同形式の緩速濾過池。濾過池は表面モルタル塗仕上げとし、深さは２．７ｍ、壁面は法勾配１分７厘で築き、底部は中央の溝に向かい１／１５０勾配で傾斜する。松江市創設水道施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007121"},{"id":"00007119","register_sub_id":"101","register_pk":"108101","name":"忌部浄水場三号濾過池","kana":"いんべじょうすいじょうさんごうろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市東忌部町字木ノ下35","lat":35.42363322,"lng":133.05163779,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"コンクリート造、面積692㎡、調整井上屋付","structure_material":"コンクリート造","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0067","desc":"二号濾過池の東側、放水井の北側に位置する。東西２２ｍ、南北３１ｍ規模の長方形平面としたコンクリート造構造物で、天端には花崗岩の笠石を置く。北側中央には円形平面の上屋付調整井を配する。松江市の創設水道施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007119"},{"id":"00007123","register_sub_id":"101","register_pk":"108105","name":"忌部浄水場集合井","kana":"いんべじょうすいじょうしゅうごうせい","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市東忌部町字木ノ下35","lat":35.423729,"lng":133.051666,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"コンクリート造、面積14㎡、上屋付","structure_material":"コンクリート造","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0071","desc":"四号濾過池の北側に位置する。直径１．８ｍ、深さ４．１ｍの円形構造物で、上屋を付ける。上屋は表面モルタル塗仕上げで、正面に円柱を配して欠円アーチ形の庇を支える。濾過池増設に伴い水量の増加した濾過水を、円滑に配水池へ送水するために設置された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007123"},{"id":"00007116","register_sub_id":"101","register_pk":"108098","name":"忌部浄水場導水溝及び放水井","kana":"いんべじょうすいじょうどうすいこうおよびほうすいせい","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市東忌部町字木ノ下35","lat":35.4235429,"lng":133.05163785,"geo_status":"db","era":"大正7・昭和4","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"導水溝 コンクリート造、延長60m 放水井 コンクリート造、面積17㎡","structure_material":"導水溝 コンクリート造","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0064","desc":"着水井から連続して築かれる。水道創設時の施設である半径１．８ｍの円形放水井に、東西に長い延長６０ｍ、幅１．２ｍの導水溝を接続したもので、導水溝には桁橋３基を架ける。いずれもコンクリート造。着水井から濾過池へ原水を円滑に分配するための施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007116"},{"id":"00007118","register_sub_id":"101","register_pk":"108100","name":"忌部浄水場二号濾過池","kana":"いんべじょうすいじょうにごうろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市東忌部町字木ノ下35","lat":35.42360885,"lng":133.05160142,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"コンクリート造、面積683㎡、調整井上屋付","structure_material":"コンクリート造","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0066","desc":"一号濾過池の東側に隣接する。一号濾過池と同規模、同形式の緩速濾過池。濾過池の天端には花崗岩の笠石を敷く。調整井は半径１．８ｍで、上屋は鉄筋コンクリート造、正面に簡略化した柱頭飾と台座を付けた角柱と隅柱を配し、頂部にも密に柱型を表す独特の外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007118"},{"id":"00007120","register_sub_id":"101","register_pk":"108102","name":"忌部浄水場四号濾過池","kana":"いんべじょうすいじょうよんごうろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市東忌部町字木ノ下35","lat":35.42366153,"lng":133.05168021,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"コンクリート造、面積695㎡、調整井上屋付","structure_material":"コンクリート造","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0068","desc":"三号濾過池の東側に隣接する。三号濾過池と同規模、同形式の緩速濾過池。底部に敷き詰められた細砂、礫、煉瓦を通過し濾過された原水が、底部中央に位置する南北方向に掘り込まれた１／１００勾配の縦溝を伝って調整井に至る。松江市創設水道施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007120"},{"id":"00007122","register_sub_id":"101","register_pk":"108104","name":"忌部浄水場六号濾過池","kana":"いんべじょうすいじょうろくごうろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市東忌部町字木ノ下35","lat":35.42371248,"lng":133.05176405,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"コンクリート造、面積692㎡、調整井上屋付","structure_material":"コンクリート造","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0070","desc":"五号濾過池の東側に隣接する。三号・四号・五号濾過池と同規模、同形式の緩速濾過池。北側中央に設けられた調整井は半径１．２ｍの円形平面。上屋は、表面モルタル塗仕上げとし、基部に半円筒形、軒蛇腹には扁平六角形を連続的にあしらう幾何学的意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007122"},{"id":"00007124","register_sub_id":"101","register_pk":"108106","name":"旧床几山配水池","kana":"きゅうしょうぎさんはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市上乃木1-1265","lat":35.45470233,"lng":133.05771462,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"コンクリート造、面積1191㎡","structure_material":"コンクリート造","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0072","desc":"忌部浄水場より約３．５ｋｍ北方に位置する床几山の山頂に築かれる。東西３７ｍ、南北３２ｍ規模のコンクリート造構造物で、中央の監視路を隔てて東・西２室に分け、天井は連続ヴォールトとする。監視路の入口には石貼の壁を建ち上げる。創設水道施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007124"},{"id":"00007125","register_sub_id":"101","register_pk":"108107","name":"旧床几山配水池計量室","kana":"きゅうしょうぎさんはいすいちけいりょうしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市上乃木1-1265","lat":35.45482234,"lng":133.05779631,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積6.1㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0073","desc":"配水池構内の東側に位置する。市街地へ配水する水道水の計量施設。２．５ｍ四方の鉄筋コンクリート造構造物で、表面モルタル吹付とする。ヴォールト屋根で、正面中央に鉄扉をたて、両脇にエンタシスを強調したイオニア式風の円柱を飾る独特な造形になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007125"},{"id":"00007126","register_sub_id":"101","register_pk":"108108","name":"旧床几山配水池門","kana":"きゅうしょうぎさんはいすいちもん","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市上乃木1-1265","lat":35.45461328,"lng":133.05784732,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"石造門柱、間口2.9m、脇門付","structure_material":"石造門柱","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0074","desc":"配水池構内の東端部に位置する旧床几山配水池の表門。間口２．９ｍ、高さ２．６ｍの、切石で築かれた角柱で、四面に江戸切仕上げ等を施す。簡素なつくりだが、基礎石、帯石、笠石に白花崗岩を用いて外観を引き締めるなど、意匠上の工夫がうかがえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007126"},{"id":"00007113","register_sub_id":"101","register_pk":"108095","name":"千本貯水池堰堤","kana":"せんぼんちょすいちえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市西忌部町字細田","lat":35.41963981,"lng":133.04513968,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長109m、堤高16m、副堰堤付","structure_material":"重力式コンクリート造堰堤","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0061","desc":"宍道湖に注ぐ忌部川の上流に位置する水源地堰堤。堤長１０９ｍ、堤高１６ｍの重力式コンクリート造堰堤で、越流式とし、下流側に副堰堤を付ける。堤体内部に粗石コンクリートを用い、表面は間知石の谷積とする。山陰地方初のコンクリートを用いた水源地堰堤。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007113"},{"id":"00007114","register_sub_id":"101","register_pk":"108096","name":"千本貯水池堰堤管理橋","kana":"せんぼんちょすいちえんていかんりきょう","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市西忌部町字細田","lat":35.419827,"lng":133.045517,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"コンクリート造4連アーチ橋、橋長18m、幅員2.0m","structure_material":"コンクリート造4連アーチ橋","registered":"2008.04.18(平成20.04.18)","register_no":"32 － 0062","desc":"貯水池堰堤の副堰堤の直下に位置する。橋長１８ｍ、幅員２．０ｍ規模の充腹式コンクリート造４連アーチ橋で、欠円アーチ形のアーチ部分は石積風に仕上げる。中央の橋脚は、周囲に石積を施し、転石から保護する。堰堤とともに水源地の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007114"},{"id":"00010503","register_sub_id":"101","register_pk":"199451","name":"中国電力株式会社澄川発電所本館","kana":"ちゅうごくでんりょくかぶしきがいしゃすみかわはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県益田市匹見町澄川イ1097","lat":34.596886,"lng":131.94212,"geo_status":"db","era":"昭和18","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階及び地下2階建、建築面積346㎡","structure_material":"鉄筋コンクリート造平屋一部2階及び地下2階建","registered":"2015.03.26(平成27.03.26)","register_no":"32 － 0171","desc":"匹見川水系に建つ水路式発電所本館。鉄筋コンクリート造モルタル塗で、南側に高い内部空間をもつ平屋一部地下二階建の発電機室、北側に二階建の事務室を雁行配置する。いずれも装飾を排したモダニズムの内外観で、戦時下の質実を旨とした設計様相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010503"},{"id":"00010504","register_sub_id":"101","register_pk":"199452","name":"中国電力株式会社匹見発電所本館","kana":"ちゅうごくでんりょくかぶしきがいしゃひきみはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県益田市匹見町匹見イ1702-3","lat":34.570581,"lng":132.031431,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"コンクリートブロック造平屋一部2階建、鉄板葺、建築面積199㎡","structure_material":"コンクリートブロック造平屋一部2階建","registered":"2015.03.26(平成27.03.26)","register_no":"32 － 0172","desc":"匹見川水系に建つ水路式発電所本館。大振りのコンクリートブロックを積み上げた平屋建で建ちの高い発電機室と、二階建の事務室からなる。外観は柱形を並べ、方形の開口部を二段に重ねて上部に欠円アーチのニッチを表す。洋風の意匠を随所に配した瀟洒な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010504"},{"id":"00006753","register_sub_id":"101","register_pk":"107736","name":"美保関おかげの井戸","kana":"みほのせきおかげのいど","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県松江市美保関町美保関598","lat":35.56232331,"lng":133.30588254,"geo_status":"db","era":"文久元","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"石造、面積2.7㎡","structure_material":"石造","registered":"2007.10.02(平成19.10.02)","register_no":"32 － 0054","desc":"美保神社の門前に位置する。乱積で築いた深さ約３．８ｍの円筒形井戸の天端に地覆石を敷き、その上に高さ０．５７ｍ、幅０．７３ｍの石板を八角形状に立ち並べる。住民のほか来港者や参詣者の用にも供され、人々の交流の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006753"},{"id":"00005917","register_sub_id":"101","register_pk":"106902","name":"入発電所水槽","kana":"いりはつでんしょすいそう","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県苫田郡鏡野町入字樋が峪","lat":35.11227404,"lng":133.900131,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"鉄筋コンクリート造、面積245㎡、石垣付","structure_material":"鉄筋コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0127","desc":"奥津発電所本館より約１２ｋｍ南方の吉井川上流域に位置する。導水路の末端部に築かれ，本館に流入する発電用水の流下水量調節を行い，東側には余水吐を設ける。西面に階段，南面には擁壁を付けいずれも玉石積で築く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005917"},{"id":"00005919","register_sub_id":"101","register_pk":"106904","name":"入発電所鉄管路擁壁及び本館擁壁","kana":"いりはつでんしょてっかんろようへきおよびほんかんようへき","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県苫田郡鏡野町入字樋が峪964","lat":35.11224034,"lng":133.90008275,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"石造、延長67m","structure_material":"石造","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0129","desc":"水槽と本館を結ぶ鉄管路の両脇に築かれた延長３６ｍの擁壁と，本館の北側及び東側に築かれた折れ曲がり延長３１ｍの擁壁よりなる。大小の玉石を組み合わせて練積で築く。備作電気株式会社により建設された水力発電所施設の構成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005919"},{"id":"00005918","register_sub_id":"101","register_pk":"106903","name":"入発電所本館","kana":"いりはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県苫田郡鏡野町入字樋が峪964","lat":35.11214592,"lng":133.89990517,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積189㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0128","desc":"水槽の約３０ｍ西方に位置する。桁行１５ｍ，梁間１２ｍで，切妻造，銅板葺の木造平屋建で，南面に事務所，西面には電池室を張り出す。小屋組はキングポストトラス，外装はモルタル塗仕上げとする。吉井川水系発電所施設の中で，現存する最古の本館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005918"},{"id":"00005907","register_sub_id":"101","register_pk":"106892","name":"奥津発電所一号蓋渠","kana":"おくつはつでんしょいちごうがいきょ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原地先","lat":35.28400821,"lng":133.92870072,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"石造及び鉄筋コンクリート造、延長122m","structure_material":"石造及び鉄筋コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0117","desc":"一号水路橋の下流側に連続して築かれる。ほぼ長方形断面の鉄筋コンクリート造構造物の側壁を，練積，谷積の石造壁体で補強した直線状の延長１２２ｍの構造物。中国合同電気株式会社により建設された水力発電所施設の構成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005907"},{"id":"00005906","register_sub_id":"101","register_pk":"106891","name":"奥津発電所一号水路橋","kana":"おくつはつでんしょいちごうすいろきょう","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原地先","lat":35.283966,"lng":133.928787,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造ラーメン橋、橋長18m","structure_material":"鉄筋コンクリート造ラーメン橋","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0116","desc":"吉井川取水堰堤より約３７０ｍ下流に位置し，吉井川に合流する木路谷川に架かる。橋長１８ｍ，スパン６．１ｍ規模の，鉄筋コンクリート造の門形バランストラーメン橋を，水路樋と一体的に築く。高さ８．０ｍの末広がり状の橋脚には水平梁を付加し安定を図る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005906"},{"id":"00005912","register_sub_id":"101","register_pk":"106897","name":"奥津発電所オロ谷川取水堰堤","kana":"おくつはつでんしょおろたにがわしゅすいえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町下齋原字上原田辺り地先","lat":35.260994,"lng":133.920502,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長4.2m、堤高2.1m","structure_material":"重力式コンクリート造堰堤","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0122","desc":"四号水路橋の南方で幹線水路に合流する支線水路の施設で，吉井川右支オロ谷川に築かれる。堤長４．２ｍ，堤高２．１ｍ規模で，上流側法勾配１分，下流側法勾配１割５分とした越流式の重力式練積堰堤。堤体の右岸寄りにアーチ形の排砂口を穿つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005912"},{"id":"00006060","register_sub_id":"101","register_pk":"107045","name":"奥津発電所会流池","kana":"おくつはつでんしょかいりゅうち","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字樽原地先","lat":35.22490214,"lng":133.91945059,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積1299㎡","structure_material":"鉄筋コンクリート造","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0149","desc":"上斎原発電所本館の南方に位置する。延長約１６０ｍに及ぶ長大な鉄筋コンクリート造構造物で，川に面する側壁は花崗岩の谷積で補強する。奥津発電所の水路施設の一つで，上斎原発電所水槽からの余水と本館からの放水を取り入れ，用水の有効利用を図る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006060"},{"id":"00005908","register_sub_id":"101","register_pk":"106893","name":"奥津発電所木路谷川取水堰堤","kana":"おくつはつでんしょきろたにがわしゅすいえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字向後谷川辺り地先","lat":35.28324263,"lng":133.92825776,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長12m、堤高2.7m、排砂門及び護岸付","structure_material":"重力式コンクリート造堰堤","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0118","desc":"一号蓋渠の西方で幹線水路に合流する支線水路の施設で，吉井川右支木路谷川に築かれる。堤長１２ｍ，堤高２．７ｍ規模の重力式練積堰堤で，右岸側には鉄筋コンクリート造排砂門を付ける。石積護岸や単アーチの取水口も含め，取水に係る設備全体が良好に残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005908"},{"id":"00005910","register_sub_id":"101","register_pk":"106895","name":"奥津発電所三号水路橋","kana":"おくつはつでんしょさんごうすいろきょう","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字川辺り地先","lat":35.27782393,"lng":133.92357453,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造ラーメン橋、橋長18m","structure_material":"鉄筋コンクリート造ラーメン橋","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0120","desc":"一号蓋渠より約６９０ｍ下流に位置し，吉井川右支湯の谷川に架かる。鉄筋コンクリート造，３径間の門形バランストラーメン橋で，橋長１８ｍ，スパン６．１ｍとする。上端３．０ｍ，下端２．７ｍのほぼ台形断面を有する水路樋と一体的に築く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005910"},{"id":"00005913","register_sub_id":"101","register_pk":"106898","name":"奥津発電所調整池","kana":"おくつはつでんしょちょうせいち","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町奥津川西字水村大畑","lat":35.229137,"lng":133.913971,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、面積9499㎡","structure_material":"鉄筋コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0123","desc":"四号水路橋より約４．２㎞下流に位置する。南北に細長い，面積９４９９㎡の大規模な高架式の鉄筋コンクリート造構造物。３ｍ間隔のグリッド状に配された柱で底部を支持し，４５度傾斜の外周壁体を水平梁で連結された扶壁で支えるという，独特の構法を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005913"},{"id":"00005909","register_sub_id":"101","register_pk":"106894","name":"奥津発電所人形仙谷川取水堰堤","kana":"おくつはつでんしょにんぎょうせんたにがわしゅすいえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字土取場地先","lat":35.27829143,"lng":133.92746983,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長4.4m、堤高1.5m","structure_material":"重力式コンクリート造堰堤","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0119","desc":"一号蓋渠より約５００ｍ下流の地点で幹線水路に合流する支線水路の施設で，吉井川右支人形仙谷川に築かれる。堤長４．４ｍ，堤高１．５ｍ規模で，上流側法勾配１分，下流側法勾配１割３分とした越流式の重力式練積堰堤。支渓を利用した発電所施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005909"},{"id":"00005916","register_sub_id":"101","register_pk":"106901","name":"奥津発電所本館擁壁","kana":"おくつはつでんしょほんかんようへき","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町奥津川西字神田560","lat":35.22537833,"lng":133.91922055,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"石造及び鉄筋コンクリート造、延長185m","structure_material":"石造及び鉄筋コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0126","desc":"本館西側に築かれた擁壁と，吉井川との境界に築かれた護岸擁壁からなる。花崗岩を用いた谷積の練積擁壁で，護岸擁壁には高さ０．８５ｍの鉄筋コンクリート造高欄を付け，ほぼ中央に余水路隧道の坑口を設ける。本館と共に近代発電所の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005916"},{"id":"00005904","register_sub_id":"101","register_pk":"106889","name":"奥津発電所吉井川取水堰堤","kana":"おくつはつでんしょよしいがわしゅすいえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字樽原地先","lat":35.28411731,"lng":133.93225331,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長34m、堤高3.3m、魚道付","structure_material":"重力式コンクリート造堰堤","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0115","desc":"岡山県東部をほぼ南北に貫流する吉井川の上流域に位置する水路式水力発電所の施設。岩盤を利用して築かれた堤長３４ｍ，堤高３．３ｍ規模の重力式練積堰堤で，越流式とし，右岸側に側面谷積とした曲線状の階段式魚道を付ける。幹線水路の始点となる構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005904"},{"id":"00005911","register_sub_id":"101","register_pk":"106896","name":"奥津発電所四号水路橋","kana":"おくつはつでんしょよんごうすいろきょう","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町下齋原字上原田辺り地先","lat":35.25754135,"lng":133.9294389,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造ラーメン橋、橋長18m","structure_material":"鉄筋コンクリート造ラーメン橋","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0121","desc":"三号水路橋より約１７６０ｍ下流に位置し，吉井川右支オロ谷川に架かる。鉄筋コンクリート造，３径間の門形バランストラーメン橋で，橋長１８ｍ，スパン６．１ｍとし，末広がり状の橋脚の下部工には，連続フーチング基礎を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005911"},{"id":"00006055","register_sub_id":"101","register_pk":"107040","name":"上斎原発電所赤和瀬川取水堰堤","kana":"かみさいばらはつでんしょあかわせがわしゅすいえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字石越地先","lat":35.30216104,"lng":133.94489107,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長12m、堤高2.3m、制水門付","structure_material":"重力式コンクリート造堰堤","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0142","desc":"吉井川取水堰堤より約１．５ｋｍ西方，天王川水路へ合流する赤和瀬川水路の上流に位置する。岩盤上に築かれた堤長１２ｍ，堤高２．３ｍの重力式コンクリート造堰堤で，表面は花崗岩の谷積とする。左岸の取水部に塵芥除去用スクリーンの設置施設をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006055"},{"id":"00006056","register_sub_id":"101","register_pk":"107041","name":"上斎原発電所池河川取水堰堤","kana":"かみさいばらはつでんしょいけごうがわしゅすいえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字十二川地先","lat":35.30372729,"lng":133.93966598,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長12m、堤高3.1m、制水門付","structure_material":"重力式コンクリート造堰堤","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0143","desc":"天王川水路へ合流する池河川水路の上流に位置する。堤長１２ｍ，堤高３．１ｍ規模の重力式コンクリート造堰堤で，下流法勾配１割１分，表面谷積とし，堤体左岸寄りにアーチ形の排砂口を穿つ。施工時の排水の便も考慮され，急勾配の岩盤斜面の頂部に築かれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006056"},{"id":"00006066","register_sub_id":"101","register_pk":"107051","name":"上斎原発電所池河川水路沈砂池","kana":"かみさいばらはつでんしょいけごうがわすいろちんさち","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字川向地先","lat":35.30396459,"lng":133.93958255,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積78㎡","structure_material":"鉄筋コンクリート造","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0144","desc":"池河川取水堰堤の約４０ｍ下流に位置する。面積７８㎡規模の側壁練積の構造物で，山側の東側壁に沿って鉄筋コンクリート造のスラブを張り出し，周辺からの土砂の流入を防ぐ。底版は西側に向けて下り勾配をつけ，西側壁の排砂門から土砂を排出するつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006066"},{"id":"00006054","register_sub_id":"101","register_pk":"107039","name":"上斎原発電所会流池","kana":"かみさいばらはつでんしょかいりゅうち","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字平作原地先","lat":35.29524651,"lng":133.95713424,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積694㎡、放水路及び管理橋付","structure_material":"鉄筋コンクリート造","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0141","desc":"吉井川取水堰堤の右岸に位置し，制水門より取り入れた水と平作原発電所からの放水を合流し，流速を低減して沈砂を行う。ほぼ櫛形平面の鉄筋コンクリート造構造物で，川と水路の境に越流堤を配し，越流堤の頂部に，橋脚を密に並べた約４５ｍ長の管理橋を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006054"},{"id":"00006057","register_sub_id":"101","register_pk":"107042","name":"上斎原発電所水槽","kana":"かみさいばらはつでんしょすいそう","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字樽原地先","lat":35.284443,"lng":133.93219,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"コンクリート造、面積497㎡","structure_material":"コンクリート造","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0146","desc":"会流池より約２．８ｋｍ下流に位置する。幹線水路の末端部にあたり，本館に流入する発電用水の流下水量調節を行う。曲線状の開渠に，沈砂機能を有するほぼ三角形平面の池を連続するつくりで，池の南側に越流堤，南側壁中央には排砂門を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006057"},{"id":"00006059","register_sub_id":"101","register_pk":"107044","name":"上斎原発電所鉄管路擁壁及び本館擁壁","kana":"かみさいばらはつでんしょてっかんろようへきおよびほんかんようへき","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字樽原1161-3","lat":35.28490398,"lng":133.93208297,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造、総延長90m","structure_material":"石造","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0148","desc":"本館と水槽を結ぶ鉄管路両脇の直線状の擁壁と，本館の西側及び北側の敷地を区画する擁壁からなり，いずれも石積とする。平地の少ない山間部に施設を建設するために必要な構造物で，延長９０ｍと長大であるが，今日まで往時の姿を良好に留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006059"},{"id":"00006067","register_sub_id":"101","register_pk":"107052","name":"上斎原発電所天王川水路沈砂池","kana":"かみさいばらはつでんしょてんのうがわすいろちんさち","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字川向地先","lat":35.30022274,"lng":133.94285202,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積134㎡","structure_material":"鉄筋コンクリート造","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0145","desc":"赤和瀬川取水堰堤の約２４０ｍ下流に位置する。天王川水路を流れる発電用水の沈砂を行う。西側に築かれた越流堤から余水を流し、越流堤の南端部には排水門を設ける。東側壁に沿って長さ２０ｍのスラブを張り出し，周辺土砂の流入を防ぐ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006067"},{"id":"00006058","register_sub_id":"101","register_pk":"107043","name":"上斎原発電所本館","kana":"かみさいばらはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字樽原1163-2","lat":35.284691,"lng":133.932281,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積288㎡、放水路付","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0147","desc":"水槽より約２５０ｍ下流に位置する。桁行１６ｍ，梁間１４ｍの発電機室に，事務室や休憩室等を張り出す鉄筋コンクリート造平屋建の発電所本館で，四周に縦長窓を配す。小屋組にライズを抑えたプラットトラスを用い，天井の高い作業空間を確保する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006058"},{"id":"00006053","register_sub_id":"101","register_pk":"107038","name":"上斎原発電所吉井川取水堰堤","kana":"かみさいばらはつでんしょよしいがわしゅすいえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字平作原地先","lat":35.29526302,"lng":133.95768188,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長30m、堤高2.6m、魚道及び制水門付","structure_material":"重力式コンクリート造堰堤","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0140","desc":"平作原発電所本館の西方を流れる吉井川を横断する取水堰堤。河床と両岸に露出する岩盤をいかして，堤長３０ｍ，堤高２．６ｍの規模で築かれた重力式コンクリート造堰堤で，表面は石積とする。右岸には勾配６割で築いた魚道と６門からなる制水門が揃って残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006053"},{"id":"00005498","register_sub_id":"101","register_pk":"106486","name":"旧京橋火の見櫓","kana":"きゅうきょうばしひのみやぐら","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県岡山市北区京橋町","lat":34.65891511,"lng":133.93262109,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄骨造、高さ21m","structure_material":"鉄骨造","registered":"2006.03.27(平成18.03.27)","register_no":"33 － 0106","desc":"高さ２１ｍの鉄骨造の警鐘台。山形鋼を四脚に立てて横材を渡し，横材間をリング式ターンバックルで補強する。最上部には正方形の望楼を載せ，鉄板製宝形屋根をかける。岡山市街の東方，京橋西詰にあり，地域の歴史的景観の核として広く市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005498"},{"id":"00004635","register_sub_id":"101","register_pk":"105625","name":"京橋水管橋","kana":"きょうばしすいかんきょう","category":"生活関連","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区京橋町～中区西中島町","lat":34.65816425,"lng":133.93303066,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"鋼製5連トラス橋、橋長131m","structure_material":"鋼製5連トラス橋","registered":"2005.02.09(平成17.02.09)","register_no":"33 － 0100","desc":"市街地東方，県道京橋と平行して旭川に架かる斜橋式水管橋。鋲接平鋼と山形鋼を使い分けた，最大スパン３３ｍの５連ワーレントラス橋で，水道用鋼製橋として最初期のもの。橋脚は五角形平面のコンクリート造で，帯鉄で締め，隅部を鉄板で保護する珍しい構造。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004635"},{"id":"00004629","register_sub_id":"101","register_pk":"105619","name":"半田山配水地一号配水池","kana":"はんだやまはいすいちいちごうはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区法界院3-1","lat":34.69318415,"lng":133.93138337,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"煉瓦造及び鉄筋コンクリート造、面積335㎡","structure_material":"煉瓦造及び鉄筋コンクリート造","registered":"2005.02.09(平成17.02.09)","register_no":"33 － 0094","desc":"三野浄水場の北西に位置する半田山の標高約５０ｍの地点に築かれる。直径２１ｍの円形平面とし，内部には同心円状の２重の隔壁を設け，その頂部に煉瓦造アーチを廻らす。屋蓋はＲＣ造の欠球形ヴォールト等で築く。全国的に類例の少ない円形配水池の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004629"},{"id":"00004634","register_sub_id":"101","register_pk":"105624","name":"半田山配水地旧事務所","kana":"はんだやまはいすいちきゅうじむしょ","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区法界院3-1","lat":34.69300104,"lng":133.9316901,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"33 － 0099","desc":"一号配水池の東下に位置し，ほぼ南面して構える。桁行５間，梁間２間の木造平屋建，寄棟造，平入で，腰縦板張，その上部を下見板張とする。開口部を広くとる開放的なつくりで，四周には瓔珞飾りを廻らし，床下換気口には市章をモチーフとした金物を嵌め込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004634"},{"id":"00004631","register_sub_id":"101","register_pk":"105621","name":"半田山配水地三号配水池","kana":"はんだやまはいすいちさんごうはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県岡山市北区法界院3-1","lat":34.69336397,"lng":133.93116086,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造及び鉄筋コンクリート造、面積335㎡","structure_material":"煉瓦造及び鉄筋コンクリート造","registered":"2005.02.09(平成17.02.09)","register_no":"33 － 0096","desc":"一・二号配水池の北側に近接する円形配水池。水道創設時に予備地として造成された土地に，第一拡張工事の一環として建設。欠球形ヴォールトを中心として，ほぼ半円錐形のＲＣ造屋根構造躯体を１６本放射状に架けるなど，創設時の配水池と同じ構造形式をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004631"},{"id":"00004632","register_sub_id":"101","register_pk":"105622","name":"半田山配水地創建量水室","kana":"はんだやまはいすいちそうけんりょうすいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区法界院3-1","lat":34.692558,"lng":133.930481,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"煉瓦造平屋建、建築面積8.9㎡","structure_material":"煉瓦造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"33 － 0097","desc":"半田山の標高約３５ｍの地点に位置する，正六角形平面の煉瓦造構造物。隅部に煉瓦で柱形をつくる。正面開口部には，頂部に要石形をあしらった三角ペディメントやオーダーなどを組み合わせ，その他の壁面には花崗岩で枠取りした丸窓を配す瀟洒なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004632"},{"id":"00004633","register_sub_id":"101","register_pk":"105623","name":"半田山配水地増設量水室","kana":"はんだやまはいすいちぞうせつりょうすいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県岡山市北区法界院3-1","lat":34.692593,"lng":133.930786,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積6.6㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"33 － 0098","desc":"創建量水室の西側に近接して位置し，第三期拡張工事期に建設された正六角形平面の鉄筋コンクリート造構造物。タイル張壁面を煉瓦小口積風に見せ，窓枠や柱形等はモルタル洗出で仕上げる。やや簡略化するものの，創建量水室の意匠を踏襲した丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004633"},{"id":"00004630","register_sub_id":"101","register_pk":"105620","name":"半田山配水地二号配水池","kana":"はんだやまはいすいちにごうはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区法界院3-1","lat":34.69315001,"lng":133.93098342,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"煉瓦造及び鉄筋コンクリート造、面積335㎡","structure_material":"煉瓦造及び鉄筋コンクリート造","registered":"2005.02.09(平成17.02.09)","register_no":"33 － 0095","desc":"一号配水池西側に近接する円形配水池。地下周壁を煉瓦張コンクリート造とし，地上外壁には換気口を穿ち，中央頂部に換気塔を戴くなど，構造形式は一号と同じ。吉村長策，佐野藤次郎等が工事に関与し，国庫及び県費補助を得て建設された岡山市創設水道施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004630"},{"id":"00006045","register_sub_id":"101","register_pk":"107030","name":"平作原発電所遠藤川取水堰堤","kana":"へいさくばらはつでんしょえんどうがわしゅすいえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字遠藤地先","lat":35.27405572,"lng":133.99366727,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長18m、堤高3.0m、制水門及び石造護岸付","structure_material":"重力式コンクリート造堰堤","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0130","desc":"吉井川水系発電所施設の最上流に位置する。遠藤川水路の取水堰堤で，堤長１８ｍ，堤高３．０ｍ，下流法勾配８分の重力式コンクリート造堰堤とし，右岸には２門の制水門を川と平行に配する。堤体頂部と堤体と水叩きの接続部を曲面状につくるのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006045"},{"id":"00006047","register_sub_id":"101","register_pk":"107032","name":"平作原発電所遠藤川沈砂池","kana":"へいさくばらはつでんしょえんどうがわちんさち","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字遠藤地先","lat":35.27374563,"lng":133.9936331,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造、面積506㎡","structure_material":"鉄筋コンクリート造","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0131","desc":"遠藤川取水堰堤の右岸に位置する。長さ５１ｍ，幅７．３ｍの鉄筋コンクリート造構造物。水路を川から隔てる西側壁は，川側を花崗岩の谷積で築き，北側壁には排砂門を設ける。流れが早く土砂を含みやすい渓流上流部に構築され，発電用水の効果的浄化を行う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006047"},{"id":"00006048","register_sub_id":"101","register_pk":"107033","name":"平作原発電所遠藤原川取水堰堤","kana":"へいさくばらはつでんしょえんどうばらがわしゅすいえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字遠藤地先","lat":35.28634524,"lng":133.99511788,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長8.2m、堤高2.4m、制水門付","structure_material":"重力式コンクリート造堰堤","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0132","desc":"遠藤川水路に合流する遠藤原川水路の取水堰堤。堤長８．２ｍ，堤高２．４ｍ，下流法勾配８分とした越流式の重力式コンクリート造堰堤で，表面モルタル塗仕上げとした２門の制水門を右岸に配する。長さ７．５ｍに及ぶ水叩きを一体的に築き，洗掘を防ぐ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006048"},{"id":"00006049","register_sub_id":"101","register_pk":"107034","name":"平作原発電所遠藤原川沈砂池","kana":"へいさくばらはつでんしょえんどうばらがわちんさち","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字遠藤地先","lat":35.28630955,"lng":133.99508376,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造、面積370㎡","structure_material":"鉄筋コンクリート造","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0133","desc":"遠藤原川取水堰堤の右岸に位置する。長さ５５ｍ，幅５．５ｍの長細い平面形状をした鉄筋コンクリート造構造物で，水路と川を隔てる西側壁の中央部には排砂門を設ける。山の斜面が迫り出す東側と南側では側壁の上に谷積の擁壁を築き，土砂の流入を防ぐ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006049"},{"id":"00005989","register_sub_id":"101","register_pk":"106974","name":"平作原発電所恩原貯水池堰堤","kana":"へいさくばらはつでんしょおんばらちょすいちえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字恩原山地先","lat":35.30061628,"lng":133.98676278,"geo_status":"db","era":"昭和3／昭和27嵩上","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"バットレス式鉄筋コンクリート造堰堤、堤長94m、堤高24m","structure_material":"バットレス式鉄筋コンクリート造堰堤","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0134","desc":"遠藤川取水堰堤より約１．７ｋｍ北方に位置する。遮水壁を扶壁で支える，堤長９４ｍ，堤高２４ｍのバットレス式鉄筋コンクリート造堰堤。「耐震池壁」に係る物部長穂の研究成果をいち早く採り入れ，躯体軽量化と資材減量化が図られた類例の少ない形式の堰堤。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005989"},{"id":"00005990","register_sub_id":"101","register_pk":"106975","name":"平作原発電所恩原貯水池堰堤余水路","kana":"へいさくばらはつでんしょおんばらちょすいちえんていよすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字恩原山地先","lat":35.30018635,"lng":133.98700686,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造、延長132m","structure_material":"鉄筋コンクリート造","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0135","desc":"恩原貯水池の余水を堰頂右岸より堤体下部の吉井川水系恩原川に導く。延長１３２ｍ，敷幅約４ｍ規模で，石造擁壁で補強されたほぼ４割勾配の斜面に，鉄筋コンクリート造壁体を立ち上げる。水路の上部と下部で緩やかに湾曲させて水勢を弱める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005990"},{"id":"00006044","register_sub_id":"101","register_pk":"107029","name":"平作原発電所幹線水路沈砂池","kana":"へいさくばらはつでんしょかんせんすいろちんさち","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字恩原山地先","lat":35.29962194,"lng":133.98720537,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造、面積85㎡","structure_material":"鉄筋コンクリート造","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0136","desc":"恩原貯水池堰堤より約２７０ｍ下流に位置する。面積８５㎡で，ほぼ長方形平面の鉄筋コンクリート造構造物。山の斜面が迫り出す西側と南側には，鉄筋コンクリートスラブを張り出して上部を覆い，周辺からの土砂の流入を防ぐつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006044"},{"id":"00006050","register_sub_id":"101","register_pk":"107035","name":"平作原発電所水槽","kana":"へいさくばらはつでんしょすいそう","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字平作原地先","lat":35.29571019,"lng":133.95838321,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造、面積355㎡","structure_material":"鉄筋コンクリート造","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0137","desc":"幹線水路沈砂池の約２．３ｋｍ下流に位置する。長辺約２５ｍ，短辺約１０ｍ規模，ほぼ長方形平面の鉄筋コンクリート造構造物で，余水路と平行する北側壁の中央には排砂門を設ける。他の構造物と同様，浅野及び小野田セメント社製の良質のセメントを用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006050"},{"id":"00006052","register_sub_id":"101","register_pk":"107037","name":"平作原発電所鉄管路擁壁及び本館擁壁","kana":"へいさくばらはつでんしょてっかんろようへきおよびほんかんようへき","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字平作原1878","lat":35.29542863,"lng":133.95853163,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"石造、総延長68m","structure_material":"石造","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0139","desc":"本館と水槽を結ぶ鉄管路の脇に築かれた延長１７ｍの擁壁と，本館の西側及び北側に築かれた折曲り延長５１ｍの擁壁からなり，いずれも花崗岩の谷積とする。平地の少ない山間部に施設を建設するために必要な構造物で，地形状況に沿って高さを変えた外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006052"},{"id":"00006051","register_sub_id":"101","register_pk":"107036","name":"平作原発電所本館","kana":"へいさくばらはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町上齋原字平作原1878","lat":35.29566396,"lng":133.95852706,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積338㎡、放水路付","structure_material":"鉄筋コンクリート造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"33 － 0138","desc":"水槽の約３３０ｍ下流に位置する。鉄筋コンクリート造で発電機及び配電盤室を収める桁行１２ｍ，梁間１４ｍ規模の切妻造の建屋に，開閉器室と旧変電器室を収め，北壁に縦長窓をもつ陸屋根の建屋を接続する。機能に即した基盤施設らしい外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006051"},{"id":"00004627","register_sub_id":"101","register_pk":"105617","name":"三野浄水場緩速ろ過池","kana":"みのじょうすいじょうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区三野1-2-1","lat":34.68909003,"lng":133.93526342,"geo_status":"db","era":"明治38／昭和初期増築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"コンクリート造、面積2304㎡、上屋付","structure_material":"コンクリート造","registered":"2005.02.09(平成17.02.09)","register_no":"33 － 0092","desc":"取水口の約２６０ｍ西方に位置し，普通沈澱池より水を導く。上幅約３５ｍの方形平面とした二基の池からなり，各周壁をコンクリートブロックで積み，縁石には花崗岩を用いる。各池東端には，増設時に鉄筋コンクリート造タイル張のバルブ室上屋を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004627"},{"id":"00004628","register_sub_id":"101","register_pk":"105618","name":"三野浄水場旧動力室・送水ポンプ室","kana":"みのじょうすいじょうきゅうどうりょくしつ・そうすいぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区三野1-2-1","lat":34.68948,"lng":133.935608,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積529㎡、煙突付","structure_material":"煉瓦造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"33 － 0093","desc":"緩速ろ過池の北方に位置する。煉瓦造平屋建，桟瓦葺，寄棟造，平入とし，腰を花崗岩で積み，四周に半円アーチ付縦長窓を配す。西妻面脇には煉瓦造煙突の下部を残す。正面にブロークンペディメントを掲げ，木造の車寄には瓔珞飾など密度の高い意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004628"},{"id":"00004626","register_sub_id":"101","register_pk":"105616","name":"三野浄水場第一水源取水口","kana":"みのじょうすいじょうだいいちすいげんしゅすいこう","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区三野","lat":34.68879438,"lng":133.93807506,"geo_status":"db","era":"明治38／大正15増改造","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"コンクリート造及び鉄筋コンクリート造、延長33m","structure_material":"コンクリート造及び鉄筋コンクリート造","registered":"2005.02.09(平成17.02.09)","register_no":"33 － 0091","desc":"市街地の北方に位置し，旭川右岸に面して築かれる。法勾配１割で丁寧に築かれた石積護岸に，水道創設時のコンクリート造の取水口と，第二拡張工事期に建設された鉄筋コンクリート造取水口を併設する。増築部分は，大井清一の指導のもと池田篤三郎が工事担当。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004626"},{"id":"00000902","register_sub_id":"101","register_pk":"101892","name":"呉市水道局平原浄水場低区配水池","kana":"くれしすいどうきょくひらばらじょうすいじょうていくはいすいち","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県呉市平原町24","lat":34.25498439,"lng":132.58190528,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"煉瓦造配水池２基よりなる，幅37.3m，長さ71.5m","structure_material":"煉瓦造配水池２基よりなる","registered":"1998.10.09(平成10.10.09)","register_no":"34 － 0019","desc":"市民用の水道施設として市内の高台につくられた浄水場で，配水池は地下式で場内南側に位置する。煉瓦及びコンクリート造で，通路を中心に東西２つの池を配置した形式になる。南北にある煙突状の煉瓦造換気塔の意匠は独特である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000902"},{"id":"00001207","register_sub_id":"101","register_pk":"102197","name":"呉市水道局三永水源地堰堤","kana":"くれしすいどうきょくみながすいげんちえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条町下三永331","lat":34.39311935,"lng":132.74202821,"geo_status":"db","era":"昭和18","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"コンクリート造堰堤，提長145m，提高14m","structure_material":"コンクリート造堰堤","registered":"1999.07.08(平成11.07.08)","register_no":"34 － 0021","desc":"急増する水需要を賄うため、呉市に隣接する西条町の下三永川に建設された重力式コンクリート造の水道用ダム。堤長１４５ｍ、堤高１４ｍと巨大で、主堤部中央は緩やかに湾曲する。貯水量は２６４万トンで、貯水池周辺は公園化し花の名所として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001207"},{"id":"00000313","register_sub_id":"101","register_pk":"101303","name":"時報塔","kana":"じほうとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市志和町志和堀字二ノ平3324-7","lat":34.51104255,"lng":132.66931496,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造，高さ7.8m","structure_material":"鉄筋コンクリート造","registered":"1997.09.03(平成9.09.03)","register_no":"34 － 0011","desc":"在郷軍人会が定時励行を目的に建設した塔状の鐘楼。上部を木造とする他はコンクリート造で，壁面に凹凸をつけ石造風につくる。鐘の上部にはサイレンが取り付き(昭和17年頃の改造)，現在でも時を告げる塔として機能しており，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000313"},{"id":"00004409","register_sub_id":"101","register_pk":"105399","name":"長江浄水場緩速ろ過池","kana":"ながえじょうすいじょうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市長江3-6-52","lat":34.41776466,"lng":133.19387916,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造、面積1845㎡","structure_material":"鉄筋コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0060","desc":"着水井から導かれた水をろ過処理するための施設。外半径４８ｍ，内半径２４ｍ，中心角１２０°で，内部を隔壁により４等分とした扇形平面の鉄筋コンクリート造構造物で，天端には花崗岩を配す。狭小地を巧みに利用した類例の少ない平面形状が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004409"},{"id":"00004408","register_sub_id":"101","register_pk":"105398","name":"長江浄水場着水井","kana":"ながえじょうすいじょうちゃくすいせい","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市長江3-6-52","lat":34.41787634,"lng":133.19366508,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造、面積5.0㎡、階段付","structure_material":"鉄筋コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0059","desc":"槇ヶ峠の頂を約１２ｍ掘り下げて築かれた尾道市創設水道の浄水池施設のひとつ。水源地より自然流下により導水された原水を受ける施設で，鉄筋コンクリート造隔壁で内部を区切り，天端には花崗岩を配す。佐野藤次郎の指導のもと水野広之進が計画設計を担当。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004408"},{"id":"00004410","register_sub_id":"101","register_pk":"105400","name":"長江浄水場配水池","kana":"ながえじょうすいじょうはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市長江3-6-52","lat":34.41790854,"lng":133.19425371,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造、面積584㎡、鉄筋コンクリート造上屋付","structure_material":"鉄筋コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0061","desc":"ろ過池と同心の半径１４ｍの円形鉄筋コンクリート構造物で内部は中央隔壁で２分される。池中心部の円井で滅菌水が注入されたろ過水を，円形２条の導流壁に沿って蛇行させることで攪拌作用を高める。円井上方にはアールデコ風の１２角形平面の上屋を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004410"},{"id":"00008573","register_sub_id":"101","register_pk":"134969","name":"長江浄水場ベンチュリー上屋","kana":"ながえじょうすいじょうべんちゅりーうわや","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市長江3-920-2","lat":34.41849257,"lng":133.19465061,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造平屋建、切妻造、建築面積5.9㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"34 － 0106","desc":"尾道市街の丘陵上にある浄水場南端に建つ。桁行二・六メートル梁間二・六メートル、鉄筋コンクリート造、切妻造妻入で、正面出入口に切妻屋根の庇を付ける。軒下や妻面に繰型風の持送りを付けるなど、木造洋風建築を鉄筋コンクリート造で表現した上屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008573"},{"id":"00004407","register_sub_id":"101","register_pk":"105397","name":"久山田貯水池堰堤","kana":"ひさやまだちょすいちえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市久山田町","lat":34.42651141,"lng":133.16511261,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"コンクリート造堰堤、堤長75m、堤高22m、副堰堤付","structure_material":"コンクリート造堰堤","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0058","desc":"市南西部を流れる門田川に建設された尾道市創設水道施設。中央に越流部を設けた堤長７５ｍ，堤高２２ｍの石張コンクリート造堰堤で，堤体右岸寄りに半円状の取水塔を張り出す。平面形状は副堰堤と同心の円弧とし，重力式とアーチ式を複合した構造形式が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004407"},{"id":"00009534","register_sub_id":"101","register_pk":"194327","name":"福山市旧佐波浄水場浄水井上屋","kana":"ふくやましきゅうさばじょうすいじょうじょうすいせいうわや","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県福山市佐波町字城山202-7","lat":34.48125792,"lng":133.34367632,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"煉瓦造及び石造平屋建、建築面積12㎡","structure_material":"煉瓦造及び石造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"34 － 0134","desc":"配水池の西側に位置する浄水井の東側中央に建つ。煉瓦造平屋建、東西三・〇メートル南北四・一メートル、高さ二・六メートルである。東面の中央に出入口、西南北の三面の中央に縦長窓を開く。簡素ながらも丁寧なつくりで、浄水場の景観に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009534"},{"id":"00009533","register_sub_id":"101","register_pk":"194326","name":"福山市旧佐波浄水場配水池","kana":"ふくやましきゅうさばじょうすいじょうはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県福山市佐波町字城山202-7他","lat":34.48134834,"lng":133.34439491,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"コンクリート造及び煉瓦造、面積929㎡","structure_material":"コンクリート造及び煉瓦造","registered":"2013.03.29(平成25.03.29)","register_no":"34 － 0133","desc":"福山市街の西方、佐波町城山に設けられた浄水場の東端に位置する。コンクリート造及び煉瓦造、東西三二メートル南北二九メートル、深さ四・七メートルの二池を東西に配する。東面と西面の中央を塔状にして点検用の出入口を開き、東面の上部に記念額を掲げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009533"},{"id":"00009535","register_sub_id":"101","register_pk":"194328","name":"福山市旧佐波浄水場門","kana":"ふくやましきゅうさばじょうすいじょうもん","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県福山市佐波町字城山202-7","lat":34.48174571,"lng":133.34427356,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"石造及び煉瓦造、間口3.9m","structure_material":"石造及び煉瓦造","registered":"2013.03.29(平成25.03.29)","register_no":"34 － 0135","desc":"浄水場の東面北寄りに開く。石造及び煉瓦造、高さ二・四メートルの門柱を二・八メートル間隔で配する。その南側に一・一メートル間隔で小振りの門柱を立てて通用門を設ける。煉瓦と石を交互に積んで縞状にした特徴的な外観をもち、浄水場施設の正面を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009535"},{"id":"00006117","register_sub_id":"101","register_pk":"107101","name":"深山変電所本館（旧椋梨川発電所本館）","kana":"みやまへんでんしょほんかん（きゅうむくなしがわはつでんしょほんかん）","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市河内町中河内字外屋山10012-3","lat":34.48076989,"lng":132.89715117,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造平屋建、スレート葺、建築面積200㎡","structure_material":"石造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"34 － 0083","desc":"市東部を流れる椋梨川沿いに建つ。桁行２０ｍ，梁間１０ｍ，切妻造，平入の石造平屋建。小屋組はキングポストトラス。壁面を瘤出仕上げの花崗岩布積で築き，四周に配した半円アーチ形開口部の間に控壁を付ける。重厚なつくりの洋風建築で山間部の近代化を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006117"},{"id":"00009379","register_sub_id":"101","register_pk":"194172","name":"岩国練武場","kana":"いわくにれんぶじょう","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県岩国市岩国3-14-35","lat":34.16314357,"lng":132.18532527,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積325㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"35 － 0069","desc":"陸軍元帥長谷川好道の邸宅跡に西面して建つ。寄棟造桟瓦葺、桁行二四メートル梁間一〇メートル、妻入で正面中央に唐破風造の玄関を付す。外部は下見板張とし、内部は演技場の東面に師範台、南面に観覧席と支度室を下屋で設ける。地域に根ざした剣道場の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009379"},{"id":"00011213","register_sub_id":"101","register_pk":"205320","name":"旧桂ヶ谷貯水池堰堤","kana":"きゅうかつらがたにちょすいちえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県山口市小郡上郷2915","lat":34.118407,"lng":131.386668,"geo_status":"db","era":"大正12／平成27改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長24m、堤高13m","structure_material":"重力式コンクリート造堰堤","registered":"2016.08.01(平成28.08.01)","register_no":"35 - 0094","desc":"椹野川水系四十八瀬川右支桂ヶ谷川に築かれた旧水道堰堤。堤長二四メートル、堤高一三メートル規模、表面石積の重力式コンクリート造堰堤。緩やかなアーチ平面と、煉瓦積で丁寧に築いた取水塔及び高欄が特徴的。中国地方につくられた初期の水道堰堤の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011213"},{"id":"00000365","register_sub_id":"101","register_pk":"101355","name":"旧桃山一号配水池監視廊入口","kana":"きゅうももやまいちごうはいすいちかんしろういりぐち","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県宇部市大字小串字開立1943","lat":33.97100299,"lng":131.25010026,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造，建築面積16㎡","structure_material":"鉄筋コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"35 － 0006","desc":"宇部市桃山の水道施設は，沖ノ山炭鉱の関連施設として建設され，後に市民用の施設となった。監視廊は，柱頭装飾がある柱形や尖頭形アーチを用いた入口の意匠に特徴がある。市街が眺望できる丘陵地にあり，市民生活の近代化の象徴として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000365"},{"id":"00000480","register_sub_id":"101","register_pk":"101470","name":"下関市水道局内日第一貯水池取水塔","kana":"しものせきしすいどうきょくうついだいいちちょすいちしゅすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県下関市大字内日上字猿山356-9","lat":34.06077804,"lng":130.95705731,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造，高さ23.1m，上部内径3.0m","structure_material":"煉瓦造","registered":"1998.01.16(平成10.01.16)","register_no":"35 － 0009","desc":"貯水池の南端にある円筒形の煉瓦造の取水塔。高さ約２０ｍ（水中部含む）で，塔頂部を御影石で固めその上部に煉瓦造の上屋（屋根は昭和４８年の改造）が取り付く。水道創設時の施設で，市民生活の近代化を知る上で貴重な施設として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000480"},{"id":"00000487","register_sub_id":"101","register_pk":"101477","name":"下関市水道局内日第２貯水池溢水隧道入口","kana":"しものせきしすいどうきょくうついだいにちょすいちいっすいずいどういりぐち","category":"生活関連","subcategory":"土木構造物","type_guess":"隧道","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県下関市大字内日上字下瀬戸1066","lat":34.06887698,"lng":130.94883616,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造アーチ坑口，高さ5.4m，トンネル高さ3.0m","structure_material":"石造アーチ坑口","registered":"1998.01.16(平成10.01.16)","register_no":"35 － 0016","desc":"第２貯水池の南端，取水塔の南方に位置する。排水用の隧道の入口で，御影石の切石で入口の馬蹄形アーチをつくり，上部に「清波」と陰刻した石造の額をはめ込む。取水塔とともに美しい水際の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000487"},{"id":"00000486","register_sub_id":"101","register_pk":"101476","name":"下関市水道局内日第二貯水池取水塔","kana":"しものせきしすいどうきょくうついだいにちょすいちしゅすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県下関市大字内日上字下瀬戸1066","lat":34.06900943,"lng":130.94933435,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造，高さ29.4m，上部内径3.0m","structure_material":"鉄筋コンクリート造","registered":"1998.01.16(平成10.01.16)","register_no":"35 － 0015","desc":"内日第１貯水池の北方に位置する第２貯水池の南にある。高さ２４ｍ（水中部を含む）の鉄筋コンクリート造の円形の塔で，上部に円形の上屋がある。上屋のドーム形屋根や周囲に巡る歩廊の高欄の意匠に特徴があり，その意匠は第１貯水池取水塔と好対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000486"},{"id":"00000481","register_sub_id":"101","register_pk":"101471","name":"下関市水道局内日貯水池事務所","kana":"しものせきしすいどうきょくうついちょすいちじむしょ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県下関市大字内日上字猿山356-9","lat":34.05954689,"lng":130.95775214,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積35㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"35 － 0010","desc":"貯水池の南方に道を挟んで建つ木造，平屋建の小規模な事務所。装飾がほとんどない簡素な意匠になるが，下見板張りの外壁，縦長の窓，入口上部の曲線状の庇など，各所に洋風の意匠を持つ。初期の水道施設の様子を示すものとして貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000481"},{"id":"00000488","register_sub_id":"101","register_pk":"101478","name":"下関市水道局水道資料室（旧日和山浄水場事務所）","kana":"しものせきしすいどうきょくすいどうしりょうしつ（きゅうひよりやまじょうすいじょうじむしょ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県下関市長崎中央町7-1","lat":33.95685624,"lng":130.93047434,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積86㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"35 － 0017","desc":"水道第３期拡張工事により，内日第２貯水池とともにつくられた日和山浄水場の施設。浄水場の北東隅に建つ。鉄筋コンクリート造，平屋建の小規模な建物で，正面入口や窓廻りの曲線模様，頂部にある庇下の幾何学的な文様等に時代の特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000488"},{"id":"00000482","register_sub_id":"101","register_pk":"101472","name":"下関市水道局高尾浄水場着水井","kana":"しものせきしすいどうきょくたかおじょうすいじょうちゃくすいせい","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県下関市春日町8-1","lat":33.95945339,"lng":130.9297659,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造，内径3.55m","structure_material":"煉瓦造","registered":"1998.01.16(平成10.01.16)","register_no":"35 － 0011","desc":"下関市の水道施設は，明治３４年に起工，３９年から通水を開始した。県内最初の水道施設で，内日第一貯水池と高尾浄水場にこの時に建設された施設が残る。着水井はそのひとつで，高尾浄水場の西端にある。煉瓦造，内径約３．６ｍの円形で，頂部に御影石をのせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000482"},{"id":"00000485","register_sub_id":"101","register_pk":"101475","name":"下関市水道局高尾浄水場配水池","kana":"しものせきしすいどうきょくたかおじょうすいじょうはいすいち","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県下関市春日町8-1","lat":33.95913962,"lng":130.93058653,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造，長さ45.5m，幅34.9m，高さ5.0m","structure_material":"煉瓦造","registered":"1998.01.16(平成10.01.16)","register_no":"35 － 0014","desc":"浄水場東に位置する。面積約１６００㎡，深さ約５ｍの池２つからなる。各池を１２分割し，上部に煉瓦造のアーチ屋根をつくり，さらに上に土をかぶせる。北側面には高さ約１ｍの煉瓦壁をみせる。明治期の大型煉瓦造構造物として技術的にみるべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000485"},{"id":"00000483","register_sub_id":"101","register_pk":"101473","name":"下関市水道局高尾浄水場４号円形濾過池","kana":"しものせきしすいどうきょくたかおじょうすいじょうよんごうえんけいろかち","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県下関市春日町8-1","lat":33.95953384,"lng":130.93026471,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造，直径40.6m，深さ3.0m","structure_material":"煉瓦造","registered":"1998.01.16(平成10.01.16)","register_no":"35 － 0012","desc":"高尾浄水場の北に位置する。直径４０．６ｍ，高さ３．０ｍの巨大な人工池で，水深は１．２ｍである。煉瓦造で頂部に御影石をのせる形態は着水井と類似する。市民生活の近代化の様子を示す施設として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000483"},{"id":"00000484","register_sub_id":"101","register_pk":"101474","name":"下関市水道局高尾浄水場４号円形濾過池付設調節井","kana":"しものせきしすいどうきょくたかおじょうすいじょうよんごうえんけいろかちふせつちょうせつせい","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県下関市春日町8-1","lat":33.95936489,"lng":130.93053825,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造，建築面積5.6㎡","structure_material":"煉瓦造","registered":"1998.01.16(平成10.01.16)","register_no":"35 － 0013","desc":"高尾浄水場の濾過池と配水池の間に位置する。平面円形で煉瓦造の小規模な建物だが，御影石の軒蛇腹や１２角形の屋根を用いた特異な形態を持ち，施設内ではひときわ目立つ存在である。なお，屋根及び北側の張り出しは後の改造（屋根は当初の形に似せる）。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000484"},{"id":"00000366","register_sub_id":"101","register_pk":"101356","name":"桃山配水計量室","kana":"ももやまはいすいけいりょうしつ","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県宇部市大字小串字福富175-9","lat":33.97101879,"lng":131.25007271,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造平屋建，建築面積30㎡","structure_material":"煉瓦造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"35 － 0007","desc":"煉瓦造平屋建で八角形の平面を持つ小規模な建物。傾斜地に広がる住宅地のなかにあり，「六角堂」の愛称で広く親しまれている。現在は鉄筋コンクリート造の陸屋根がかかっているが，建設当初には八角錐形の屋根を頂いていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000366"},{"id":"00000709","register_sub_id":"101","register_pk":"101699","name":"山口市水道局電気室（旧宮島水源地ポンプ室）","kana":"やまぐちしすいどうきょくでんきしつ（きゅうみやじますいげんちぽんぷしつ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県山口市宮島町1012","lat":34.16514073,"lng":131.4817076,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造半地下１階地上１階建，建築面積72㎡","structure_material":"鉄筋コンクリート造半地下１階地上１階建","registered":"1998.09.02(平成10.09.02)","register_no":"35 － 0019","desc":"創設山口市水道の記念建造物。取水井に集めた地下伏流水を吸引して象頭山の配水池へ送水するための施設。鉄筋コンクリート造，地下室付平屋，陸屋根の建物で，スクラッチタイルを貼る。小品ながら，開口部窓を２連アーチとし，端正な姿形に仕上げている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000709"},{"id":"00000905","register_sub_id":"101","register_pk":"101895","name":"徳島市水道局佐古配水場源水井","kana":"とくしましすいどうきょくさこはいすいじょうげんすいせい","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県徳島市南佐古6-3-11","lat":34.07449959,"lng":134.52755567,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造上屋，内部源水井附属，建築面積21㎡","structure_material":"鉄筋コンクリート造上屋","registered":"1998.10.09(平成10.10.09)","register_no":"36 － 0008","desc":"鉄筋コンクリート造の箱形の井に上屋をかけた形式。上屋は方形平面で，外壁に煉瓦を用いて，パラペットや窓廻り等の要所に花崗岩を配す，ポンプ場と同様の意匠になる。市民生活の近代化の様子を物語る貴重な建物のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000905"},{"id":"00000906","register_sub_id":"101","register_pk":"101896","name":"徳島市水道局佐古配水場集合井","kana":"とくしましすいどうきょくさこはいすいじょうしゅうごうせい","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県徳島市南佐古6-3-11","lat":34.0741179,"lng":134.527908,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造上屋，内部集合井附属，高さ5.1m","structure_material":"鉄筋コンクリート造上屋","registered":"1998.10.09(平成10.10.09)","register_no":"36 － 0009","desc":"鉄筋コンクリート造の井の側壁上縁に上屋をかけた形になる。上屋は，ポンプ場，源水井上屋と構造・意匠は類似するが，平面を円形とする点や入口上部の浮き彫り装飾，壁面の柱型，窓上部の枠石等の意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000906"},{"id":"00000172","register_sub_id":"101","register_pk":"101162","name":"徳島市水道局佐古配水場ポンプ場","kana":"とくしましすいどうきょくさこはいすいじょうぽんぷじょう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県徳島市南佐古6-3-11","lat":34.07408687,"lng":134.52803814,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造平屋建，瓦葺，建築面積272㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"36 － 0001","desc":"煉瓦造のポンプ場で，イギリス積みの煉瓦壁で四周を囲む。内部は一室で漆喰仕上げとし，小屋組は軽量鉄骨のトラス組である。外観は簡素であるが，入り口部分のうち特にペディメント風の飾りは特異である。「佐古の浄水場」として広く市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000172"},{"id":"00002441","register_sub_id":"101","register_pk":"103431","name":"唐櫃岡の清水共同用水場","kana":"からとおかのしみずきょうどうようすいじょう","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡土庄町豊島唐櫃字東伏1261-1","lat":34.485672,"lng":134.085449,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造、水槽・排水路・擁壁よりなる、面積75㎡","structure_material":"石造","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0057","desc":"小豆島西方の豊島にある生活用の水場。台形平面を有し，雛壇状の花崗岩布積で壁面をつくる。湧水を上部の貯水槽から３連小水槽，大水槽に流し，各水槽に異なる用途を充てる。余水は脇の水路から町の下水路に通ずる。往時からの生活環境を物語る貴重な建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002441"},{"id":"00011219","register_sub_id":"101","register_pk":"205326","name":"旧御殿水源地北門門柱","kana":"きゅうごてんすいげんちきたもんもんちゅう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市鶴市町字御殿1360","lat":34.334545,"lng":134.01546,"geo_status":"db","era":"大正7頃","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造、間口2.9m、土塁留付","structure_material":"石造","registered":"2016.08.01(平成28.08.01)","register_no":"37 - 0417","desc":"水源地の北東端に位置する。間口三・三メートルで配された花崗岩製の門柱と、土塁の土留用石垣からなる。門柱は笠石、柱頭部、柱身部よりなり、笠石上面は扁平な四角錐形に仕上げる。隣接する官舎への通用口として利用された、質実なつくりの外構施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011219"},{"id":"00000174","register_sub_id":"101","register_pk":"101164","name":"旧御殿水源地事務所","kana":"きゅうごてんすいげんちじむしょ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市鶴市町御殿1360","lat":34.33444701,"lng":134.01530799,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積145㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"37 － 0006","desc":"高松の近代的水道施設の創設当時から事務室、宿直室として使われている。Ｌ字型の平面構成をとり，出隅角部を入り口とする。平屋建の小規模な建物であるが，ポンプ所と類似する意匠をもち，あわせて近代化のシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000174"},{"id":"00011218","register_sub_id":"101","register_pk":"205325","name":"旧御殿水源地集水埋渠東方人孔","kana":"きゅうごてんすいげんちしゅうすいまいきょとうほうじんこう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市鶴市町字御殿1360先","lat":34.334426,"lng":134.014869,"geo_status":"db","era":"大正4頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造、面積6.4㎡","structure_material":"煉瓦造","registered":"2016.08.01(平成28.08.01)","register_no":"37 - 0416","desc":"香東川右岸に位置する。川を横断する暗渠の東端に建つ八・五メートル高の煉瓦構造物で、天端に花崗岩の切石を貼る。川とほぼ平行に築かれ、両端を水切り状とする。高松市創設水道施設の一つで、川の伏流水を利用した水源地施設としては我が国最初期のもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011218"},{"id":"00011217","register_sub_id":"101","register_pk":"205324","name":"旧御殿水源地倉庫","kana":"きゅうごてんすいげんちそうこ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市鶴市町字御殿1360","lat":34.33455,"lng":134.015196,"geo_status":"db","era":"大正6／昭和62改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"37 - 0415","desc":"水源地の北西端に位置する。桁行一五メートル、梁間五・六メートル、外装横板張の木造平屋建で、東西北面に鉄格子付高窓を設ける。内部は南北二室からなり、南室ではキングポストトラスを表す。建ちを高くし内部空間を広くとる倉庫建築らしい簡素な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011217"},{"id":"00000173","register_sub_id":"101","register_pk":"101163","name":"旧御殿水源地喞筒場","kana":"きゅうごてんすいげんちそくとうじょう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市鶴市町御殿1360","lat":34.33415552,"lng":134.01522414,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積249㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"37 － 0005","desc":"平屋建・瓦葺で，Ｔ字型にわずかな張り出しがある平面をもつ。本来ポンプ所として建てられたが，事務所風の外観を見せる。小規模で簡素ながら，半円形窓を配した妻面等の洋風の意匠に特徴が見られ，市民生活の近代化を象徴する建物として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000173"},{"id":"00011220","register_sub_id":"101","register_pk":"205327","name":"旧御殿水源地擁壁","kana":"きゅうごてんすいげんちようへき","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市鶴市町字御殿1360","lat":34.3346452,"lng":134.01533043,"geo_status":"db","era":"大正7頃","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造、総延長105m","structure_material":"石造","registered":"2016.08.01(平成28.08.01)","register_no":"37 - 0418","desc":"水源地の北・東面を区画する石積擁壁。花崗岩を用いて谷積で精緻に積み上げたもので、下部はコンクリートで覆われている。折れ曲がり延長一〇五メートル、高さ約二・二メートル、法勾配三分とする。創設当初の姿を今に伝え、地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011220"},{"id":"00008596","register_sub_id":"101","register_pk":"134992","name":"旧端出場水力発電所","kana":"きゅうはでばすいりょくはつでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県新居浜市立川町594","lat":33.90154417,"lng":133.31084973,"geo_status":"db","era":"明治45年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積528㎡","structure_material":"煉瓦造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"38 － 0095","desc":"足谷川右岸の急峻な傾斜地に建つ。建築面積五二八平方メートルの煉瓦造、鉄板葺で越屋根二ヶ所を設ける。イギリス積とし、平側は柱型を現し、上に二連のアーチ窓、下には大きく欠円アーチ窓を穿つ。煉瓦と要所に配される石のコントラストが深緑の山肌に映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008596"},{"id":"00009847","register_sub_id":"101","register_pk":"195676","name":"向野堅一記念館（旧讃井病院）","kana":"こうのけんいちきねんかん（きゅうさぬいびょういん）","category":"生活関連","subcategory":"建築物","type_guess":"記念碑","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県直方市大字直方594-3他","lat":33.74403024,"lng":130.72806397,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積227㎡、塔屋付","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"40 － 0103","desc":"角地に建つＬ字形平面の木造二階建で、隅部を塔屋とする。正面に玄関ポーチを構え、左右張出し部に大オーダーを表し、頂部に台形のパラペットを飾る。内部は一階がもと診療室や薬局などで、二階に和室を配する。ゼツェッション意匠を基調とする、もと医院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009847"},{"id":"00010532","register_sub_id":"101","register_pk":"199472","name":"ジョーキュウ醤油若宮神社","kana":"じょーきゅうしょうゆわかみやじんじゃ","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"福岡県","address":"福岡県福岡市中央区大名1-349-1","lat":33.58811,"lng":130.395226,"geo_status":"db","era":"寛政4(1792)","year":1792,"year_source":"db","year_min":1792,"year_max":1792,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積0.3㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0124","desc":"敷地東辺中央の切石積檀上に建つ、一間社見世棚造、銅板葺で、見世棚社殿には珍しい切妻造妻入とする。身舎は板壁とし、庇柱を木鼻付頭貫で固め、柱上に大斗と実肘木を載せて虹梁と桁を受け、虹梁上に蟇股を置く。簡素な小社ながら細部に時代的特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010532"},{"id":"00009850","register_sub_id":"101","register_pk":"195679","name":"直方谷尾美術館茶室鉄牛庵","kana":"のおがたたにおびじゅつかんちゃしつてつぎゅうあん","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県直方市殿町534-1他","lat":33.74328903,"lng":130.72869484,"geo_status":"db","era":"昭和16頃","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"40 － 0106","desc":"細長い敷地の東奥部に建つ。和館と渡廊下を介して繋ぎ、南側に庭園を控える。切妻造桟瓦葺で内外観とも数寄屋意匠とし、外壁は中塗仕上げとする。平面は東端に四畳半茶室をおき、手前に水屋、六畳の待合を直列させる。茶の湯を嗜んだ施主の好みを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009850"},{"id":"00009848","register_sub_id":"101","register_pk":"195677","name":"直方谷尾美術館洋館（旧奥野医院）","kana":"のおがたたにおびじゅつかんようかん（きゅうおくのいいん）","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県直方市殿町534-1他","lat":33.74331759,"lng":130.72827129,"geo_status":"db","era":"昭和16頃／平成期改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積265㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"40 － 0104","desc":"正面中央の玄関ポーチにコンポジット式円柱を立ててコーニスを受け、玄関ホールにはコリント式円柱を配する。周囲の外壁はタイル貼で柱形を表し、縦長窓を連続させ、また側面に半円形平面の応接間を張出すなど、古典様式とモダニズムを融合した外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009848"},{"id":"00009849","register_sub_id":"101","register_pk":"195678","name":"直方谷尾美術館和館（旧奥野家住宅主屋）","kana":"のおがたたにおびじゅつかんわかん（きゅうおくのけじゅうたくしゅおく）","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県直方市殿町534-1他","lat":33.74324382,"lng":130.72854374,"geo_status":"db","era":"昭和16頃／平成期改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造及び土蔵造2階建、瓦葺、建築面積259㎡","structure_material":"木造及び土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"40 － 0105","desc":"洋館後方に建つ和風住宅で、洋館接続部に玄関を構える。北東寄りの二階建部分には、もとの客間などがあり、南西隅に二階建土蔵の収蔵庫を附属する。落着いた佇まいの住宅で、洋風意匠の医院部分と好対照をなし、大正期の直方における医院建築の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009849"},{"id":"00008216","register_sub_id":"101","register_pk":"132741","name":"小ヶ倉ダム","kana":"こがくらだむ","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県長崎市上戸町4-397-4他","lat":32.7158806,"lng":129.87625808,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"重力式コンクリート造堰堤、堤高41m、堤長136m、副堰堤及び水路付","structure_material":"重力式コンクリート造堰堤","registered":"2010.04.28(平成22.04.28)","register_no":"42 － 0089","desc":"市街地の南方に位置する。堤長１３６ｍ、堤高４１ｍの重力式コンクリート造堰堤で、越流式とし、表面は花崗岩の布積とする。下流には石積護岸及びアーチ式コンクリート造の副堰堤を設ける。建設当時、水道ダムとしてわが国最高の堤高を誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008216"},{"id":"00008217","register_sub_id":"101","register_pk":"132742","name":"小ヶ倉ダム管理橋","kana":"こがくらだむかんりきょう","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県長崎市上戸町4-367地先","lat":32.71610006,"lng":129.87544609,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造、橋長9.1m、幅員2.2m","structure_material":"鉄筋コンクリート造","registered":"2010.04.28(平成22.04.28)","register_no":"42 － 0090","desc":"ダムから約９０ｍ下流に位置し、放水路に架かる。橋長９．１ｍ、幅員２．２ｍの鉄筋コンクリート造単桁橋。橋台、橋桁の側面などに幾何学模様をあしらう。長崎市第２回水道拡張事業の一環として建設された水源地の管理用構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008217"},{"id":"00000177","register_sub_id":"101","register_pk":"101167","name":"熊本市水道記念館（旧八景水谷貯水池ポンプ場）","kana":"くまもとしすいどうきねんかん（きゅうはけのみやちょすいちぽんぷじょう）","category":"生活関連","subcategory":"建築物","type_guess":"記念碑","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市八景水谷1-7-3","lat":32.84230632,"lng":130.72172702,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造平屋建，建築面積99㎡","structure_material":"煉瓦造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"43 － 0004","desc":"八景水谷の湧水地に設けられたポンプ場で，平面は正方形になる。外観の意匠は，窓廻りの縁取りや煉瓦壁と上部のモルタル壁の取合せ，寄棟屋根の四面に反曲線の組み合わせによる特異な小屋根を張り出させる等，表現派の装いをした建物で市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000177"},{"id":"00000316","register_sub_id":"101","register_pk":"101306","name":"別府市朝見浄水場集合井室","kana":"べっぷしあさみじょうすいじょうしゅうごうせいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県別府市朝見2-4141","lat":33.26979798,"lng":131.49210666,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"鉄筋コンクリート造，建築面積14㎡","structure_material":"鉄筋コンクリート造","registered":"1997.09.03(平成9.09.03)","register_no":"44 － 0012","desc":"八角形の平面になる鉄筋コンクリート造の建屋で，球状の屋根を持つ。正面入口は，円弧状のペディメントを載せたポーチ付きで小規模ながら本格的な造りになる。外壁は石積み風の目地を入れる。独特の外観は，生活近代化の象徴として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000316"},{"id":"00000317","register_sub_id":"101","register_pk":"101307","name":"別府市朝見浄水場配水池","kana":"べっぷしあさみじょうすいじょうはいすいち","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県別府市朝見2-4130-1","lat":33.26995485,"lng":131.49182383,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"鉄筋コンクリート造，建築面積985㎡","structure_material":"鉄筋コンクリート造","registered":"1997.09.03(平成9.09.03)","register_no":"44 － 0013","desc":"別府市の生活近代化を図るため，第１期工事として建設された鉄筋コンクリート造の配水池。石製の笠木を持つなど趣のある造形になる。完成当時２万５千人分の給水が可能であった。別府市の水道史の証として，浄水場内に大切に保存されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000317"},{"id":"00000318","register_sub_id":"101","register_pk":"101308","name":"別府市朝見浄水場配水池北出入口","kana":"べっぷしあさみじょうすいじょうはいすいちきたでいりぐち","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県別府市朝見2-4130-1","lat":33.27001211,"lng":131.491862,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造，建築面積13㎡","structure_material":"鉄筋コンクリート造","registered":"1997.09.03(平成9.09.03)","register_no":"44 － 0014","desc":"配水池に敷設された管理用の出入り施設。南北２カ所に設けられているが，ともに独立した鉄筋コンクリート造の建屋である。小規模ながら，出入り口に方形の基礎をおいた柱型を配し，独特の柱頭飾をおく等特徴的な細部意匠の建屋として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000318"},{"id":"00000319","register_sub_id":"101","register_pk":"101309","name":"別府市朝見浄水場配水池南出入口","kana":"べっぷしあさみじょうすいじょうはいすいちみなみでいりぐち","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県別府市朝見2-4130-1","lat":33.26989281,"lng":131.49178565,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造，建築面積13㎡","structure_material":"鉄筋コンクリート造","registered":"1997.09.03(平成9.09.03)","register_no":"44 － 0015","desc":"浄水場の敷地の西端に位置する配水池の南北側面の２カ所に敷設された管理用の出入り口の一つ。平面は矩形の建屋で，壁面を洗い出しとし，側面にアーチ型の窓枠を設けるなど小規模ながら建築として扱っている。配水池とともに記念的な施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000319"},{"id":"00000320","register_sub_id":"101","register_pk":"101310","name":"別府市朝見浄水場量水室","kana":"べっぷしあさみじょうすいじょうりょうすいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県別府市朝見2-4075-5","lat":33.27218987,"lng":131.49381245,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造，建築面積17㎡","structure_material":"鉄筋コンクリート造","registered":"1997.09.03(平成9.09.03)","register_no":"44 － 0016","desc":"高台に立地する浄水場からやや離れた北側の低地に建てられた鉄筋コンクリート造の小規模な建物。基壇風の基礎に正面１間，側面２間に見せる柱頭飾りを置く列柱を配し，アーチ形の窓枠を設けるなど古典様式になる独特の外観は，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000320"},{"id":"00000179","register_sub_id":"101","register_pk":"101169","name":"黒北発電所","kana":"くろきたはつでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市清武町大字船引字川平3544","lat":31.8769526,"lng":131.35187319,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積78㎡","structure_material":"石造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"45 － 0001","desc":"大分清武川水系を利用した石造，平屋建の水力発電所の建屋。外観に石積みの目地を表し，縦長の窓やアーチ形の明かり取り窓を用いる等小規模ながら洋風の本格的な意匠が用いられている。現存する九州最古の水力発電所として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000179"},{"id":"00004091","register_sub_id":"101","register_pk":"105081","name":"塚原ダム","kana":"つかばるだむ","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県東臼杵郡美郷町西郷区山三箇字野々尾～諸塚村大字七ツ山字谷口","lat":32.50518697,"lng":131.30025852,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長215m、堤高87m","structure_material":"重力式コンクリート造堰堤","registered":"2004.03.02(平成16.03.02)","register_no":"45 － 0025","desc":"耳川中流域に建設された水力発電用堰堤。堤体中央部に８門のテンターゲートを配し，天端にはバトルメント付きの小塔を設ける。昭和前期の最新コンクリート技術を結集し，我国最大高８７ｍを実現したコンクリートダム。山本格設計，吉田徳次郎指導，間組施工。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004091"},{"id":"00008606","register_sub_id":"101","register_pk":"135002","name":"九州電力妙見発電所１号機ヘッドタンク","kana":"きゅうしゅうでんりょくみょうけんはつでんしょ１ごうきへっどたんく","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県霧島市牧園町宿窪田字葉切4224-6","lat":31.81364907,"lng":130.75810302,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"石造、面積76㎡","structure_material":"石造","registered":"2011.01.26(平成23.01.26)","register_no":"46 － 0093","desc":"本館背後の急斜面上の中腹に位置する。中津川から取った水のヘッドタンクで、一五〇メートル長を越える水圧鉄管で１号機へ送る。切石を円筒形に階段状に積み上げたタンクで、面積七六平方メートル。水圧鉄管両側には石積により擁壁を造り、階段を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008606"},{"id":"00008607","register_sub_id":"101","register_pk":"135003","name":"九州電力妙見発電所２号機及び３号機ヘッドタンク","kana":"きゅうしゅうでんりょくみょうけんはつでんしょ２ごうきおよび３ごうきへっどたんく","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県霧島市牧園町宿窪田字葉切4224-6","lat":31.81333736,"lng":130.75756124,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"石造、面積478㎡","structure_material":"石造","registered":"2011.01.26(平成23.01.26)","register_no":"46 － 0094","desc":"本館背後の急斜面、１号機ヘッドタンクより低い位置に設ける。石を階段状に積み上げた矩形のタンクで、天降川から取水し、２号機と３号機へ送る。道路下に水圧鉄管を通し、そこに石造アーチを設ける。本館と一連の石造タンクが残り、歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008607"},{"id":"00008605","register_sub_id":"101","register_pk":"135001","name":"九州電力妙見発電所本館","kana":"きゅうしゅうでんりょくみょうけんはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県霧島市牧園町宿窪田字葉切4230-1","lat":31.81274363,"lng":130.75703431,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"石造2階一部3階建、瓦葺、建築面積403㎡、放水口付","structure_material":"石造2階一部3階建","registered":"2011.01.26(平成23.01.26)","register_no":"46 － 0092","desc":"天降川に面する敷地に建つ。桁行二九メートル梁間一四メートルとし、二階建の発電機室棟と三階建の配電盤室棟よりなり、発電機室棟と川の間には三条の放水路を設ける。江戸切り仕上げの溶結凝灰岩を全体に積み上げた、重厚な外観をもつ大規模な石造建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008605"},{"id":"00005390","register_sub_id":"101","register_pk":"106378","name":"旧曽木発電所ヘッドタンク","kana":"きゅうそぎはつでんしょへっどたんく","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県伊佐市大口宮人地内","lat":32.01118896,"lng":130.56331181,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"石造、面積290㎡","structure_material":"石造","registered":"2006.03.02(平成18.03.02)","register_no":"46 － 0022","desc":"本館より北東の高台に位置する。発電用水の流下水量を調節するための発電所関連施設。切石積の構造物で，モルタル仕上げとした法面には，水圧鉄管を据えるための穴を４箇所設ける。残存する鉄管用礎石を含む。九州に築かれた初期の水路式発電所施設の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005390"},{"id":"00005389","register_sub_id":"101","register_pk":"106377","name":"旧曽木発電所本館","kana":"きゅうそぎはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県伊佐市大口宮人地内","lat":32.01101354,"lng":130.5631239,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"煉瓦造、面積652㎡","structure_material":"煉瓦造","registered":"2006.03.02(平成18.03.02)","register_no":"46 － 0021","desc":"市南部に位置する旧水力発電所施設で，発電機棟とそれに直交する事務棟からなる。外壁イギリス積とし，上部を欠円アーチとした開口部を密に配する。妻には丸窓を設けコーニスを階段状につくるなど変化を付ける。九州南部の大規模煉瓦建築として最初期のもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005389"},{"id":"00006249","register_sub_id":"101","register_pk":"107233","name":"旧東洋製糖下阪浴場風呂場","kana":"きゅうとうようせいとうしもさかよくじょうふろば","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港10-2","lat":25.95474856,"lng":131.28758553,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"石造、建築面積141㎡","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0046","desc":"北大東島西北部に位置する。正面１１ｍ，奥行９．８ｍ規模，石灰岩の布積で築かれた矩形平面の石造構造物。内部には大小２槽のコンクリート造浴槽を南壁面沿いに設け，壁を隔ててボイラー室を設ける。燐鉱採掘時代の島住民の生活を物語る遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006249"},{"id":"00006250","register_sub_id":"101","register_pk":"107234","name":"旧東洋製糖下阪浴場水取場","kana":"きゅうとうようせいとうしもさかよくじょうみずとりば","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港10-2","lat":25.95506968,"lng":131.28740203,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"コンクリート造、面積671㎡、コンクリート造貯水タンク2基付","structure_material":"コンクリート造","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0047","desc":"下阪浴場風呂場の南側に位置する。燐鉱労働者と地域住民が利用した浴場の施設。緩やかに傾斜する斜面に約５００㎡のモルタル敷の床を設け，その北側に２槽の貯水タンクを掘り込む。水源に乏しい離島の水利用の仕組みを知る上で貴重な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006250"},{"id":"00006256","register_sub_id":"101","register_pk":"107240","name":"旧東洋製糖社員浴場貯水タンク","kana":"きゅうとうようせいとうしゃいんよくじょうちょすいたんく","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港24-1","lat":25.9553255,"lng":131.2876989,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"石造、面積101㎡","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0049","desc":"社員浴場風呂場の北東に位置する。深さ２．５ｍ，頂部で内径８．９ｍ，外径１０．６ｍとした貯水タンクで，内壁をモルタル塗，外壁を石灰岩の布積で築き，風呂場寄りに高架タンクの基部を残す。風呂場とともに，島の燐鉱採掘時代の歴史的景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006256"},{"id":"00006255","register_sub_id":"101","register_pk":"107239","name":"旧東洋製糖社員浴場風呂場","kana":"きゅうとうようせいとうしゃいんよくじょうふろば","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港24-1","lat":25.95530612,"lng":131.28777295,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"鉄筋コンクリート造平屋建、建築面積51㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0048","desc":"北大東島西北部に位置する。正面８．７ｍ，奥行５．９ｍ規模，矩形平面の鉄筋コンクリート造平屋建で，欠円アーチ形のスラブで屋根をつくる特徴的な外観。内部は均等に３室に分かれ，各室に個別の入口を設ける。旧東洋製糖の本部施設に近接する共同浴場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006255"},{"id":"00000423","register_sub_id":"101","register_pk":"101413","name":"潮平ガー","kana":"すんじゃがー","category":"生活関連","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"沖縄県","address":"沖縄県糸満市字潮平136","lat":26.14357725,"lng":127.67708826,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"石造井泉，水溜部・作業場・石段・法面石垣・香炉2基からなる，面積314㎡","structure_material":"石造井泉","registered":"1997.12.12(平成9.12.12)","register_no":"47 － 0001","desc":"緩やかな傾斜地につくられた大規模な井泉。屋根付の水溜部，石敷の作業場，作業場に至る石段，法面石垣からなり，水溜部及びその後方に香炉２基が据えられている。大型の切石を積んだ構造は沖縄によくみられるもので，生活用水に利用され広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000423"},{"id":"00005534","register_sub_id":"101","register_pk":"106522","name":"なごみの塔","kana":"なごみのとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"沖縄県","address":"沖縄県八重山郡竹富町字竹富","lat":24.330614,"lng":124.08535858,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"鉄筋コンクリート造、高さ4.5m、面積51㎡","structure_material":"鉄筋コンクリート造","registered":"2006.03.27(平成18.03.27)","register_no":"47 － 0016","desc":"竹富島の西集落のほぼ中央の赤山公園内に位置し，高さ６ｍの丘の上に石垣等を築き，その上に設けられた高さ４ｍの鉄筋コンクリート造の物見塔である。太さ０．６ｍの柱の上に物見台を作り，８段の階段を付ける。島民に愛され，島のシンボル的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005534"}];
